INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C1','soc',4,1,'u1',1,'지도의 뜻과 필요성 — 높은 곳에서 내려다보면 지역이 한눈에 보이지만 장소의 정확한 위치와 거리는 알기 어려움 · 지도는 하늘에서 내려다본 땅의 모습을 일정하게 줄여 정해진 약속에 따라 나타낸 그림 · 선·색·숫자·모양 표시는 모두 약속이라 일정한 정보를 얻음 · 사진은 실제 모습이 다 담겨 복잡하고 지도는 약속된 기호로 장소를 쉽게 찾음 · 지도 제작 기술자',ARRAY['[4사05-01] 지도의 기본 요소(방위·기호와 범례·등고선·축척)를 이해하고 지도를 읽고 활용한다(차시 머리 표기 · 문구 초안)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C2','soc',4,1,'u1',2,'방위와 방위표 — 앞·뒤·오른쪽·왼쪽은 보는 방향에 따라 달라져 일정한 기준이 필요 · 방위 = 동서남북의 방향으로 나타낸 위치 · 방위표로 알 수 있고 방위표가 없으면 위쪽이 북쪽(아래 남·오른쪽 동·왼쪽 서) · 8방위(북동·남동·남서·북서) · 방위를 쓰면 누가 어디서 보아도 위치가 같게 전해짐 · 실제 북쪽은 나침반으로',ARRAY['[4사05-01] 지도의 기본 요소(방위·기호와 범례·등고선·축척)를 이해하고 지도를 읽고 활용한다(차시 머리 표기 · 문구 초안)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C3','soc',4,1,'u1',3,'기호와 범례 — 기호 = 땅의 모습을 알기 쉽게 나타내려고 약속한 표시, 장소의 생김새나 특징을 본떠 만듦(제비 모양 우체국 등) · 범례 = 지도에 쓰인 기호와 그 뜻을 한곳에 모아 놓은 것 · 기호와 범례로 복잡한 땅을 간단하게 · 그림지도보다 기호지도에서 장소를 빨리 찾음 · 픽토그램 = 글자를 몰라도 누구나 이해하는 그림 문자',ARRAY['[4사05-01] 지도의 기본 요소(방위·기호와 범례·등고선·축척)를 이해하고 지도를 읽고 활용한다(차시 머리 표기 · 문구 초안)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C4','soc',4,1,'u1',4,'등고선 — 등고선 = 땅의 높이가 같은 곳을 이은 선, 옆 숫자는 높이 · 안쪽으로 갈수록 높고 가장 안쪽 작은 원이 가장 높은 곳 · 낮은 곳 초록색·높은 곳 고동색 · 간격이 좁을수록 경사가 급하고 넓을수록 완만 · 숫자가 크고 등고선이 여러 겹일수록 높은 산 · 등고선 모형을 위에서 보면 지도의 등고선',ARRAY['[4사05-01] 지도의 기본 요소(방위·기호와 범례·등고선·축척)를 이해하고 지도를 읽고 활용한다(차시 머리 표기 · 문구 초안)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C5','soc',4,1,'u1',5,'축척 — 축척 = 지도에서 실제 거리를 줄여 나타낸 정도, 축척 막대로 앎 · 지역을 종이에 나타내려면 실제보다 줄임 · 실제 거리는 축척 확인 → 축척 막대자로 지도상 거리 재기 · 1 cm = 1 km 이면 3 cm 는 3 km · 많이 줄인 지도는 넓은 지역을 간략하게, 덜 줄인 지도는 좁은 지역을 자세하게',ARRAY['[4사05-01] 지도의 기본 요소(방위·기호와 범례·등고선·축척)를 이해하고 지도를 읽고 활용한다(차시 머리 표기 · 문구 초안)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C6','soc',4,1,'u1',6,'일상생활 속 지도 활용 — 관광 안내도(관광지 위치) · 약도(목적지까지 길을 간단히) · 버스·지하철 노선도(갈아타기 = 환승) · 길 도우미(목적지를 넣으면 좋은 길 안내) · 상황과 목적에 맞는 지도를 골라 쓰면 이동을 미리 계획 · 옛 지도 대동여지도(김정호)도 기호와 범례를 썼고 선의 굵기로 산의 크기와 높이를 나타냄',ARRAY['[4사05-01] 지도의 기본 요소(방위·기호와 범례·등고선·축척)를 이해하고 지도를 읽고 활용한다(차시 머리 표기 · 문구 초안)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C7','soc',4,1,'u1',7,'지도 요소로 지도 종합해 읽기 — 방위는 방향, 기호와 범례는 장소, 등고선은 높낮이, 축척은 실제 거리 · 요소가 모두 담긴 지도에서 방향·장소·높낮이·거리 정보를 함께 정확히 읽음 · 요소의 이름과 하는 일을 짝짓고 여러 요소를 이어 한 장소를 설명',ARRAY['[4사05-01] 지도의 기본 요소(방위·기호와 범례·등고선·축척)를 이해하고 지도를 읽고 활용한다(차시 머리 표기 · 문구 초안)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C8','soc',4,1,'u1',8,'우리 지역의 위치와 지형 — 위치 = 어떤 곳이 다른 곳을 기준으로 어디쯤 있는지, 방위와 이웃 지역으로 나타냄(날씨·인구는 위치가 아님) · 지형 = 산·강·들(평야)·바다·섬처럼 땅이 이루는 여러 가지 생김새 · 산은 우뚝 솟은 높은 땅, 들은 넓고 평평해 농사짓기 좋음 · 지형에 따라 생활 모습이 달라져 지역의 특성을 이해',ARRAY['[4사05-02] 우리 지역의 위치와 특성을 지리 정보로 탐색하고 다른 지역과 비교한다(차시 머리 표기 · 문구 초안)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C9','soc',4,1,'u1',9,'우리 지역의 면적과 인구 — 면적 = 땅이 차지하는 넓이(km²) · 인구 = 지역에 사는 사람의 수 · 그래프·표로 한눈에 비교, 막대가 길수록 값이 큼 · 연도별 막대가 길어지면 인구가 늘고 있음 · 면적이 넓다고 인구가 꼭 많은 것은 아님 · 면적과 인구를 알면 필요한 시설을 계획',ARRAY['[4사05-02] 우리 지역의 위치와 특성을 지리 정보로 탐색하고 다른 지역과 비교한다(차시 머리 표기 · 문구 초안)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C10','soc',4,1,'u1',10,'우리 지역의 기온과 강수량 — 기온 = 공기가 따뜻하고 차가운 정도(°C) · 강수량 = 일정 기간 내린 비·눈의 양(mm) · 기후 그래프는 기온(꺾은선)과 강수량(막대)을 함께 · 우리나라는 여름에 덥고 비가 많고 겨울에 춥고 건조 · 계절에 맞는 옷차림·농사·생활 준비',ARRAY['[4사05-02] 우리 지역의 위치와 특성을 지리 정보로 탐색하고 다른 지역과 비교한다(차시 머리 표기 · 문구 초안)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C11','soc',4,1,'u1',11,'지리 정보로 지역 비교하기 — 지리 정보 = 위치·지형·면적·인구·기후처럼 지역에 관한 여러 정보 · 영상 지도(위치·지형)·통계(인구·면적)·기상 자료(기온·강수량)로 조사 · 같은 항목끼리 견주어 비교 · 비교하면 각 지역의 특징과 다른 점을 앎 · 지리 정보는 시간이 지나며 변할 수 있음 · 지리 정보 전문가',ARRAY['[4사05-02] 우리 지역의 위치와 특성을 지리 정보로 탐색하고 다른 지역과 비교한다(차시 머리 표기 · 문구 초안)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-1-u1-C12','soc',4,1,'u1',12,'픽셀 아트로 지역 나타내기 — 픽셀 아트 = 작은 사각형(픽셀)을 모아 나타낸 그림 · 범례에서 숫자별 색을 정해 범례에 맞추어 색칠 · 칸 수가 많을수록 면적이 넓음 · 색칠된 자리로 위치를 앎 · 완성한 지도로 지역별 위치와 면적을 비교하며 이야기하고 협력',ARRAY['[4사05-02] 우리 지역의 위치와 특성을 지리 정보로 탐색하고 다른 지역과 비교한다(차시 머리 표기 · 문구 초안)']::text[],12) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X01','soc',4,'u1',ARRAY['SO4-1-u1-C1']::text[],'지도를 실제 크기 그대로 그린 그림이나 그리고 싶은 대로 그린 그림으로 여긴다','일정하게 줄여 · 약속대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X02','soc',4,'u1',ARRAY['SO4-1-u1-C1']::text[],'높은 곳에서 내려다보기만 하면 장소의 정확한 위치와 거리까지 알 수 있다고 여긴다','한눈에 보여도 거리는 몰라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X03','soc',4,'u1',ARRAY['SO4-1-u1-C1','SO4-1-u1-C3']::text[],'지도의 선·색·모양 표시를 그린 사람 마음대로 정한 것으로 여겨 「약속」을 놓친다','표시는 모두 약속') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X04','soc',4,'u1',ARRAY['SO4-1-u1-C1','SO4-1-u1-C3']::text[],'실제 모습이 다 담긴 사진이나 그림지도가 장소를 찾기에 더 쉽다고 여긴다','약속된 기호가 더 빨라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X05','soc',4,'u1',ARRAY['SO4-1-u1-C2']::text[],'앞·뒤·오른쪽·왼쪽으로 말해도 누구에게나 위치가 똑같이 전해진다고 여긴다','보는 방향에 따라 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X06','soc',4,'u1',ARRAY['SO4-1-u1-C2','SO4-1-u1-C7']::text[],'방위표에서 동쪽과 서쪽, 북쪽과 남쪽을 바꾸어 읽는다','위 북 · 아래 남 · 오른쪽 동 · 왼쪽 서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X07','soc',4,'u1',ARRAY['SO4-1-u1-C2']::text[],'방위표가 없는 지도에서는 방위를 알 수 없다고 여기거나, 방위표가 있어도 화살표를 보지 않는다','없으면 위쪽이 북쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X08','soc',4,'u1',ARRAY['SO4-1-u1-C2']::text[],'8방위의 사이 방위 이름을 잘못 붙인다(북쪽과 동쪽 사이를 남동쪽이라고 하는 등)','두 방위 이름을 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X09','soc',4,'u1',ARRAY['SO4-1-u1-C3']::text[],'기호와 범례를 헷갈린다(기호 하나를 범례라고 하는 등)','범례 = 기호와 뜻을 모은 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X10','soc',4,'u1',ARRAY['SO4-1-u1-C3']::text[],'기호는 아무 모양이나 쓴다고 여겨 장소의 생김새나 특징을 본떠 만든다는 것을 놓친다','생김새 · 특징을 본떠요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X11','soc',4,'u1',ARRAY['SO4-1-u1-C7','SO4-1-u1-C2','SO4-1-u1-C3','SO4-1-u1-C4','SO4-1-u1-C5']::text[],'지도 요소의 이름과 하는 일을 바꾸어 짝짓는다(축척을 방향, 등고선을 거리로 여기는 등)','방향 · 장소 · 높낮이 · 거리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X12','soc',4,'u1',ARRAY['SO4-1-u1-C4']::text[],'등고선을 길·강·경계선 같은 다른 선으로 여기거나 높이가 같은 곳을 이은 선이라는 것을 놓친다','높이가 같은 곳을 이어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X13','soc',4,'u1',ARRAY['SO4-1-u1-C4']::text[],'등고선의 바깥쪽 큰 원이 더 높은 곳이라고 거꾸로 읽는다','안쪽으로 갈수록 높아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X14','soc',4,'u1',ARRAY['SO4-1-u1-C4']::text[],'등고선 간격이 좁은 곳을 완만한 곳, 넓은 곳을 급한 곳으로 거꾸로 읽는다','좁으면 급해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X15','soc',4,'u1',ARRAY['SO4-1-u1-C4']::text[],'높낮이 색을 거꾸로 읽는다(낮은 곳을 고동색, 높은 곳을 초록색으로)','낮은 곳 초록 · 높은 곳 고동') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X16','soc',4,'u1',ARRAY['SO4-1-u1-C5','SO4-1-u1-C7']::text[],'축척으로 실제 거리를 구할 때 곱하는 수나 단위를 잘못 쓴다(3 cm 를 300 m 나 30 km 로 하는 등)','1 cm 가 몇 km 인지 먼저') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X17','soc',4,'u1',ARRAY['SO4-1-u1-C5']::text[],'실제 거리를 많이 줄인 지도가 더 자세하다고, 덜 줄인 지도가 더 넓은 지역을 담는다고 거꾸로 여긴다','많이 줄이면 넓게 · 간략하게') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X18','soc',4,'u1',ARRAY['SO4-1-u1-C5']::text[],'축척을 확인하지 않고 지도상 거리만 재거나, 지역을 실제 크기대로 종이에 그릴 수 있다고 여긴다','축척 확인 → 막대자로 재기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X19','soc',4,'u1',ARRAY['SO4-1-u1-C6']::text[],'상황과 목적을 생각하지 않고 아무 지도나, 가장 큰 지도만 쓰면 된다고 여긴다','상황과 목적에 맞게 골라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X20','soc',4,'u1',ARRAY['SO4-1-u1-C6']::text[],'관광 안내도·약도·노선도·길 도우미가 무엇을 알려 주는지 바꾸어 안다','무엇을 알려 주는 지도일까') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X21','soc',4,'u1',ARRAY['SO4-1-u1-C6']::text[],'옛 지도는 오늘날 지도와 전혀 달라 기호·범례가 없었다고 여긴다','대동여지도에도 기호와 범례') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X22','soc',4,'u1',ARRAY['SO4-1-u1-C8']::text[],'위치를 날씨·인구·크기 같은 다른 정보로 설명한다','방위와 이웃 지역으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X23','soc',4,'u1',ARRAY['SO4-1-u1-C8','SO4-1-u1-C11']::text[],'산·들(평야)·강·바다·섬 같은 지형의 생김새를 서로 헷갈린다','솟은 땅 · 평평한 땅 · 물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X24','soc',4,'u1',ARRAY['SO4-1-u1-C8']::text[],'지형은 사람들의 생활과 관계없다고 여긴다','지형에 따라 생활이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X25','soc',4,'u1',ARRAY['SO4-1-u1-C9']::text[],'면적과 인구를 헷갈리거나, 면적이 넓으면 인구도 반드시 많다고 여긴다','넓이 ≠ 사람 수') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X26','soc',4,'u1',ARRAY['SO4-1-u1-C9','SO4-1-u1-C10']::text[],'그래프를 거꾸로 읽는다(막대가 짧을수록 많다, 막대가 길어지는데 줄고 있다고 하는 등)','막대가 길수록 커요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X27','soc',4,'u1',ARRAY['SO4-1-u1-C10']::text[],'기온과 강수량을 헷갈리거나 단위(°C·mm)를 바꾸어 쓴다','따뜻한 정도 · 내린 양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X28','soc',4,'u1',ARRAY['SO4-1-u1-C10']::text[],'기후 그래프에서 기온을 막대, 강수량을 꺾은선으로 바꾸어 읽는다','기온 꺾은선 · 강수량 막대') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X29','soc',4,'u1',ARRAY['SO4-1-u1-C10']::text[],'우리나라 계절의 기온·강수량 특징을 잘못 안다(겨울에 비가 가장 많다고 하는 등)','여름 덥고 비 많음') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X30','soc',4,'u1',ARRAY['SO4-1-u1-C11','SO4-1-u1-C12']::text[],'지리 정보가 아닌 것(좋아하는 음식·친구 얼굴 등)을 지리 정보로 여기거나 조사할 곳을 잘못 고른다','위치·지형·면적·인구·기후') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X31','soc',4,'u1',ARRAY['SO4-1-u1-C11']::text[],'서로 다른 항목끼리 견주거나, 지리 정보는 한번 정해지면 변하지 않는다고 여긴다','같은 항목끼리 · 변할 수 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-1-u1-X32','soc',4,'u1',ARRAY['SO4-1-u1-C12']::text[],'픽셀 지도에서 칸 수를 인구나 다른 정보로 읽거나, 범례와 다르게 마음대로 색칠한다','칸 수 = 면적 · 범례대로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#1','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',1,'mc','auto','하늘에서 내려다본 땅의 모습을 일정하게 줄여 정해진 약속에 따라 나타낸 그림을 무엇이라고 하나요?',ARRAY['SO4-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C1","difficulty":1,"kind":"mc","stem":"하늘에서 내려다본 땅의 모습을 일정하게 줄여 정해진 약속에 따라 나타낸 그림을 무엇이라고 하나요?","options":[{"t":"지도","correct":true},{"t":"사진","mis":"SO4-1-u1-X01"},{"t":"그림일기","mis":"SO4-1-u1-X01"},{"t":"달력","mis":"SO4-1-u1-X01"}],"explanation":["줄여서 나타내요.","약속대로 나타내요.","지도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#2','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',1,'ox','auto','높은 곳에 올라가 내려다보면 지역이 한눈에 보여요.',ARRAY['SO4-1-u1-X02']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C1","difficulty":1,"kind":"ox","stem":"높은 곳에 올라가 내려다보면 지역이 한눈에 보여요.","answer":"O","reason_options":[{"t":"땅의 모습과 특징을 넓게 볼 수 있기 때문에","correct":true},{"t":"높은 곳에서는 아무것도 보이지 않기 때문에","mis":"SO4-1-u1-X02"}],"mis":"SO4-1-u1-X02","explanation":["높은 곳에 올라요.","넓게 보여요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#3','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',1,'sa','auto','지도의 선·색·숫자·모양 표시는 모두 정해진 ○○이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C1","difficulty":1,"kind":"sa","stem":"지도의 선·색·숫자·모양 표시는 모두 정해진 ○○이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["약속"],"explanation":["모두가 미리 정했어요.","약◯이에요.","약속이에요."],"mis":"SO4-1-u1-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#4','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',1,'mc','auto','산꼭대기에 오른 채원이가 우리 집을 쉽게 찾으려면 무엇을 보면 가장 좋을까요?',ARRAY['SO4-1-u1-X02']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C1","difficulty":1,"kind":"mc","stem":"산꼭대기에 오른 채원이가 우리 집을 쉽게 찾으려면 무엇을 보면 가장 좋을까요?","options":[{"t":"지도","correct":true},{"t":"구름","mis":"SO4-1-u1-X02"},{"t":"거울","mis":"SO4-1-u1-X02"},{"t":"시계","mis":"SO4-1-u1-X02"}],"explanation":["위치를 알려 주는 것이에요.","약속된 표시가 있어요.","지도예요."],"asset":{"type":"passage","lines":["채원이가 뒷산 꼭대기에 올라 마을을 내려다보았다.","마을이 한눈에 들어왔지만 우리 집이 어디인지 찾기 어려웠다.","학교에서 우리 집까지 얼마나 떨어져 있는지도 알 수 없었다."],"title":"산꼭대기에서 본 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#5','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',2,'mc','auto','채원이가 산꼭대기에서 정확히 알기 어려웠던 것은 무엇인가요?',ARRAY['SO4-1-u1-X02']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C1","difficulty":2,"kind":"mc","stem":"채원이가 산꼭대기에서 정확히 알기 어려웠던 것은 무엇인가요?","options":[{"t":"학교에서 우리 집까지의 거리","correct":true},{"t":"마을이 있는지 없는지","mis":"SO4-1-u1-X02"},{"t":"마을의 전체 모습","mis":"SO4-1-u1-X02"},{"t":"산 아래에 마을이 펼쳐진 모습","mis":"SO4-1-u1-X02"}],"explanation":["마을은 한눈에 보였어요.","얼마나 떨어졌는지는 몰랐어요.","거리예요."],"asset":{"type":"passage","lines":["채원이가 뒷산 꼭대기에 올라 마을을 내려다보았다.","마을이 한눈에 들어왔지만 우리 집이 어디인지 찾기 어려웠다.","학교에서 우리 집까지 얼마나 떨어져 있는지도 알 수 없었다."],"title":"산꼭대기에서 본 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#6','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',2,'ox','auto','지도는 땅을 실제 크기 그대로 그린 그림이에요.',ARRAY['SO4-1-u1-X01']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C1","difficulty":2,"kind":"ox","stem":"지도는 땅을 실제 크기 그대로 그린 그림이에요.","answer":"X","reason_options":[{"t":"땅의 모습을 일정하게 줄여서 나타내기 때문에","correct":true},{"t":"실제 크기로 그려야 정확하기 때문에","mis":"SO4-1-u1-X01"}],"mis":"SO4-1-u1-X01","explanation":["실제 크기라면 종이가 마을만큼 커져요.","줄여서 그려요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#7','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',2,'mc','auto','두 자료 가운데 학교와 병원을 더 빨리 찾을 수 있는 것과 그 까닭은 무엇인가요?',ARRAY['SO4-1-u1-X04','SO4-1-u1-X03']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C1","difficulty":2,"kind":"mc","stem":"두 자료 가운데 학교와 병원을 더 빨리 찾을 수 있는 것과 그 까닭은 무엇인가요?","options":[{"t":"㉯ — 약속된 표시로 장소를 나타내서","correct":true},{"t":"㉮ — 모든 것이 다 찍혀 있어서","mis":"SO4-1-u1-X04"},{"t":"㉮ — 색이 더 예뻐서","mis":"SO4-1-u1-X04"},{"t":"㉯ — 종이가 더 커서","mis":"SO4-1-u1-X03"}],"explanation":["사진은 다 담겨 복잡해요.","지도는 약속된 표시예요.","㉯가 빨라요."],"asset":{"type":"passage","lines":["㉮ 하늘에서 찍은 사진 — 지붕·나무·자동차까지 모두 찍혀 있다.","㉯ 지도 — 학교는 깃발, 병원은 ＋, 강은 파란 선으로 나타냈다."],"title":"같은 마을을 나타낸 두 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#8','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',2,'blank','auto','지도의 표시는 모두 약속이라서 지도에서 (    ) 정보를 얻을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u1-X03']::text[],false,'{"seq":8,"concept":"SO4-1-u1-C1","difficulty":2,"kind":"blank","stem":"지도의 표시는 모두 약속이라서 지도에서 (    ) 정보를 얻을 수 있어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"일정한","correct":true},{"t":"엉뚱한","mis":"SO4-1-u1-X03"},{"t":"그날그날 다른","mis":"SO4-1-u1-X03"},{"t":"아무","mis":"SO4-1-u1-X03"}],"explanation":["약속은 누구에게나 같아요.","그래서 정보도 같아요.","일정한 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#9','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',2,'mc','auto','지도에 대해 가장 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u1-X01','SO4-1-u1-X03']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C1","difficulty":2,"kind":"mc","stem":"지도에 대해 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"땅의 모습을 일정하게 줄여 약속에 따라 나타낸 그림이에요","correct":true},{"t":"그리고 싶은 대로 그린 그림이에요","mis":"SO4-1-u1-X01"},{"t":"땅을 실제 크기로 옮긴 그림이에요","mis":"SO4-1-u1-X01"},{"t":"아무 정보도 얻을 수 없는 그림이에요","mis":"SO4-1-u1-X03"}],"explanation":["줄여서예요.","약속대로예요.","두 가지가 다 들어가요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_basic#10','soc',4,1,'u1','L01','g4_1_soc_u1_L01_basic','lesson_basic','SO4-1-u1-C1',3,'mc','auto','비행기에서 찍은 사진과 땅의 높이·거리 정보를 모아 약속에 따라 지도로 나타내는 사람은 누구인가요?',ARRAY['SO4-1-u1-X04','SO4-1-u1-X01']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C1","difficulty":3,"kind":"mc","stem":"비행기에서 찍은 사진과 땅의 높이·거리 정보를 모아 약속에 따라 지도로 나타내는 사람은 누구인가요?","options":[{"t":"지도 제작 기술자","correct":true},{"t":"사진 작가","mis":"SO4-1-u1-X04"},{"t":"건물을 짓는 사람","mis":"SO4-1-u1-X01"},{"t":"그림책 작가","mis":"SO4-1-u1-X01"}],"explanation":["정보를 모아요.","약속대로 나타내요.","지도 제작 기술자예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#1','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',2,'ox','auto','높은 곳에서 내려다보면 장소 사이의 정확한 거리도 알 수 있어요.',ARRAY['SO4-1-u1-X02']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C1","difficulty":2,"kind":"ox","stem":"높은 곳에서 내려다보면 장소 사이의 정확한 거리도 알 수 있어요.","answer":"X","reason_options":[{"t":"한눈에 보여도 거리가 얼마나 되는지는 정확히 알기 어렵기 때문에","correct":true},{"t":"높이 올라갈수록 거리가 저절로 보이기 때문에","mis":"SO4-1-u1-X02"}],"mis":"SO4-1-u1-X02","explanation":["지역은 한눈에 보여요.","거리는 정확히 몰라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#2','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',2,'mc','auto','자료 ㉮가 장소를 찾기에 불편한 까닭은 무엇인가요?',ARRAY['SO4-1-u1-X04']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C1","difficulty":2,"kind":"mc","stem":"자료 ㉮가 장소를 찾기에 불편한 까닭은 무엇인가요?","options":[{"t":"실제 모습이 모두 담겨 복잡하기 때문이에요","correct":true},{"t":"색이 하나도 없기 때문이에요","mis":"SO4-1-u1-X04"},{"t":"너무 작게 찍혔기 때문이에요","mis":"SO4-1-u1-X04"},{"t":"아무것도 찍히지 않았기 때문이에요","mis":"SO4-1-u1-X04"}],"explanation":["지붕·나무·자동차가 다 있어요.","복잡해요.","그래서 찾기 어려워요."],"asset":{"type":"passage","lines":["㉮ 하늘에서 찍은 사진 — 지붕·나무·자동차까지 모두 찍혀 있다.","㉯ 지도 — 학교는 깃발, 병원은 ＋, 강은 파란 선으로 나타냈다."],"title":"같은 마을을 나타낸 두 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#3','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',3,'error','auto','지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X03','SO4-1-u1-X01']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C1","difficulty":3,"kind":"error","stem":"지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「지도의 표시는 그린 사람이 그날 기분대로 정해.」","correct":true,"mis_target":"SO4-1-u1-X03"},{"t":"친구 가 — 「지도는 땅의 모습을 줄여서 나타내.」","mis":"SO4-1-u1-X01"},{"t":"친구 다 — 「표시가 약속이라 누구나 읽을 수 있어.」","mis":"SO4-1-u1-X03"}],"explanation":["표시는 약속이에요.","기분대로가 아니에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#4','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',3,'mc','auto','지도를 만들 때 땅의 모습을 「일정하게 줄이는」 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X01','SO4-1-u1-X03']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C1","difficulty":3,"kind":"mc","stem":"지도를 만들 때 땅의 모습을 「일정하게 줄이는」 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"넓은 땅을 종이 위에 담으려고","correct":true},{"t":"지도를 예쁘게 꾸미려고","mis":"SO4-1-u1-X01"},{"t":"정보를 일부러 숨기려고","mis":"SO4-1-u1-X03"},{"t":"실제보다 크게 보이려고","mis":"SO4-1-u1-X01"}],"explanation":["땅은 아주 넓어요.","종이는 작아요.","줄여야 담겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#5','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',3,'mc','auto','채원이처럼 산꼭대기에서 우리 집을 못 찾은 사람에게 지도가 도움이 되는 까닭은 무엇인가요?',ARRAY['SO4-1-u1-X02','SO4-1-u1-X04']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C1","difficulty":3,"kind":"mc","stem":"채원이처럼 산꼭대기에서 우리 집을 못 찾은 사람에게 지도가 도움이 되는 까닭은 무엇인가요?","options":[{"t":"장소의 위치와 거리를 알 수 있기 때문이에요","correct":true},{"t":"산을 더 높게 보여 주기 때문이에요","mis":"SO4-1-u1-X02"},{"t":"구름을 걷어 주기 때문이에요","mis":"SO4-1-u1-X02"},{"t":"사진보다 더 복잡하기 때문이에요","mis":"SO4-1-u1-X04"}],"explanation":["채원이는 위치를 몰랐어요.","거리도 몰랐어요.","지도로 알 수 있어요."],"asset":{"type":"passage","lines":["채원이가 뒷산 꼭대기에 올라 마을을 내려다보았다.","마을이 한눈에 들어왔지만 우리 집이 어디인지 찾기 어려웠다.","학교에서 우리 집까지 얼마나 떨어져 있는지도 알 수 없었다."],"title":"산꼭대기에서 본 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#6','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',3,'ox','auto','약속을 아는 사람이라면 처음 보는 지역의 지도도 읽을 수 있어요.',ARRAY['SO4-1-u1-X03']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C1","difficulty":3,"kind":"ox","stem":"약속을 아는 사람이라면 처음 보는 지역의 지도도 읽을 수 있어요.","answer":"O","reason_options":[{"t":"지도의 표시가 정해진 약속이기 때문에","correct":true},{"t":"지도는 그린 사람만 읽을 수 있기 때문에","mis":"SO4-1-u1-X03"}],"mis":"SO4-1-u1-X03","explanation":["표시는 약속이에요.","누구나 같아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#7','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',3,'mc','auto','같은 마을을 사진 ㉮와 지도 ㉯로 나타냈어요. 지도 ㉯에서 「파란 선」으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u1-X04']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C1","difficulty":3,"kind":"mc","stem":"같은 마을을 사진 ㉮와 지도 ㉯로 나타냈어요. 지도 ㉯에서 「파란 선」으로 알 수 있는 것은 무엇인가요?","options":[{"t":"강","correct":true},{"t":"자동차","mis":"SO4-1-u1-X04"},{"t":"나무","mis":"SO4-1-u1-X04"},{"t":"지붕","mis":"SO4-1-u1-X04"}],"explanation":["지도는 약속된 표시를 써요.","파란 선이에요.","강이에요."],"asset":{"type":"passage","lines":["㉮ 하늘에서 찍은 사진 — 지붕·나무·자동차까지 모두 찍혀 있다.","㉯ 지도 — 학교는 깃발, 병원은 ＋, 강은 파란 선으로 나타냈다."],"title":"같은 마을을 나타낸 두 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#8','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',4,'essay','teacher','채원이에게 지도가 무엇인지 설명하고, 산꼭대기에서 내려다보는 것과 견주어 지도가 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C1","difficulty":4,"kind":"essay","stem":"채원이에게 지도가 무엇인지 설명하고, 산꼭대기에서 내려다보는 것과 견주어 지도가 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 지도는 하늘에서 내려다본 땅의 모습을 일정하게 줄여 정해진 약속에 따라 나타낸 그림이에요. 산꼭대기에서는 마을이 한눈에 보여도 우리 집의 정확한 위치와 거리를 알기 어렵지만, 지도를 보면 약속된 표시로 위치와 거리를 알 수 있어요.","scoring_points":["지도의 뜻(줄여서·약속에 따라)을 썼는가","내려다볼 때 알기 어려운 점을 썼는가","지도가 좋은 점(위치·거리)을 썼는가"]},"explanation":["뜻을 먼저 써요.","견주어 봐요.","좋은 점을 써요."],"asset":{"type":"passage","lines":["채원이가 뒷산 꼭대기에 올라 마을을 내려다보았다.","마을이 한눈에 들어왔지만 우리 집이 어디인지 찾기 어려웠다.","학교에서 우리 집까지 얼마나 떨어져 있는지도 알 수 없었다."],"title":"산꼭대기에서 본 마을"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#9','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',4,'mc','auto','지도에 대한 설명을 두 가지 조건으로 고르면 「줄여서」와 「약속대로」예요. 두 조건을 모두 갖춘 설명은 무엇인가요?',ARRAY['SO4-1-u1-X01','SO4-1-u1-X03','SO4-1-u1-X04']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C1","difficulty":4,"kind":"mc","stem":"지도에 대한 설명을 두 가지 조건으로 고르면 「줄여서」와 「약속대로」예요. 두 조건을 모두 갖춘 설명은 무엇인가요?","options":[{"t":"마을을 일정하게 줄여 약속된 표시로 나타낸 그림","correct":true},{"t":"마을을 실제 크기로 약속된 표시를 써서 그린 그림","mis":"SO4-1-u1-X01"},{"t":"마을을 줄여서 마음대로 꾸민 그림","mis":"SO4-1-u1-X03"},{"t":"마을을 높은 곳에서 찍은 사진","mis":"SO4-1-u1-X04"}],"explanation":["줄였나요?","약속대로인가요?","둘 다 갖춘 것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L01_challenge#10','soc',4,1,'u1','L01','g4_1_soc_u1_L01_challenge','lesson_challenge','SO4-1-u1-C1',4,'essay','teacher','사진 ㉮와 지도 ㉯ 가운데 처음 온 손님에게 병원 가는 길을 알려 줄 자료를 고르고, 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C1","difficulty":4,"kind":"essay","stem":"사진 ㉮와 지도 ㉯ 가운데 처음 온 손님에게 병원 가는 길을 알려 줄 자료를 고르고, 그 까닭을 쓰세요.","answer_guide":{"answer":"예: 지도 ㉯를 고를 거예요. 사진은 지붕·나무·자동차가 모두 찍혀 복잡하지만, 지도는 병원을 ＋ 같은 약속된 표시로 나타내서 처음 온 사람도 쉽게 찾을 수 있기 때문이에요.","scoring_points":["지도 ㉯를 골랐는가","사진이 복잡하다는 점을 썼는가","약속된 표시로 쉽게 찾는다는 점을 썼는가"]},"explanation":["두 자료를 견줘요.","약속된 표시를 떠올려요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉮ 하늘에서 찍은 사진 — 지붕·나무·자동차까지 모두 찍혀 있다.","㉯ 지도 — 학교는 깃발, 병원은 ＋, 강은 파란 선으로 나타냈다."],"title":"같은 마을을 나타낸 두 자료"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_basic#1','soc',4,1,'u1','L02','g4_1_soc_u1_L02_basic','lesson_basic','SO4-1-u1-C2',1,'mc','auto','지도에서 동서남북의 방향으로 나타낸 위치를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C2","difficulty":1,"kind":"mc","stem":"지도에서 동서남북의 방향으로 나타낸 위치를 무엇이라고 하나요?","options":[{"t":"방위","correct":true},{"t":"기호","mis":"SO4-1-u1-X11"},{"t":"거리","mis":"SO4-1-u1-X11"},{"t":"축척","mis":"SO4-1-u1-X11"}],"explanation":["동서남북이에요.","방향으로 나타내요.","방위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_basic#2','soc',4,1,'u1','L02','g4_1_soc_u1_L02_basic','lesson_basic','SO4-1-u1-C2',1,'sa','auto','지도에서 방위를 알려 주는 표시를 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u1-C2","difficulty":1,"kind":"sa","stem":"지도에서 방위를 알려 주는 표시를 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["방위표"],"explanation":["방위를 알려 줘요.","방위◯예요.","방위표예요."],"mis":"SO4-1-u1-X07"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_basic#3','soc',4,1,'u1','L02','g4_1_soc_u1_L02_basic','lesson_basic','SO4-1-u1-C2',1,'ox','auto','방위표가 없는 지도에서는 위쪽을 북쪽으로 약속해요.',ARRAY['SO4-1-u1-X07']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C2","difficulty":1,"kind":"ox","stem":"방위표가 없는 지도에서는 위쪽을 북쪽으로 약속해요.","answer":"O","reason_options":[{"t":"방위표가 없으면 위쪽 북·아래쪽 남·오른쪽 동·왼쪽 서로 약속하기 때문에","correct":true},{"t":"방위표가 없으면 방위를 전혀 알 수 없기 때문에","mis":"SO4-1-u1-X07"}],"mis":"SO4-1-u1-X07","explanation":["방위표가 없어요.","약속이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_basic#4','soc',4,1,'u1','L02','g4_1_soc_u1_L02_basic','lesson_basic','SO4-1-u1-C2',1,'mc','auto','방위표에서 오른쪽은 어느 방위인가요?',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C2","difficulty":1,"kind":"mc","stem":"방위표에서 오른쪽은 어느 방위인가요?","options":[{"t":"동쪽","correct":true},{"t":"서쪽","mis":"SO4-1-u1-X06"},{"t":"북쪽","mis":"SO4-1-u1-X06"},{"t":"남쪽","mis":"SO4-1-u1-X06"}],"explanation":["위쪽은 북이에요.","오른쪽을 봐요.","동쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_basic#5','soc',4,1,'u1','L02','g4_1_soc_u1_L02_basic','lesson_basic','SO4-1-u1-C2',2,'mc','auto','별빛마을 지도에서 학교의 위쪽에 있는 도서관은 학교의 어느 쪽에 있나요?',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C2","difficulty":2,"kind":"mc","stem":"별빛마을 지도에서 학교의 위쪽에 있는 도서관은 학교의 어느 쪽에 있나요?","options":[{"t":"북쪽","correct":true},{"t":"남쪽","mis":"SO4-1-u1-X06"},{"t":"동쪽","mis":"SO4-1-u1-X06"},{"t":"서쪽","mis":"SO4-1-u1-X06"}],"explanation":["화살표가 위쪽을 가리켜요.","위쪽이 북쪽이에요.","북쪽이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","지도 가운데 — 학교","학교의 위쪽 — 도서관 · 학교의 아래쪽 — 공원","학교의 오른쪽 — 우체국 · 학교의 왼쪽 — 병원","학교의 오른쪽 위 — 소방서 · 학교의 왼쪽 아래 — 시장"],"title":"별빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_basic#6','soc',4,1,'u1','L02','g4_1_soc_u1_L02_basic','lesson_basic','SO4-1-u1-C2',2,'mc','auto','도윤이와 서아가 같은 도서관을 두고 다르게 말한 까닭은 무엇인가요?',ARRAY['SO4-1-u1-X05']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C2","difficulty":2,"kind":"mc","stem":"도윤이와 서아가 같은 도서관을 두고 다르게 말한 까닭은 무엇인가요?","options":[{"t":"오른쪽·왼쪽은 보는 방향에 따라 달라지기 때문이에요","correct":true},{"t":"도서관이 두 개이기 때문이에요","mis":"SO4-1-u1-X05"},{"t":"한 사람이 거짓말을 했기 때문이에요","mis":"SO4-1-u1-X05"},{"t":"도서관이 움직였기 때문이에요","mis":"SO4-1-u1-X05"}],"explanation":["서로 마주 보고 서 있어요.","바라보는 방향이 반대예요.","오른쪽·왼쪽이 바뀌어요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"도서관은 내 오른쪽에 있어."},{"who":"서아","text":"어? 내가 보기엔 도서관이 내 왼쪽에 있는데?"},{"who":"도윤","text":"우리가 서로 마주 보고 서 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
