INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#3','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',3,'mc','auto','별빛마을 지도에서 시장은 학교의 어느 쪽에 있나요?',ARRAY['SO4-1-u1-X06','SO4-1-u1-X08']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C2","difficulty":3,"kind":"mc","stem":"별빛마을 지도에서 시장은 학교의 어느 쪽에 있나요?","options":[{"t":"남서쪽","correct":true},{"t":"북동쪽","mis":"SO4-1-u1-X06"},{"t":"남동쪽","mis":"SO4-1-u1-X08"},{"t":"북서쪽","mis":"SO4-1-u1-X08"}],"explanation":["왼쪽 아래예요.","남쪽과 서쪽 사이예요.","남서쪽이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","지도 가운데 — 학교","학교의 위쪽 — 도서관 · 학교의 아래쪽 — 공원","학교의 오른쪽 — 우체국 · 학교의 왼쪽 — 병원","학교의 오른쪽 위 — 소방서 · 학교의 왼쪽 아래 — 시장"],"title":"별빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#4','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',3,'error','auto','별빛마을 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C2","difficulty":3,"kind":"error","stem":"별빛마을 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「우체국은 학교의 서쪽에 있어.」","correct":true,"mis_target":"SO4-1-u1-X06"},{"t":"친구 가 — 「공원은 학교의 남쪽에 있어.」","mis":"SO4-1-u1-X06"},{"t":"친구 나 — 「도서관은 학교의 북쪽에 있어.」","mis":"SO4-1-u1-X06"}],"explanation":["우체국은 오른쪽이에요.","오른쪽은 동쪽이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","지도 가운데 — 학교","학교의 위쪽 — 도서관 · 학교의 아래쪽 — 공원","학교의 오른쪽 — 우체국 · 학교의 왼쪽 — 병원","학교의 오른쪽 위 — 소방서 · 학교의 왼쪽 아래 — 시장"],"title":"별빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#5','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',3,'mc','auto','공원에서 학교를 바라보면 학교는 공원의 어느 쪽에 있나요?',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C2","difficulty":3,"kind":"mc","stem":"공원에서 학교를 바라보면 학교는 공원의 어느 쪽에 있나요?","options":[{"t":"북쪽","correct":true},{"t":"남쪽","mis":"SO4-1-u1-X06"},{"t":"동쪽","mis":"SO4-1-u1-X06"},{"t":"서쪽","mis":"SO4-1-u1-X06"}],"explanation":["공원은 학교의 아래쪽이에요.","공원에서 보면 학교는 위쪽이에요.","북쪽이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","지도 가운데 — 학교","학교의 위쪽 — 도서관 · 학교의 아래쪽 — 공원","학교의 오른쪽 — 우체국 · 학교의 왼쪽 — 병원","학교의 오른쪽 위 — 소방서 · 학교의 왼쪽 아래 — 시장"],"title":"별빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#6','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',3,'ox','auto','방위표가 있는 지도에서는 화살표가 가리키는 쪽을 보고 북쪽을 찾아요.',ARRAY['SO4-1-u1-X07']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C2","difficulty":3,"kind":"ox","stem":"방위표가 있는 지도에서는 화살표가 가리키는 쪽을 보고 북쪽을 찾아요.","answer":"O","reason_options":[{"t":"방위표의 화살표가 북쪽을 알려 주기 때문에","correct":true},{"t":"방위표가 있어도 언제나 종이의 위쪽만 북쪽이기 때문에","mis":"SO4-1-u1-X07"}],"mis":"SO4-1-u1-X07","explanation":["방위표를 봐요.","화살표가 북쪽이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#7','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',3,'match','auto','8방위 가운데 사이 방위와 그 자리를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C2","difficulty":3,"kind":"match","stem":"8방위 가운데 사이 방위와 그 자리를 알맞게 이으세요.","pairs":[{"l":"북동쪽","r":"북쪽과 동쪽 사이"},{"l":"남동쪽","r":"남쪽과 동쪽 사이"},{"l":"남서쪽","r":"남쪽과 서쪽 사이"},{"l":"북서쪽","r":"북쪽과 서쪽 사이"}],"mis":"SO4-1-u1-X08","explanation":["두 방위 사이예요.","두 이름을 이어요.","북·남을 먼저 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#8','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',4,'essay','teacher','도윤이와 서아의 대화를 보고, 두 사람이 헷갈리지 않으려면 도서관의 위치를 어떻게 말하면 좋을지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C2","difficulty":4,"kind":"essay","stem":"도윤이와 서아의 대화를 보고, 두 사람이 헷갈리지 않으려면 도서관의 위치를 어떻게 말하면 좋을지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 「도서관은 학교의 북쪽에 있어.」처럼 방위로 말하면 좋아요. 오른쪽·왼쪽은 보는 방향에 따라 달라지지만, 방위는 누가 어디서 보아도 같기 때문이에요.","scoring_points":["방위로 위치를 말했는가","오른쪽·왼쪽은 보는 방향에 따라 달라진다고 썼는가","방위는 누구에게나 같다고 썼는가"]},"explanation":["무엇이 헷갈렸나요?","기준이 필요해요.","방위로 말해요."],"asset":{"type":"speech","turns":[{"who":"도윤","text":"도서관은 내 오른쪽에 있어."},{"who":"서아","text":"어? 내가 보기엔 도서관이 내 왼쪽에 있는데?"},{"who":"도윤","text":"우리가 서로 마주 보고 서 있구나."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#9','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',4,'mc','auto','방위표의 화살표가 지도의 오른쪽을 가리키고 있어요. 이 지도에서 위쪽은 어느 방위인가요?',ARRAY['SO4-1-u1-X07','SO4-1-u1-X06']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C2","difficulty":4,"kind":"mc","stem":"방위표의 화살표가 지도의 오른쪽을 가리키고 있어요. 이 지도에서 위쪽은 어느 방위인가요?","options":[{"t":"서쪽","correct":true},{"t":"북쪽","mis":"SO4-1-u1-X07"},{"t":"동쪽","mis":"SO4-1-u1-X06"},{"t":"남쪽","mis":"SO4-1-u1-X06"}],"explanation":["오른쪽이 북쪽이에요.","북쪽에서 왼쪽으로 돌면 서쪽이에요.","위쪽은 서쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L02_challenge#10','soc',4,1,'u1','L02','g4_1_soc_u1_L02_challenge','lesson_challenge','SO4-1-u1-C2',4,'essay','teacher','별빛마을 지도에서 우체국과 소방서의 위치를 방위로 쓰고, 8방위를 쓰면 좋은 점을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C2","difficulty":4,"kind":"essay","stem":"별빛마을 지도에서 우체국과 소방서의 위치를 방위로 쓰고, 8방위를 쓰면 좋은 점을 쓰세요.","answer_guide":{"answer":"예: 우체국은 학교의 동쪽, 소방서는 학교의 북동쪽에 있어요. 네 방위만 쓰면 소방서처럼 사이에 있는 곳을 말하기 어렵지만, 8방위를 쓰면 더 정확하게 위치를 말할 수 있어요.","scoring_points":["우체국을 동쪽이라고 썼는가","소방서를 북동쪽이라고 썼는가","8방위로 더 정확하게 말할 수 있다고 썼는가"]},"explanation":["오른쪽은 동쪽이에요.","오른쪽 위는 북동쪽이에요.","좋은 점을 써요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","지도 가운데 — 학교","학교의 위쪽 — 도서관 · 학교의 아래쪽 — 공원","학교의 오른쪽 — 우체국 · 학교의 왼쪽 — 병원","학교의 오른쪽 위 — 소방서 · 학교의 왼쪽 아래 — 시장"],"title":"별빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#1','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',1,'mc','auto','복잡한 땅의 모습을 지도에 알기 쉽게 나타내려고 약속한 표시를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X09','SO4-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C3","difficulty":1,"kind":"mc","stem":"복잡한 땅의 모습을 지도에 알기 쉽게 나타내려고 약속한 표시를 무엇이라고 하나요?","options":[{"t":"기호","correct":true},{"t":"범례","mis":"SO4-1-u1-X09"},{"t":"축척","mis":"SO4-1-u1-X11"},{"t":"방위","mis":"SO4-1-u1-X11"}],"explanation":["약속한 표시예요.","기◯예요.","기호예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#2','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',1,'mc','auto','지도에 쓰인 기호와 그 뜻을 한곳에 모아 놓은 것을 무엇이라고 하나요?',ARRAY['SO4-1-u1-X09','SO4-1-u1-X11']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C3","difficulty":1,"kind":"mc","stem":"지도에 쓰인 기호와 그 뜻을 한곳에 모아 놓은 것을 무엇이라고 하나요?","options":[{"t":"범례","correct":true},{"t":"기호","mis":"SO4-1-u1-X09"},{"t":"방위표","mis":"SO4-1-u1-X11"},{"t":"축척 막대","mis":"SO4-1-u1-X11"}],"explanation":["한곳에 모았어요.","뜻이 적혀 있어요.","범례예요."],"asset":{"type":"passage","lines":["깃발 — 학교","＋ — 병원","제비 모양 — 우체국","파란 선 — 강","초록 세모 — 산","검은 네모 — 건물"],"title":"별빛마을 지도의 범례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#3','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',1,'sa','auto','별빛마을 지도의 범례에서 「제비 모양」 기호는 어느 장소를 나타내나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C3","difficulty":1,"kind":"sa","stem":"별빛마을 지도의 범례에서 「제비 모양」 기호는 어느 장소를 나타내나요? 세 글자로 쓰세요.","answer":["우체국"],"explanation":["범례를 봐요.","소식을 전하는 곳이에요.","우체국이에요."],"asset":{"type":"passage","lines":["깃발 — 학교","＋ — 병원","제비 모양 — 우체국","파란 선 — 강","초록 세모 — 산","검은 네모 — 건물"],"title":"별빛마을 지도의 범례"},"mis":"SO4-1-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#4','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',1,'ox','auto','지도의 기호는 장소의 생김새나 특징을 본떠서 만들어요.',ARRAY['SO4-1-u1-X10']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C3","difficulty":1,"kind":"ox","stem":"지도의 기호는 장소의 생김새나 특징을 본떠서 만들어요.","answer":"O","reason_options":[{"t":"그래서 기호가 무엇을 뜻하는지 짐작하기 쉽기 때문에","correct":true},{"t":"기호는 아무 모양이나 골라 쓰기 때문에","mis":"SO4-1-u1-X10"}],"mis":"SO4-1-u1-X10","explanation":["생김새를 본떠요.","짐작하기 쉬워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#5','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',2,'mc','auto','별빛마을 지도에서 「＋」 기호가 보였어요. 범례로 알 수 있는 장소는 어디인가요?',ARRAY['SO4-1-u1-X09']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"mc","stem":"별빛마을 지도에서 「＋」 기호가 보였어요. 범례로 알 수 있는 장소는 어디인가요?","options":[{"t":"병원","correct":true},{"t":"학교","mis":"SO4-1-u1-X09"},{"t":"우체국","mis":"SO4-1-u1-X09"},{"t":"산","mis":"SO4-1-u1-X09"}],"explanation":["범례를 찾아요.","＋ 옆을 봐요.","병원이에요."],"asset":{"type":"passage","lines":["깃발 — 학교","＋ — 병원","제비 모양 — 우체국","파란 선 — 강","초록 세모 — 산","검은 네모 — 건물"],"title":"별빛마을 지도의 범례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#6','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',2,'mc','auto','제비 모양을 본떠 우체국 기호를 만든 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X10','SO4-1-u1-X03']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"mc","stem":"제비 모양을 본떠 우체국 기호를 만든 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"우체국이 반가운 소식을 전해 주는 곳이라서","correct":true},{"t":"우체국 건물이 제비처럼 생겨서","mis":"SO4-1-u1-X10"},{"t":"그날 제비가 날아서","mis":"SO4-1-u1-X10"},{"t":"그린 사람이 제비를 좋아해서","mis":"SO4-1-u1-X03"}],"explanation":["우체국은 편지를 전해요.","소식을 전하는 새예요.","특징을 본떴어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#7','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',2,'ox','auto','그림지도보다 기호지도에서 학교를 더 빨리 찾을 수 있어요.',ARRAY['SO4-1-u1-X04']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"ox","stem":"그림지도보다 기호지도에서 학교를 더 빨리 찾을 수 있어요.","answer":"O","reason_options":[{"t":"기호지도는 약속된 기호로 장소를 한눈에 나타내기 때문에","correct":true},{"t":"그림지도에 실제 모습이 다 그려져 있어 더 쉽기 때문에","mis":"SO4-1-u1-X04"}],"mis":"SO4-1-u1-X04","explanation":["그림지도는 복잡해요.","기호는 약속이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_basic#8','soc',4,1,'u1','L03','g4_1_soc_u1_L03_basic','lesson_basic','SO4-1-u1-C3',2,'blank','auto','글자를 몰라도 누구나 쉽게 이해할 수 있도록 만든 그림 문자를 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u1-X09','SO4-1-u1-X11']::text[],false,'{"seq":8,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"blank","stem":"글자를 몰라도 누구나 쉽게 이해할 수 있도록 만든 그림 문자를 (    )이라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"픽토그램","correct":true},{"t":"범례","mis":"SO4-1-u1-X09"},{"t":"축척","mis":"SO4-1-u1-X11"},{"t":"방위","mis":"SO4-1-u1-X11"}],"explanation":["그림만 보고 알아요.","화장실·비상구 그림이에요.","픽토그램이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
