INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#2','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',2,'ox','auto','범례는 지도에 쓰인 기호 하나하나를 부르는 이름이에요.',ARRAY['SO4-1-u1-X09']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"ox","stem":"범례는 지도에 쓰인 기호 하나하나를 부르는 이름이에요.","answer":"X","reason_options":[{"t":"범례는 기호와 그 뜻을 한곳에 모아 놓은 것이기 때문에","correct":true},{"t":"기호와 범례는 같은 말이기 때문에","mis":"SO4-1-u1-X09"}],"mis":"SO4-1-u1-X09","explanation":["기호는 표시예요.","범례는 모아 놓은 곳이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#3','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',3,'error','auto','기호와 범례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X10','SO4-1-u1-X09','SO4-1-u1-X03']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C3","difficulty":3,"kind":"error","stem":"기호와 범례를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「기호는 생김새와 상관없이 아무 모양이나 써.」","correct":true,"mis_target":"SO4-1-u1-X10"},{"t":"친구 나 — 「범례를 보면 기호의 뜻을 알 수 있어.」","mis":"SO4-1-u1-X09"},{"t":"친구 다 — 「기호를 쓰면 땅의 모습이 간단해져.」","mis":"SO4-1-u1-X03"}],"explanation":["기호는 본떠 만들어요.","아무 모양이 아니에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#4','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',3,'mc','auto','그림지도와 기호지도 가운데 학교를 더 빨리 찾을 수 있는 것과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u1-X04','SO4-1-u1-X03']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C3","difficulty":3,"kind":"mc","stem":"그림지도와 기호지도 가운데 학교를 더 빨리 찾을 수 있는 것과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"기호지도 — 약속된 기호로 나타내어 한눈에 찾을 수 있어서","correct":true},{"t":"그림지도 — 실제 모습이 다 그려져 있어서","mis":"SO4-1-u1-X04"},{"t":"그림지도 — 색이 더 예뻐서","mis":"SO4-1-u1-X04"},{"t":"기호지도 — 종이가 더 커서","mis":"SO4-1-u1-X03"}],"explanation":["그림지도는 복잡해요.","기호는 약속이에요.","기호지도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#5','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',3,'mc','auto','픽토그램으로 장소를 나타내면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u1-X03','SO4-1-u1-X04']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C3","difficulty":3,"kind":"mc","stem":"픽토그램으로 장소를 나타내면 좋은 점은 무엇인가요?","options":[{"t":"글자를 모르는 사람도 쉽고 빠르게 알아볼 수 있어요","correct":true},{"t":"한 사람만 알아볼 수 있어요","mis":"SO4-1-u1-X03"},{"t":"글자를 많이 써야 해요","mis":"SO4-1-u1-X04"},{"t":"색이 화려해져요","mis":"SO4-1-u1-X03"}],"explanation":["그림 문자예요.","글자가 없어도 돼요.","누구나 알아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#6','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',3,'ox','auto','기호가 많은 지도라도 범례가 있으면 기호를 읽을 수 있어요.',ARRAY['SO4-1-u1-X09']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C3","difficulty":3,"kind":"ox","stem":"기호가 많은 지도라도 범례가 있으면 기호를 읽을 수 있어요.","answer":"O","reason_options":[{"t":"범례에 기호와 그 뜻이 모여 있기 때문에","correct":true},{"t":"기호가 많으면 범례로도 알 수 없기 때문에","mis":"SO4-1-u1-X09"}],"mis":"SO4-1-u1-X09","explanation":["기호가 많아요.","범례에 뜻이 있어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#7','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',3,'mc','auto','별빛마을 지도의 범례로 알 수 없는 것은 무엇인가요?',ARRAY['SO4-1-u1-X09']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C3","difficulty":3,"kind":"mc","stem":"별빛마을 지도의 범례로 알 수 없는 것은 무엇인가요?","options":[{"t":"학교에 다니는 학생 수","correct":true},{"t":"학교의 위치를 나타내는 기호","mis":"SO4-1-u1-X09"},{"t":"강을 나타내는 기호","mis":"SO4-1-u1-X09"},{"t":"산을 나타내는 기호","mis":"SO4-1-u1-X09"}],"explanation":["범례에는 기호와 뜻이 있어요.","학생 수는 없어요.","그것을 골라요."],"asset":{"type":"passage","lines":["깃발 — 학교","＋ — 병원","제비 모양 — 우체국","파란 선 — 강","초록 세모 — 산","검은 네모 — 건물"],"title":"별빛마을 지도의 범례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#8','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',4,'essay','teacher','우리 학교 둘레의 장소 하나를 골라 기호를 새로 만든다면 어떤 모양으로 만들지 쓰고, 그렇게 만든 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C3","difficulty":4,"kind":"essay","stem":"우리 학교 둘레의 장소 하나를 골라 기호를 새로 만든다면 어떤 모양으로 만들지 쓰고, 그렇게 만든 까닭을 쓰세요.","answer_guide":{"answer":"예: 놀이터를 미끄럼틀 모양으로 나타낼 거예요. 놀이터의 생김새와 특징을 본떠야 누구나 무엇을 뜻하는지 쉽게 짐작할 수 있기 때문이에요.","scoring_points":["장소와 기호 모양을 썼는가","생김새나 특징을 본떴다고 썼는가","누구나 쉽게 알아본다는 까닭을 썼는가"]},"explanation":["장소를 골라요.","생김새를 떠올려요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#9','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',4,'essay','teacher','처음 우리 마을에 온 친구에게 별빛마을 지도의 범례가 왜 필요한지 설명하는 글을 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-1-u1-C3","difficulty":4,"kind":"essay","stem":"처음 우리 마을에 온 친구에게 별빛마을 지도의 범례가 왜 필요한지 설명하는 글을 쓰세요.","answer_guide":{"answer":"예: 지도에는 깃발·＋·파란 선 같은 기호가 많아요. 범례에는 기호와 그 뜻이 한곳에 모여 있어서, 처음 온 친구도 범례를 보면 깃발은 학교, ＋는 병원이라는 것을 알고 장소를 찾을 수 있어요.","scoring_points":["범례가 기호와 뜻을 모은 것이라고 썼는가","기호의 예를 들었는가","처음 온 사람도 지도를 읽을 수 있다고 썼는가"]},"explanation":["기호가 많아요.","뜻이 모여 있어요.","누구나 읽어요."],"asset":{"type":"passage","lines":["깃발 — 학교","＋ — 병원","제비 모양 — 우체국","파란 선 — 강","초록 세모 — 산","검은 네모 — 건물"],"title":"별빛마을 지도의 범례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L03_challenge#10','soc',4,1,'u1','L03','g4_1_soc_u1_L03_challenge','lesson_challenge','SO4-1-u1-C3',4,'mc','auto','어떤 지도의 범례에 「◎ — 시청」이 있어요. 다른 지도에서 ◎가 도서관을 뜻한다면 두 지도를 읽을 때 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X09','SO4-1-u1-X03']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C3","difficulty":4,"kind":"mc","stem":"어떤 지도의 범례에 「◎ — 시청」이 있어요. 다른 지도에서 ◎가 도서관을 뜻한다면 두 지도를 읽을 때 알맞은 것은 무엇인가요?","options":[{"t":"지도마다 범례를 확인하고 읽어요","correct":true},{"t":"먼저 본 지도의 뜻으로만 읽어요","mis":"SO4-1-u1-X09"},{"t":"◎는 둘 다 시청이에요","mis":"SO4-1-u1-X09"},{"t":"◎는 아무 뜻도 없어요","mis":"SO4-1-u1-X03"}],"explanation":["지도마다 범례가 있어요.","뜻을 확인해요.","범례를 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#1','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',1,'mc','auto','지도에서 땅의 높이가 같은 곳을 이은 선을 무엇이라고 하나요?',ARRAY['SO4-1-u1-X11','SO4-1-u1-X12']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C4","difficulty":1,"kind":"mc","stem":"지도에서 땅의 높이가 같은 곳을 이은 선을 무엇이라고 하나요?","options":[{"t":"등고선","correct":true},{"t":"방위표","mis":"SO4-1-u1-X11"},{"t":"경계선","mis":"SO4-1-u1-X12"},{"t":"도로","mis":"SO4-1-u1-X12"}],"explanation":["높이가 같아요.","선으로 이어요.","등고선이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#2','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',1,'sa','auto','등고선과 함께 쓰여 있는 숫자는 땅의 무엇을 나타내나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u1-C4","difficulty":1,"kind":"sa","stem":"등고선과 함께 쓰여 있는 숫자는 땅의 무엇을 나타내나요? 두 글자로 쓰세요.","answer":["높이"],"explanation":["땅이 얼마나 높은지예요.","높◯예요.","높이예요."],"mis":"SO4-1-u1-X12"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#3','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',1,'ox','auto','등고선 지도에서 땅이 낮은 곳은 초록색으로 나타내요.',ARRAY['SO4-1-u1-X15']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C4","difficulty":1,"kind":"ox","stem":"등고선 지도에서 땅이 낮은 곳은 초록색으로 나타내요.","answer":"O","reason_options":[{"t":"낮은 곳은 초록색, 높은 곳은 고동색으로 나타내기 때문에","correct":true},{"t":"낮은 곳을 고동색으로 나타내기 때문에","mis":"SO4-1-u1-X15"}],"mis":"SO4-1-u1-X15","explanation":["낮은 곳이에요.","초록색이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#4','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',1,'mc','auto','해오름산 등고선 지도에서 높이가 500인 곳은 어디인가요?',ARRAY['SO4-1-u1-X12','SO4-1-u1-X13']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C4","difficulty":1,"kind":"mc","stem":"해오름산 등고선 지도에서 높이가 500인 곳은 어디인가요?","options":[{"t":"가 봉우리의 가장 안쪽 원","correct":true},{"t":"나 봉우리의 가장 안쪽 원","mis":"SO4-1-u1-X12"},{"t":"가 봉우리의 가장 바깥쪽 원","mis":"SO4-1-u1-X13"},{"t":"산 아래 들","mis":"SO4-1-u1-X13"}],"explanation":["숫자 500을 찾아요.","가 봉우리예요.","가장 안쪽 원이에요."],"asset":{"type":"passage","lines":["가 봉우리 — 등고선 5겹, 가장 안쪽 원에 쓰인 숫자 500","나 봉우리 — 등고선 3겹, 가장 안쪽 원에 쓰인 숫자 300","가 봉우리 동쪽 비탈 — 등고선 간격이 좁다","가 봉우리 서쪽 비탈 — 등고선 간격이 넓다","산 아래 들 — 초록색 · 봉우리 꼭대기 — 고동색"],"title":"해오름산 등고선 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#5','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',2,'mc','auto','등고선의 간격이 좁은 곳은 경사가 어떠한가요?',ARRAY['SO4-1-u1-X14','SO4-1-u1-X12']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"mc","stem":"등고선의 간격이 좁은 곳은 경사가 어떠한가요?","options":[{"t":"경사가 급해요","correct":true},{"t":"경사가 완만해요","mis":"SO4-1-u1-X14"},{"t":"평평해요","mis":"SO4-1-u1-X14"},{"t":"물이 많아요","mis":"SO4-1-u1-X12"}],"explanation":["간격이 좁아요.","높이가 빨리 바뀌어요.","경사가 급해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#6','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',2,'mc','auto','봉우리가 있는 등고선 지도에서 가장 높은 곳은 어디인가요?',ARRAY['SO4-1-u1-X13','SO4-1-u1-X12']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"mc","stem":"봉우리가 있는 등고선 지도에서 가장 높은 곳은 어디인가요?","options":[{"t":"가장 안쪽의 가장 작은 원","correct":true},{"t":"가장 바깥쪽의 큰 원","mis":"SO4-1-u1-X13"},{"t":"지도의 네 귀퉁이","mis":"SO4-1-u1-X13"},{"t":"등고선이 없는 빈 곳","mis":"SO4-1-u1-X12"}],"explanation":["안쪽으로 갈수록 높아요.","가장 안쪽이에요.","작은 원이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#7','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',2,'ox','auto','해오름산의 가 봉우리 동쪽 비탈은 서쪽 비탈보다 경사가 급해요.',ARRAY['SO4-1-u1-X14']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"ox","stem":"해오름산의 가 봉우리 동쪽 비탈은 서쪽 비탈보다 경사가 급해요.","answer":"O","reason_options":[{"t":"동쪽 비탈의 등고선 간격이 더 좁기 때문에","correct":true},{"t":"간격이 좁을수록 경사가 완만하기 때문에","mis":"SO4-1-u1-X14"}],"mis":"SO4-1-u1-X14","explanation":["동쪽은 좁아요.","좁으면 급해요.","그래서 O예요."],"asset":{"type":"passage","lines":["가 봉우리 — 등고선 5겹, 가장 안쪽 원에 쓰인 숫자 500","나 봉우리 — 등고선 3겹, 가장 안쪽 원에 쓰인 숫자 300","가 봉우리 동쪽 비탈 — 등고선 간격이 좁다","가 봉우리 서쪽 비탈 — 등고선 간격이 넓다","산 아래 들 — 초록색 · 봉우리 꼭대기 — 고동색"],"title":"해오름산 등고선 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
