INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_basic#9','soc',4,1,'u1','L04','g4_1_soc_u1_L04_basic','lesson_basic','SO4-1-u1-C4',2,'mc','auto','해오름산의 두 봉우리 가운데 더 높을 것으로 짐작되는 봉우리와 그 까닭은 무엇인가요?',ARRAY['SO4-1-u1-X13','SO4-1-u1-X12']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"mc","stem":"해오름산의 두 봉우리 가운데 더 높을 것으로 짐작되는 봉우리와 그 까닭은 무엇인가요?","options":[{"t":"가 봉우리 — 숫자가 더 크고 등고선이 더 여러 겹이라서","correct":true},{"t":"나 봉우리 — 등고선이 더 적어서","mis":"SO4-1-u1-X13"},{"t":"나 봉우리 — 지도 아래쪽에 있어서","mis":"SO4-1-u1-X12"},{"t":"알 수 없어요 — 산 사진이 없어서","mis":"SO4-1-u1-X12"}],"explanation":["숫자를 견줘요.","겹 수도 견줘요.","가 봉우리예요."],"asset":{"type":"passage","lines":["가 봉우리 — 등고선 5겹, 가장 안쪽 원에 쓰인 숫자 500","나 봉우리 — 등고선 3겹, 가장 안쪽 원에 쓰인 숫자 300","가 봉우리 동쪽 비탈 — 등고선 간격이 좁다","가 봉우리 서쪽 비탈 — 등고선 간격이 넓다","산 아래 들 — 초록색 · 봉우리 꼭대기 — 고동색"],"title":"해오름산 등고선 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
