INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#3','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',3,'error','auto','해오름산 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X15','SO4-1-u1-X13','SO4-1-u1-X14']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C4","difficulty":3,"kind":"error","stem":"해오름산 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「산 아래 들은 고동색이니까 높은 곳이야.」","correct":true,"mis_target":"SO4-1-u1-X15"},{"t":"친구 가 — 「가 봉우리가 나 봉우리보다 높아.」","mis":"SO4-1-u1-X13"},{"t":"친구 다 — 「동쪽 비탈이 서쪽 비탈보다 급해.」","mis":"SO4-1-u1-X14"}],"explanation":["들은 초록색이에요.","낮은 곳이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["가 봉우리 — 등고선 5겹, 가장 안쪽 원에 쓰인 숫자 500","나 봉우리 — 등고선 3겹, 가장 안쪽 원에 쓰인 숫자 300","가 봉우리 동쪽 비탈 — 등고선 간격이 좁다","가 봉우리 서쪽 비탈 — 등고선 간격이 넓다","산 아래 들 — 초록색 · 봉우리 꼭대기 — 고동색"],"title":"해오름산 등고선 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#4','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',3,'mc','auto','산을 오를 때 힘이 덜 드는 길을 고르려면 등고선을 어떻게 보면 좋을까요?',ARRAY['SO4-1-u1-X14','SO4-1-u1-X15']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C4","difficulty":3,"kind":"mc","stem":"산을 오를 때 힘이 덜 드는 길을 고르려면 등고선을 어떻게 보면 좋을까요?","options":[{"t":"등고선 간격이 넓은 쪽으로 가요","correct":true},{"t":"등고선 간격이 좁은 쪽으로 가요","mis":"SO4-1-u1-X14"},{"t":"등고선이 가장 많이 겹친 쪽으로 가요","mis":"SO4-1-u1-X14"},{"t":"등고선 색은 보지 않아요","mis":"SO4-1-u1-X15"}],"explanation":["완만한 길이 편해요.","간격이 넓으면 완만해요.","넓은 쪽이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#5','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',3,'mc','auto','등고선이 땅의 높이가 같은 곳을 이은 선이라는 것으로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u1-X12']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C4","difficulty":3,"kind":"mc","stem":"등고선이 땅의 높이가 같은 곳을 이은 선이라는 것으로 알 수 있는 것은 무엇인가요?","options":[{"t":"한 등고선 위의 땅은 어디나 높이가 같아요","correct":true},{"t":"한 등고선 위의 땅은 높이가 모두 달라요","mis":"SO4-1-u1-X12"},{"t":"등고선은 길을 따라 그어요","mis":"SO4-1-u1-X12"},{"t":"등고선은 강을 나타내요","mis":"SO4-1-u1-X12"}],"explanation":["같은 높이를 이었어요.","선 위는 다 같아요.","높이가 같아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#6','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',3,'ox','auto','나 봉우리는 등고선이 3겹이고 숫자가 300이므로 가 봉우리보다 낮을 거예요.',ARRAY['SO4-1-u1-X13']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C4","difficulty":3,"kind":"ox","stem":"나 봉우리는 등고선이 3겹이고 숫자가 300이므로 가 봉우리보다 낮을 거예요.","answer":"O","reason_options":[{"t":"숫자가 더 작고 등고선도 더 적기 때문에","correct":true},{"t":"등고선이 적을수록 높은 산이기 때문에","mis":"SO4-1-u1-X13"}],"mis":"SO4-1-u1-X13","explanation":["숫자를 견줘요.","겹 수도 견줘요.","그래서 O예요."],"asset":{"type":"passage","lines":["가 봉우리 — 등고선 5겹, 가장 안쪽 원에 쓰인 숫자 500","나 봉우리 — 등고선 3겹, 가장 안쪽 원에 쓰인 숫자 300","가 봉우리 동쪽 비탈 — 등고선 간격이 좁다","가 봉우리 서쪽 비탈 — 등고선 간격이 넓다","산 아래 들 — 초록색 · 봉우리 꼭대기 — 고동색"],"title":"해오름산 등고선 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#7','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',3,'match','auto','등고선 지도의 모습과 땅의 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C4","difficulty":3,"kind":"match","stem":"등고선 지도의 모습과 땅의 모습을 알맞게 이으세요.","pairs":[{"l":"간격이 좁다","r":"경사가 급하다"},{"l":"간격이 넓다","r":"경사가 완만하다"},{"l":"가장 안쪽 원","r":"가장 높은 곳"},{"l":"초록색","r":"낮은 곳"}],"mis":"SO4-1-u1-X14","explanation":["간격을 봐요.","안쪽을 봐요.","색을 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#8','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',4,'essay','teacher','해오름산에서 가 봉우리를 오를 때 동쪽과 서쪽 가운데 어느 쪽으로 오르고 싶은지 고르고, 등고선을 근거로 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C4","difficulty":4,"kind":"essay","stem":"해오름산에서 가 봉우리를 오를 때 동쪽과 서쪽 가운데 어느 쪽으로 오르고 싶은지 고르고, 등고선을 근거로 까닭을 쓰세요.","answer_guide":{"answer":"예: 서쪽으로 오르고 싶어요. 서쪽 비탈은 등고선 간격이 넓어서 경사가 완만하기 때문에 덜 힘들게 오를 수 있어요. (동쪽을 고르면 간격이 좁아 경사가 급해서 빨리 오를 수 있다는 까닭도 됨)","scoring_points":["오를 쪽을 골랐는가","등고선 간격을 근거로 들었는가","간격과 경사의 관계를 바르게 썼는가"]},"explanation":["동쪽과 서쪽을 견줘요.","간격을 봐요.","경사를 써요."],"asset":{"type":"passage","lines":["가 봉우리 — 등고선 5겹, 가장 안쪽 원에 쓰인 숫자 500","나 봉우리 — 등고선 3겹, 가장 안쪽 원에 쓰인 숫자 300","가 봉우리 동쪽 비탈 — 등고선 간격이 좁다","가 봉우리 서쪽 비탈 — 등고선 간격이 넓다","산 아래 들 — 초록색 · 봉우리 꼭대기 — 고동색"],"title":"해오름산 등고선 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#9','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',4,'mc','auto','어느 산의 등고선이 북쪽은 촘촘하고 남쪽은 듬성듬성해요. 이 산에서 썰매를 가장 빠르게 타고 내려올 수 있는 쪽은 어디인가요?',ARRAY['SO4-1-u1-X14','SO4-1-u1-X13']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C4","difficulty":4,"kind":"mc","stem":"어느 산의 등고선이 북쪽은 촘촘하고 남쪽은 듬성듬성해요. 이 산에서 썰매를 가장 빠르게 타고 내려올 수 있는 쪽은 어디인가요?","options":[{"t":"북쪽 비탈","correct":true},{"t":"남쪽 비탈","mis":"SO4-1-u1-X14"},{"t":"산꼭대기","mis":"SO4-1-u1-X13"},{"t":"어느 쪽이나 같아요","mis":"SO4-1-u1-X14"}],"explanation":["촘촘하면 간격이 좁아요.","좁으면 급해요.","급한 북쪽이 빨라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L04_challenge#10','soc',4,1,'u1','L04','g4_1_soc_u1_L04_challenge','lesson_challenge','SO4-1-u1-C4',4,'essay','teacher','등고선 지도를 처음 보는 동생에게 산의 높낮이를 읽는 방법을 세 가지로 설명하세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C4","difficulty":4,"kind":"essay","stem":"등고선 지도를 처음 보는 동생에게 산의 높낮이를 읽는 방법을 세 가지로 설명하세요.","answer_guide":{"answer":"예: 첫째, 등고선 옆 숫자가 클수록 높은 곳이에요. 둘째, 안쪽 원으로 갈수록 높아지고 가장 안쪽 원이 가장 높아요. 셋째, 낮은 곳은 초록색, 높은 곳은 고동색이에요.","scoring_points":["숫자로 높이를 읽는다고 썼는가","안쪽일수록 높다고 썼는가","색이나 간격으로 읽는 방법을 썼는가"]},"explanation":["숫자예요.","안쪽이에요.","색이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#1','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',1,'mc','auto','지도에서 실제 거리를 줄여 나타낸 정도를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C5","difficulty":1,"kind":"mc","stem":"지도에서 실제 거리를 줄여 나타낸 정도를 무엇이라고 하나요?","options":[{"t":"축척","correct":true},{"t":"방위","mis":"SO4-1-u1-X11"},{"t":"등고선","mis":"SO4-1-u1-X11"},{"t":"범례","mis":"SO4-1-u1-X11"}],"explanation":["줄인 정도예요.","축◯이에요.","축척이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#2','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',1,'ox','auto','우리 지역을 종이 지도에 나타내려면 실제보다 줄여서 그려야 해요.',ARRAY['SO4-1-u1-X18']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C5","difficulty":1,"kind":"ox","stem":"우리 지역을 종이 지도에 나타내려면 실제보다 줄여서 그려야 해요.","answer":"O","reason_options":[{"t":"실제 크기로 그리면 종이가 지역만큼 커져야 하기 때문에","correct":true},{"t":"지도는 실제 크기 그대로 그려야 정확하기 때문에","mis":"SO4-1-u1-X18"}],"mis":"SO4-1-u1-X18","explanation":["지역은 넓어요.","종이는 작아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#3','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',1,'sa','auto','별빛마을 지도에서 학교부터 시장까지 지도상 거리는 2 cm 예요. 실제 거리는 몇 km 인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C5","difficulty":1,"kind":"sa","stem":"별빛마을 지도에서 학교부터 시장까지 지도상 거리는 2 cm 예요. 실제 거리는 몇 km 인가요? 숫자만 쓰세요.","answer":["2"],"explanation":["1 cm 가 1 km 예요.","2 cm 예요.","2 km 예요."],"asset":{"type":"passage","lines":["축척 막대 — 1 cm = 1 km","학교 ~ 시장: 지도에서 2 cm","학교 ~ 기차역: 지도에서 4 cm","학교 ~ 바닷가: 지도에서 7 cm"],"title":"별빛마을 지도의 축척"},"mis":"SO4-1-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#4','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',1,'mc','auto','축척을 알려 주는 것으로 지도에 그려진 막대를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C5","difficulty":1,"kind":"mc","stem":"축척을 알려 주는 것으로 지도에 그려진 막대를 무엇이라고 하나요?","options":[{"t":"축척 막대","correct":true},{"t":"방위표","mis":"SO4-1-u1-X11"},{"t":"범례","mis":"SO4-1-u1-X11"},{"t":"등고선","mis":"SO4-1-u1-X11"}],"explanation":["막대 모양이에요.","축척을 알려 줘요.","축척 막대예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#5','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',2,'mc','auto','축척 막대가 「1 cm = 1 km」인 지도에서 지도상 거리가 3 cm 이면 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"mc","stem":"축척 막대가 「1 cm = 1 km」인 지도에서 지도상 거리가 3 cm 이면 실제 거리는 얼마인가요?","options":[{"t":"3 km","correct":true},{"t":"300 m","mis":"SO4-1-u1-X16"},{"t":"30 m","mis":"SO4-1-u1-X16"},{"t":"30 km","mis":"SO4-1-u1-X16"}],"explanation":["1 cm 가 1 km 예요.","3 cm 예요.","3 km 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#6','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',2,'mc','auto','지도에서 두 장소 사이의 실제 거리를 구하는 차례로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X18']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"mc","stem":"지도에서 두 장소 사이의 실제 거리를 구하는 차례로 알맞은 것은 무엇인가요?","options":[{"t":"축척을 확인하고 → 축척 막대자로 지도상 거리를 재요","correct":true},{"t":"지도상 거리만 재고 → 그 수를 그대로 답해요","mis":"SO4-1-u1-X18"},{"t":"방위표를 먼저 그리고 → 색을 칠해요","mis":"SO4-1-u1-X18"},{"t":"기호를 지우고 → 범례를 읽어요","mis":"SO4-1-u1-X18"}],"explanation":["먼저 축척이에요.","그다음 재요.","실제 거리를 구해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#7','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',2,'ox','auto','실제 거리를 많이 줄인 지도는 넓은 지역을 간략하게 보여 줘요.',ARRAY['SO4-1-u1-X17']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"ox","stem":"실제 거리를 많이 줄인 지도는 넓은 지역을 간략하게 보여 줘요.","answer":"O","reason_options":[{"t":"많이 줄일수록 같은 종이에 더 넓은 지역이 담기기 때문에","correct":true},{"t":"많이 줄인 지도일수록 좁은 곳을 자세히 보여 주기 때문에","mis":"SO4-1-u1-X17"}],"mis":"SO4-1-u1-X17","explanation":["많이 줄였어요.","넓은 지역이 담겨요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#8','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',2,'mc','auto','별빛마을 지도에서 학교부터 기차역까지의 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16']::text[],false,'{"seq":8,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"mc","stem":"별빛마을 지도에서 학교부터 기차역까지의 실제 거리는 얼마인가요?","options":[{"t":"4 km","correct":true},{"t":"400 m","mis":"SO4-1-u1-X16"},{"t":"40 km","mis":"SO4-1-u1-X16"},{"t":"2 km","mis":"SO4-1-u1-X16"}],"explanation":["지도에서 4 cm 예요.","1 cm 가 1 km 예요.","4 km 예요."],"asset":{"type":"passage","lines":["축척 막대 — 1 cm = 1 km","학교 ~ 시장: 지도에서 2 cm","학교 ~ 기차역: 지도에서 4 cm","학교 ~ 바닷가: 지도에서 7 cm"],"title":"별빛마을 지도의 축척"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#9','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',2,'blank','auto','실제 거리를 덜 줄인 지도는 (    ) 지역을 자세하게 보여 줘요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u1-X17']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"blank","stem":"실제 거리를 덜 줄인 지도는 (    ) 지역을 자세하게 보여 줘요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"좁은","correct":true},{"t":"넓은","mis":"SO4-1-u1-X17"},{"t":"모든","mis":"SO4-1-u1-X17"},{"t":"먼","mis":"SO4-1-u1-X17"}],"explanation":["덜 줄였어요.","좁은 곳이 크게 나와요.","좁은 지역이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_basic#10','soc',4,1,'u1','L05','g4_1_soc_u1_L05_basic','lesson_basic','SO4-1-u1-C5',3,'mc','auto','세 지도 가운데 학교 둘레 골목을 가장 자세하게 살펴보려면 어느 지도를 골라야 하나요?',ARRAY['SO4-1-u1-X17']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"mc","stem":"세 지도 가운데 학교 둘레 골목을 가장 자세하게 살펴보려면 어느 지도를 골라야 하나요?","options":[{"t":"㉢","correct":true},{"t":"㉠","mis":"SO4-1-u1-X17"},{"t":"㉡","mis":"SO4-1-u1-X17"},{"t":"세 지도 모두 똑같아요","mis":"SO4-1-u1-X17"}],"explanation":["덜 줄일수록 자세해요.","㉢은 조금 줄였어요.","㉢이에요."],"asset":{"type":"passage","lines":["㉠ 실제 거리를 아주 많이 줄인 지도 — 별빛시 전체가 보인다.","㉡ 중간쯤 줄인 지도 — 별빛마을이 보인다.","㉢ 조금 줄인 지도 — 학교 둘레 골목까지 보인다.","(세 지도는 모두 같은 크기의 종이에 그렸다.)"],"title":"같은 종이에 그린 세 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#1','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',2,'mc','auto','세 지도 가운데 가장 넓은 지역이 담긴 지도는 어느 것인가요?',ARRAY['SO4-1-u1-X17','SO4-1-u1-X18']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"mc","stem":"세 지도 가운데 가장 넓은 지역이 담긴 지도는 어느 것인가요?","options":[{"t":"㉠","correct":true},{"t":"㉢","mis":"SO4-1-u1-X17"},{"t":"㉡","mis":"SO4-1-u1-X17"},{"t":"알 수 없어요","mis":"SO4-1-u1-X18"}],"explanation":["같은 종이예요.","많이 줄일수록 넓게 담겨요.","㉠이에요."],"asset":{"type":"passage","lines":["㉠ 실제 거리를 아주 많이 줄인 지도 — 별빛시 전체가 보인다.","㉡ 중간쯤 줄인 지도 — 별빛마을이 보인다.","㉢ 조금 줄인 지도 — 학교 둘레 골목까지 보인다.","(세 지도는 모두 같은 크기의 종이에 그렸다.)"],"title":"같은 종이에 그린 세 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#2','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',2,'ox','auto','별빛마을 지도에서 학교부터 바닷가까지 지도상 거리가 7 cm 이므로 실제 거리도 7 cm 예요.',ARRAY['SO4-1-u1-X18']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"ox","stem":"별빛마을 지도에서 학교부터 바닷가까지 지도상 거리가 7 cm 이므로 실제 거리도 7 cm 예요.","answer":"X","reason_options":[{"t":"축척에 따라 1 cm 가 실제 1 km 이므로 실제 거리는 7 km 이기 때문에","correct":true},{"t":"지도상 거리가 곧 실제 거리이기 때문에","mis":"SO4-1-u1-X18"}],"mis":"SO4-1-u1-X18","explanation":["축척을 확인해요.","1 cm 가 1 km 예요.","그래서 X예요."],"asset":{"type":"passage","lines":["축척 막대 — 1 cm = 1 km","학교 ~ 시장: 지도에서 2 cm","학교 ~ 기차역: 지도에서 4 cm","학교 ~ 바닷가: 지도에서 7 cm"],"title":"별빛마을 지도의 축척"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#3','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',3,'mc','auto','축척 막대가 「1 cm = 1 km」인 지도에서 지도상 거리가 10 cm 이면 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"mc","stem":"축척 막대가 「1 cm = 1 km」인 지도에서 지도상 거리가 10 cm 이면 실제 거리는 얼마인가요?","options":[{"t":"10 km","correct":true},{"t":"1 km","mis":"SO4-1-u1-X16"},{"t":"100 m","mis":"SO4-1-u1-X16"},{"t":"1 m","mis":"SO4-1-u1-X16"}],"explanation":["1 cm 가 1 km 예요.","10 cm 예요.","10 km 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#4','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',3,'error','auto','세 지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"error","stem":"세 지도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉠이 가장 자세해. 가장 많이 줄였으니까.」","correct":true,"mis_target":"SO4-1-u1-X17"},{"t":"친구 가 — 「㉢에는 골목까지 보여.」","mis":"SO4-1-u1-X17"},{"t":"친구 나 — 「㉠에는 별빛시 전체가 담겼어.」","mis":"SO4-1-u1-X17"}],"explanation":["많이 줄이면 간략해요.","자세하지 않아요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 실제 거리를 아주 많이 줄인 지도 — 별빛시 전체가 보인다.","㉡ 중간쯤 줄인 지도 — 별빛마을이 보인다.","㉢ 조금 줄인 지도 — 학교 둘레 골목까지 보인다.","(세 지도는 모두 같은 크기의 종이에 그렸다.)"],"title":"같은 종이에 그린 세 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#5','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',3,'mc','auto','학교에서 시장과 기차역 가운데 더 먼 곳은 어디이고, 두 곳의 실제 거리는 얼마나 차이 나나요?',ARRAY['SO4-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"mc","stem":"학교에서 시장과 기차역 가운데 더 먼 곳은 어디이고, 두 곳의 실제 거리는 얼마나 차이 나나요?","options":[{"t":"기차역 — 2 km 더 멀어요","correct":true},{"t":"시장 — 2 km 더 멀어요","mis":"SO4-1-u1-X16"},{"t":"기차역 — 2 cm 더 멀어요","mis":"SO4-1-u1-X16"},{"t":"기차역 — 6 km 더 멀어요","mis":"SO4-1-u1-X16"}],"explanation":["시장 2 km, 기차역 4 km 예요.","기차역이 더 멀어요.","2 km 차이예요."],"asset":{"type":"passage","lines":["축척 막대 — 1 cm = 1 km","학교 ~ 시장: 지도에서 2 cm","학교 ~ 기차역: 지도에서 4 cm","학교 ~ 바닷가: 지도에서 7 cm"],"title":"별빛마을 지도의 축척"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#6','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',3,'ox','auto','축척이 다른 두 지도에서 지도상 거리가 똑같이 3 cm 라도 실제 거리는 다를 수 있어요.',ARRAY['SO4-1-u1-X18']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"ox","stem":"축척이 다른 두 지도에서 지도상 거리가 똑같이 3 cm 라도 실제 거리는 다를 수 있어요.","answer":"O","reason_options":[{"t":"지도마다 실제 거리를 줄인 정도가 다르기 때문에","correct":true},{"t":"지도상 거리가 같으면 실제 거리도 언제나 같기 때문에","mis":"SO4-1-u1-X18"}],"mis":"SO4-1-u1-X18","explanation":["축척이 달라요.","줄인 정도가 달라요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#7','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',3,'match','auto','지도와 그 지도가 보여 주는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"match","stem":"지도와 그 지도가 보여 주는 모습을 알맞게 이으세요.","pairs":[{"l":"실제 거리를 많이 줄인 지도","r":"넓은 지역을 간략하게"},{"l":"실제 거리를 덜 줄인 지도","r":"좁은 지역을 자세하게"},{"l":"축척 막대","r":"실제 거리를 줄인 정도"}],"mis":"SO4-1-u1-X17","explanation":["많이 줄이면 넓게예요.","덜 줄이면 자세하게예요.","막대는 정도를 알려 줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#8','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',4,'essay','teacher','별빛마을 지도로 학교부터 바닷가까지의 실제 거리를 구하는 과정을 차례대로 쓰고 답을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C5","difficulty":4,"kind":"essay","stem":"별빛마을 지도로 학교부터 바닷가까지의 실제 거리를 구하는 과정을 차례대로 쓰고 답을 쓰세요.","answer_guide":{"answer":"예: 먼저 축척 막대를 보고 1 cm 가 실제 1 km 라는 것을 확인해요. 다음으로 축척 막대자로 학교부터 바닷가까지 지도상 거리를 재면 7 cm 예요. 그래서 실제 거리는 7 km 예요.","scoring_points":["축척을 먼저 확인했는가","지도상 거리 7 cm 를 썼는가","실제 거리 7 km 를 바르게 구했는가"]},"explanation":["축척을 봐요.","재요.","구해요."],"asset":{"type":"passage","lines":["축척 막대 — 1 cm = 1 km","학교 ~ 시장: 지도에서 2 cm","학교 ~ 기차역: 지도에서 4 cm","학교 ~ 바닷가: 지도에서 7 cm"],"title":"별빛마을 지도의 축척"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#9','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',4,'mc','auto','「1 cm = 2 km」인 지도에서 도서관부터 공원까지 지도상 거리가 3 cm 예요. 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16','SO4-1-u1-X18']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C5","difficulty":4,"kind":"mc","stem":"「1 cm = 2 km」인 지도에서 도서관부터 공원까지 지도상 거리가 3 cm 예요. 실제 거리는 얼마인가요?","options":[{"t":"6 km","correct":true},{"t":"3 km","mis":"SO4-1-u1-X16"},{"t":"5 km","mis":"SO4-1-u1-X16"},{"t":"6 cm","mis":"SO4-1-u1-X18"}],"explanation":["1 cm 가 2 km 예요.","3 cm 는 2 km 의 3배예요.","6 km 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L05_challenge#10','soc',4,1,'u1','L05','g4_1_soc_u1_L05_challenge','lesson_challenge','SO4-1-u1-C5',4,'essay','teacher','우리 고장 전체를 한 장에 담은 안내판과 학교 둘레만 크게 그린 안내판을 만들려고 해요. 두 안내판의 축척이 어떻게 달라야 하는지 까닭과 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C5","difficulty":4,"kind":"essay","stem":"우리 고장 전체를 한 장에 담은 안내판과 학교 둘레만 크게 그린 안내판을 만들려고 해요. 두 안내판의 축척이 어떻게 달라야 하는지 까닭과 함께 쓰세요.","answer_guide":{"answer":"예: 고장 전체 안내판은 실제 거리를 많이 줄여야 넓은 지역을 한 장에 담을 수 있어요. 학교 둘레 안내판은 실제 거리를 덜 줄여야 좁은 지역을 자세하게 보여 줄 수 있어요.","scoring_points":["고장 전체는 많이 줄인다고 썼는가","학교 둘레는 덜 줄인다고 썼는가","넓게·자세하게의 까닭을 썼는가"]},"explanation":["담을 곳이 달라요.","줄인 정도가 달라요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#1','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',1,'mc','auto','지역에 어떤 관광지가 있고 어디에 있는지 알려 주는 지도를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X20','SO4-1-u1-X19']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C6","difficulty":1,"kind":"mc","stem":"지역에 어떤 관광지가 있고 어디에 있는지 알려 주는 지도를 무엇이라고 하나요?","options":[{"t":"관광 안내도","correct":true},{"t":"약도","mis":"SO4-1-u1-X20"},{"t":"지하철 노선도","mis":"SO4-1-u1-X20"},{"t":"시간표","mis":"SO4-1-u1-X19"}],"explanation":["볼거리를 알려 줘요.","관광지예요.","관광 안내도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#2','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',1,'mc','auto','목적지를 찾아갈 수 있도록 길을 간단히 그린 지도를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X20','SO4-1-u1-X19']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C6","difficulty":1,"kind":"mc","stem":"목적지를 찾아갈 수 있도록 길을 간단히 그린 지도를 무엇이라고 하나요?","options":[{"t":"약도","correct":true},{"t":"관광 안내도","mis":"SO4-1-u1-X20"},{"t":"지구본","mis":"SO4-1-u1-X19"},{"t":"세계지도","mis":"SO4-1-u1-X19"}],"explanation":["길을 간단히 그려요.","초대장에 자주 있어요.","약도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#3','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',1,'sa','auto','지하철 노선이 다를 때 두 노선이 만나는 역에서 다른 노선으로 갈아타는 것을 무엇이라고 하나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C6","difficulty":1,"kind":"sa","stem":"지하철 노선이 다를 때 두 노선이 만나는 역에서 다른 노선으로 갈아타는 것을 무엇이라고 하나요? 두 글자로 쓰세요.","answer":["환승"],"explanation":["갈아타요.","환◯이에요.","환승이에요."],"asset":{"type":"passage","lines":["1호선: 해오름역 — 바람역 — 별빛역 — 달맞이역","2호선: 숲속역 — 별빛역 — 바닷가역","별빛역에서 1호선과 2호선이 만난다."],"title":"가상 지하철 노선도"},"mis":"SO4-1-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#4','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',1,'ox','auto','길 도우미(내비게이션)는 목적지를 넣으면 가장 좋은 이동 방법을 지도로 알려 줘요.',ARRAY['SO4-1-u1-X20']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C6","difficulty":1,"kind":"ox","stem":"길 도우미(내비게이션)는 목적지를 넣으면 가장 좋은 이동 방법을 지도로 알려 줘요.","answer":"O","reason_options":[{"t":"목적지까지 가는 좋은 길을 찾아 안내해 주기 때문에","correct":true},{"t":"길 도우미는 관광지 사진만 보여 주기 때문에","mis":"SO4-1-u1-X20"}],"mis":"SO4-1-u1-X20","explanation":["목적지를 넣어요.","길을 알려 줘요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#5','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',2,'mc','auto','상황 ㉠처럼 처음 가 보는 캠핑장에 자동차로 갈 때 가장 도움이 되는 것은 무엇인가요?',ARRAY['SO4-1-u1-X19']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"mc","stem":"상황 ㉠처럼 처음 가 보는 캠핑장에 자동차로 갈 때 가장 도움이 되는 것은 무엇인가요?","options":[{"t":"길 도우미(내비게이션)","correct":true},{"t":"관광 안내도","mis":"SO4-1-u1-X19"},{"t":"지하철 노선도","mis":"SO4-1-u1-X19"},{"t":"세계지도","mis":"SO4-1-u1-X19"}],"explanation":["처음 가는 곳이에요.","자동차로 가요.","길 도우미예요."],"asset":{"type":"passage","lines":["㉠ 처음 가 보는 캠핑장에 자동차로 간다.","㉡ 생일잔치에 초대하며 우리 집 가는 길을 알려 준다.","㉢ 다른 고장에 놀러 가서 볼거리를 찾는다.","㉣ 지하철을 갈아타고 박물관에 간다."],"title":"지도가 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#6','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',2,'mc','auto','가상 지하철 노선도에서 해오름역(1호선)에서 숲속역(2호선)으로 가려면 어느 역에서 갈아타야 하나요?',ARRAY['SO4-1-u1-X20']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"mc","stem":"가상 지하철 노선도에서 해오름역(1호선)에서 숲속역(2호선)으로 가려면 어느 역에서 갈아타야 하나요?","options":[{"t":"별빛역","correct":true},{"t":"바람역","mis":"SO4-1-u1-X20"},{"t":"달맞이역","mis":"SO4-1-u1-X20"},{"t":"바닷가역","mis":"SO4-1-u1-X20"}],"explanation":["두 노선이 만나요.","만나는 역을 찾아요.","별빛역이에요."],"asset":{"type":"passage","lines":["1호선: 해오름역 — 바람역 — 별빛역 — 달맞이역","2호선: 숲속역 — 별빛역 — 바닷가역","별빛역에서 1호선과 2호선이 만난다."],"title":"가상 지하철 노선도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#7','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',2,'ox','auto','여러 지도 가운데 가장 큰 지도 하나만 있으면 어떤 상황에서도 편리해요.',ARRAY['SO4-1-u1-X19']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"ox","stem":"여러 지도 가운데 가장 큰 지도 하나만 있으면 어떤 상황에서도 편리해요.","answer":"X","reason_options":[{"t":"지도마다 담긴 정보가 달라 상황과 목적에 맞는 지도를 골라야 하기 때문에","correct":true},{"t":"큰 지도에는 모든 정보가 다 들어 있기 때문에","mis":"SO4-1-u1-X19"}],"mis":"SO4-1-u1-X19","explanation":["지도마다 정보가 달라요.","상황에 맞게 골라요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_basic#8','soc',4,1,'u1','L06','g4_1_soc_u1_L06_basic','lesson_basic','SO4-1-u1-C6',2,'mc','auto','조선 시대 김정호가 만든 대동여지도에서 산의 크기와 높이는 무엇으로 짐작하게 했나요?',ARRAY['SO4-1-u1-X21']::text[],false,'{"seq":8,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"mc","stem":"조선 시대 김정호가 만든 대동여지도에서 산의 크기와 높이는 무엇으로 짐작하게 했나요?","options":[{"t":"선의 굵기","correct":true},{"t":"글자 크기","mis":"SO4-1-u1-X21"},{"t":"사진","mis":"SO4-1-u1-X21"},{"t":"색칠","mis":"SO4-1-u1-X21"}],"explanation":["산줄기를 이어 그렸어요.","선이 굵고 가늘어요.","선의 굵기예요."],"asset":{"type":"passage","lines":["조선 시대에 김정호가 만든 옛 지도이다.","산줄기를 이어 그리고 선의 굵기로 산의 크기와 높이를 짐작하게 했다.","여러 가지 기호를 쓰고 그 뜻을 모아 범례로 정리했다."],"title":"대동여지도 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
