INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#2','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',2,'ox','auto','대동여지도는 아주 옛날 지도라서 기호나 범례를 쓰지 않았어요.',ARRAY['SO4-1-u1-X21']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"ox","stem":"대동여지도는 아주 옛날 지도라서 기호나 범례를 쓰지 않았어요.","answer":"X","reason_options":[{"t":"대동여지도에도 여러 가지 기호를 쓰고 범례로 정리했기 때문에","correct":true},{"t":"옛 지도는 그림으로만 그렸기 때문에","mis":"SO4-1-u1-X21"}],"mis":"SO4-1-u1-X21","explanation":["옛 지도예요.","그래도 기호가 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["조선 시대에 김정호가 만든 옛 지도이다.","산줄기를 이어 그리고 선의 굵기로 산의 크기와 높이를 짐작하게 했다.","여러 가지 기호를 쓰고 그 뜻을 모아 범례로 정리했다."],"title":"대동여지도 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#3','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',3,'mc','auto','가상 지하철 노선도에서 바람역(1호선)에서 바닷가역(2호선)으로 가는 방법으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X20']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"mc","stem":"가상 지하철 노선도에서 바람역(1호선)에서 바닷가역(2호선)으로 가는 방법으로 알맞은 것은 무엇인가요?","options":[{"t":"1호선을 타고 별빛역에서 2호선으로 갈아타요","correct":true},{"t":"1호선만 타고 끝까지 가요","mis":"SO4-1-u1-X20"},{"t":"달맞이역에서 2호선으로 갈아타요","mis":"SO4-1-u1-X20"},{"t":"2호선만 타고 가요","mis":"SO4-1-u1-X20"}],"explanation":["노선이 달라요.","만나는 역이 있어요.","별빛역에서 갈아타요."],"asset":{"type":"passage","lines":["1호선: 해오름역 — 바람역 — 별빛역 — 달맞이역","2호선: 숲속역 — 별빛역 — 바닷가역","별빛역에서 1호선과 2호선이 만난다."],"title":"가상 지하철 노선도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#4','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',3,'error','auto','지도 활용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X20']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"error","stem":"지도 활용을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「약도에는 고장의 관광지가 모두 나와 있어.」","correct":true,"mis_target":"SO4-1-u1-X20"},{"t":"친구 나 — 「관광 안내도로 볼거리를 찾을 수 있어.」","mis":"SO4-1-u1-X20"},{"t":"친구 다 — 「노선도로 갈아탈 역을 찾을 수 있어.」","mis":"SO4-1-u1-X20"}],"explanation":["약도는 길을 간단히 그려요.","관광지는 관광 안내도예요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#5','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',3,'mc','auto','상황과 목적에 맞는 지도를 골라 쓰면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u1-X19']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"mc","stem":"상황과 목적에 맞는 지도를 골라 쓰면 좋은 점은 무엇인가요?","options":[{"t":"이동을 미리 계획할 수 있어 편리해요","correct":true},{"t":"어떤 지도든 같아서 고를 필요가 없어요","mis":"SO4-1-u1-X19"},{"t":"지도를 볼 필요가 없어져요","mis":"SO4-1-u1-X19"},{"t":"가장 큰 지도만 쓰게 돼요","mis":"SO4-1-u1-X19"}],"explanation":["지도마다 정보가 달라요.","맞는 것을 골라요.","미리 계획해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#6','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',3,'ox','auto','상황 ㉢처럼 다른 고장의 볼거리를 찾을 때는 관광 안내도가 알맞아요.',ARRAY['SO4-1-u1-X20']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"ox","stem":"상황 ㉢처럼 다른 고장의 볼거리를 찾을 때는 관광 안내도가 알맞아요.","answer":"O","reason_options":[{"t":"관광 안내도는 관광지가 어디에 있는지 알려 주기 때문에","correct":true},{"t":"관광 안내도는 지하철 갈아타는 곳만 알려 주기 때문에","mis":"SO4-1-u1-X20"}],"mis":"SO4-1-u1-X20","explanation":["볼거리를 찾아요.","관광지예요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 처음 가 보는 캠핑장에 자동차로 간다.","㉡ 생일잔치에 초대하며 우리 집 가는 길을 알려 준다.","㉢ 다른 고장에 놀러 가서 볼거리를 찾는다.","㉣ 지하철을 갈아타고 박물관에 간다."],"title":"지도가 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#7','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',3,'mc','auto','대동여지도에서 굵은 선으로 그린 산줄기는 가는 선으로 그린 산줄기와 견주어 어떤 산일까요?',ARRAY['SO4-1-u1-X21']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"mc","stem":"대동여지도에서 굵은 선으로 그린 산줄기는 가는 선으로 그린 산줄기와 견주어 어떤 산일까요?","options":[{"t":"더 크고 높은 산","correct":true},{"t":"더 작고 낮은 산","mis":"SO4-1-u1-X21"},{"t":"강이 흐르는 곳","mis":"SO4-1-u1-X21"},{"t":"사람이 많이 사는 곳","mis":"SO4-1-u1-X21"}],"explanation":["선의 굵기를 봐요.","굵을수록 커요.","크고 높은 산이에요."],"asset":{"type":"passage","lines":["조선 시대에 김정호가 만든 옛 지도이다.","산줄기를 이어 그리고 선의 굵기로 산의 크기와 높이를 짐작하게 했다.","여러 가지 기호를 쓰고 그 뜻을 모아 범례로 정리했다."],"title":"대동여지도 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#8','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',4,'essay','teacher','가족 여행 계획을 세워요. 네 상황 ㉠~㉣ 가운데 두 가지를 골라 어떤 지도를 쓸지와 그 까닭을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C6","difficulty":4,"kind":"essay","stem":"가족 여행 계획을 세워요. 네 상황 ㉠~㉣ 가운데 두 가지를 골라 어떤 지도를 쓸지와 그 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉠ 처음 가는 캠핑장에는 길 도우미를 쓸 거예요. 목적지를 넣으면 가장 좋은 길을 안내해 주기 때문이에요. ㉣ 지하철로 박물관에 갈 때는 지하철 노선도를 볼 거예요. 어느 역에서 갈아타야 하는지 알 수 있기 때문이에요.","scoring_points":["상황 두 가지를 골랐는가","상황에 맞는 지도를 골랐는가","지도가 알려 주는 정보로 까닭을 썼는가"]},"explanation":["상황을 골라요.","지도를 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 처음 가 보는 캠핑장에 자동차로 간다.","㉡ 생일잔치에 초대하며 우리 집 가는 길을 알려 준다.","㉢ 다른 고장에 놀러 가서 볼거리를 찾는다.","㉣ 지하철을 갈아타고 박물관에 간다."],"title":"지도가 필요한 네 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#9','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',4,'mc','auto','가상 지하철 노선도에서 달맞이역에서 숲속역으로 가는 사람이 지나는 역을 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['SO4-1-u1-X20']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C6","difficulty":4,"kind":"mc","stem":"가상 지하철 노선도에서 달맞이역에서 숲속역으로 가는 사람이 지나는 역을 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"달맞이역 → 별빛역(환승) → 숲속역","correct":true},{"t":"달맞이역 → 바람역 → 숲속역","mis":"SO4-1-u1-X20"},{"t":"달맞이역 → 바닷가역 → 숲속역","mis":"SO4-1-u1-X20"},{"t":"달맞이역 → 해오름역(환승) → 숲속역","mis":"SO4-1-u1-X20"}],"explanation":["달맞이역은 1호선이에요.","별빛역에서 2호선으로 갈아타요.","숲속역에 도착해요."],"asset":{"type":"passage","lines":["1호선: 해오름역 — 바람역 — 별빛역 — 달맞이역","2호선: 숲속역 — 별빛역 — 바닷가역","별빛역에서 1호선과 2호선이 만난다."],"title":"가상 지하철 노선도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L06_challenge#10','soc',4,1,'u1','L06','g4_1_soc_u1_L06_challenge','lesson_challenge','SO4-1-u1-C6',4,'essay','teacher','대동여지도와 오늘날의 길 도우미를 견주어 비슷한 점 하나와 다른 점 하나를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C6","difficulty":4,"kind":"essay","stem":"대동여지도와 오늘날의 길 도우미를 견주어 비슷한 점 하나와 다른 점 하나를 쓰세요.","answer_guide":{"answer":"예: 비슷한 점은 둘 다 땅의 모습을 약속된 표시로 나타내 장소를 찾게 해 준다는 거예요. 다른 점은 대동여지도는 종이에 그려 선의 굵기로 산의 높이를 나타냈지만, 길 도우미는 목적지를 넣으면 가장 좋은 길을 바로 안내해 준다는 거예요.","scoring_points":["비슷한 점을 썼는가","다른 점을 썼는가","두 지도의 특징을 바르게 썼는가"]},"explanation":["같은 점을 찾아요.","다른 점도 찾아요.","견주어 써요."],"asset":{"type":"passage","lines":["조선 시대에 김정호가 만든 옛 지도이다.","산줄기를 이어 그리고 선의 굵기로 산의 크기와 높이를 짐작하게 했다.","여러 가지 기호를 쓰고 그 뜻을 모아 범례로 정리했다."],"title":"대동여지도 알아보기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_basic#1','soc',4,1,'u1','L07','g4_1_soc_u1_L07_basic','lesson_basic','SO4-1-u1-C7',1,'mc','auto','지도에서 동서남북 방향을 알려 주는 것은 무엇인가요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C7","difficulty":1,"kind":"mc","stem":"지도에서 동서남북 방향을 알려 주는 것은 무엇인가요?","options":[{"t":"방위","correct":true},{"t":"축척","mis":"SO4-1-u1-X11"},{"t":"범례","mis":"SO4-1-u1-X11"},{"t":"등고선","mis":"SO4-1-u1-X11"}],"explanation":["방향이에요.","동서남북이에요.","방위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_basic#2','soc',4,1,'u1','L07','g4_1_soc_u1_L07_basic','lesson_basic','SO4-1-u1-C7',1,'mc','auto','지도에서 실제 거리를 줄여 나타낸 정도는 무엇인가요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C7","difficulty":1,"kind":"mc","stem":"지도에서 실제 거리를 줄여 나타낸 정도는 무엇인가요?","options":[{"t":"축척","correct":true},{"t":"방위","mis":"SO4-1-u1-X11"},{"t":"기호","mis":"SO4-1-u1-X11"},{"t":"등고선","mis":"SO4-1-u1-X11"}],"explanation":["거리를 줄였어요.","줄인 정도예요.","축척이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_basic#3','soc',4,1,'u1','L07','g4_1_soc_u1_L07_basic','lesson_basic','SO4-1-u1-C7',1,'sa','auto','은하마을 지도에서 병원은 학교의 어느 쪽에 있나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C7","difficulty":1,"kind":"sa","stem":"은하마을 지도에서 병원은 학교의 어느 쪽에 있나요? 두 글자로 쓰세요.","answer":["남쪽"],"explanation":["병원은 아래쪽이에요.","화살표는 위쪽이에요.","남쪽이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"},"mis":"SO4-1-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_basic#4','soc',4,1,'u1','L07','g4_1_soc_u1_L07_basic','lesson_basic','SO4-1-u1-C7',1,'ox','auto','등고선은 지도에서 땅의 높낮이를 알려 줘요.',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C7","difficulty":1,"kind":"ox","stem":"등고선은 지도에서 땅의 높낮이를 알려 줘요.","answer":"O","reason_options":[{"t":"높이가 같은 곳을 이어 높낮이를 나타내기 때문에","correct":true},{"t":"등고선은 실제 거리를 알려 주기 때문에","mis":"SO4-1-u1-X11"}],"mis":"SO4-1-u1-X11","explanation":["높이가 같은 곳을 이어요.","높낮이를 알아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_basic#5','soc',4,1,'u1','L07','g4_1_soc_u1_L07_basic','lesson_basic','SO4-1-u1-C7',2,'mc','auto','은하마을 지도에서 학교부터 병원까지의 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C7","difficulty":2,"kind":"mc","stem":"은하마을 지도에서 학교부터 병원까지의 실제 거리는 얼마인가요?","options":[{"t":"3 km","correct":true},{"t":"300 m","mis":"SO4-1-u1-X16"},{"t":"30 km","mis":"SO4-1-u1-X16"},{"t":"1 km","mis":"SO4-1-u1-X16"}],"explanation":["지도에서 3 cm 예요.","1 cm 가 1 km 예요.","3 km 예요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
