INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#1','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',2,'ox','auto','방위·기호·등고선·축척이 모두 담긴 지도에서는 여러 정보를 함께 정확히 알 수 있어요.',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C7","difficulty":2,"kind":"ox","stem":"방위·기호·등고선·축척이 모두 담긴 지도에서는 여러 정보를 함께 정확히 알 수 있어요.","answer":"O","reason_options":[{"t":"방향·장소·높낮이·거리 정보가 모두 담겨 있기 때문에","correct":true},{"t":"요소가 많을수록 복잡해서 아무것도 알 수 없기 때문에","mis":"SO4-1-u1-X11"}],"mis":"SO4-1-u1-X11","explanation":["요소가 모였어요.","정보가 많아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#2','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',2,'mc','auto','은하마을 지도에서 높낮이를 알고 싶을 때 살펴볼 요소는 무엇인가요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C7","difficulty":2,"kind":"mc","stem":"은하마을 지도에서 높낮이를 알고 싶을 때 살펴볼 요소는 무엇인가요?","options":[{"t":"등고선","correct":true},{"t":"방위표","mis":"SO4-1-u1-X11"},{"t":"축척 막대","mis":"SO4-1-u1-X11"},{"t":"범례","mis":"SO4-1-u1-X11"}],"explanation":["높낮이예요.","높이가 같은 선이에요.","등고선이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#3','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',3,'error','auto','은하마을 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X11','SO4-1-u1-X09','SO4-1-u1-X06']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"error","stem":"은하마을 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「축척 막대를 보면 학교가 어느 쪽인지 알 수 있어.」","correct":true,"mis_target":"SO4-1-u1-X11"},{"t":"친구 가 — 「깃발을 보면 학교를 찾을 수 있어.」","mis":"SO4-1-u1-X09"},{"t":"친구 나 — 「병원은 학교의 남쪽이야.」","mis":"SO4-1-u1-X06"}],"explanation":["축척은 거리예요.","방향은 방위예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#4','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',3,'mc','auto','은하마을 지도에서 학교부터 병원과 우체국까지의 실제 거리를 견주면 어떠한가요?',ARRAY['SO4-1-u1-X16']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"mc","stem":"은하마을 지도에서 학교부터 병원과 우체국까지의 실제 거리를 견주면 어떠한가요?","options":[{"t":"병원이 우체국보다 1 km 더 멀어요","correct":true},{"t":"우체국이 병원보다 1 km 더 멀어요","mis":"SO4-1-u1-X16"},{"t":"두 곳의 거리가 같아요","mis":"SO4-1-u1-X16"},{"t":"병원이 우체국보다 1 cm 더 멀어요","mis":"SO4-1-u1-X16"}],"explanation":["병원 3 km 예요.","우체국 2 km 예요.","병원이 1 km 더 멀어요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#5','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',3,'mc','auto','은하마을 지도에서 강을 따라 걷고 싶어요. 범례에서 찾아야 할 것과 그것이 뜻하는 것을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-1-u1-X09']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"mc","stem":"은하마을 지도에서 강을 따라 걷고 싶어요. 범례에서 찾아야 할 것과 그것이 뜻하는 것을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"파란 선 — 강","correct":true},{"t":"파란 선 — 도로","mis":"SO4-1-u1-X09"},{"t":"초록 세모 — 강","mis":"SO4-1-u1-X09"},{"t":"깃발 — 강","mis":"SO4-1-u1-X09"}],"explanation":["범례를 봐요.","강을 찾아요.","파란 선이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#6','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',3,'ox','auto','은하마을 지도에서 산은 학교의 북쪽에 있으니 학교의 위쪽에 그려져 있어요.',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"ox","stem":"은하마을 지도에서 산은 학교의 북쪽에 있으니 학교의 위쪽에 그려져 있어요.","answer":"O","reason_options":[{"t":"방위표의 화살표가 위쪽을 가리켜 위쪽이 북쪽이기 때문에","correct":true},{"t":"북쪽은 언제나 지도의 아래쪽이기 때문에","mis":"SO4-1-u1-X06"}],"mis":"SO4-1-u1-X06","explanation":["화살표는 위쪽이에요.","북쪽은 위쪽이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#7','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',3,'mc','auto','은하마을 지도에서 같은 축척으로 학교부터 강까지 지도상 거리가 5 cm 였어요. 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16','SO4-1-u1-X18']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"mc","stem":"은하마을 지도에서 같은 축척으로 학교부터 강까지 지도상 거리가 5 cm 였어요. 실제 거리는 얼마인가요?","options":[{"t":"5 km","correct":true},{"t":"50 km","mis":"SO4-1-u1-X16"},{"t":"500 m","mis":"SO4-1-u1-X16"},{"t":"5 cm","mis":"SO4-1-u1-X18"}],"explanation":["1 cm 가 1 km 예요.","5 cm 예요.","5 km 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#8','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',4,'essay','teacher','은하마을 지도에서 병원을 찾아가는 방법을 방위·기호와 범례·축척을 모두 써서 설명하세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C7","difficulty":4,"kind":"essay","stem":"은하마을 지도에서 병원을 찾아가는 방법을 방위·기호와 범례·축척을 모두 써서 설명하세요.","answer_guide":{"answer":"예: 범례에서 ＋ 기호가 병원이라는 것을 확인해요. 방위표를 보면 위쪽이 북쪽이라서 병원은 학교의 남쪽에 있어요. 축척 막대가 1 cm = 1 km 이고 지도상 거리가 3 cm 이므로 학교에서 남쪽으로 3 km 가면 병원이에요.","scoring_points":["범례로 병원 기호를 찾았는가","방위로 남쪽이라고 썼는가","축척으로 3 km 를 구했는가"]},"explanation":["기호를 찾아요.","방향을 봐요.","거리를 구해요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","범례 — 깃발 학교 · ＋ 병원 · 파란 선 강 · 제비 모양 우체국","등고선 — 학교 북쪽에 산이 있고, 가장 안쪽 원에 400","축척 막대 — 1 cm = 1 km","학교 ~ 병원: 지도에서 3 cm, 병원은 학교의 아래쪽","학교 ~ 우체국: 지도에서 2 cm, 우체국은 학교의 오른쪽"],"title":"은하마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#9','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',4,'mc','auto','어떤 지도에 방위표·범례·축척 막대는 있는데 등고선이 없어요. 이 지도로 알기 어려운 것은 무엇인가요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C7","difficulty":4,"kind":"mc","stem":"어떤 지도에 방위표·범례·축척 막대는 있는데 등고선이 없어요. 이 지도로 알기 어려운 것은 무엇인가요?","options":[{"t":"산의 높낮이와 경사","correct":true},{"t":"장소 사이의 실제 거리","mis":"SO4-1-u1-X11"},{"t":"장소가 있는 방향","mis":"SO4-1-u1-X11"},{"t":"기호가 뜻하는 장소","mis":"SO4-1-u1-X11"}],"explanation":["없는 요소를 찾아요.","등고선이 없어요.","높낮이를 알기 어려워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L07_challenge#10','soc',4,1,'u1','L07','g4_1_soc_u1_L07_challenge','lesson_challenge','SO4-1-u1-C7',4,'essay','teacher','지도 요소 네 가지 가운데 하나가 빠진 지도를 쓴다면 무엇이 가장 불편할지 하나를 골라 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C7","difficulty":4,"kind":"essay","stem":"지도 요소 네 가지 가운데 하나가 빠진 지도를 쓴다면 무엇이 가장 불편할지 하나를 골라 까닭을 쓰세요.","answer_guide":{"answer":"예: 축척이 빠지면 가장 불편할 것 같아요. 지도에서 두 장소가 얼마나 떨어져 있는지 실제 거리를 알 수 없어서 걸어갈지 차를 탈지 계획하기 어렵기 때문이에요.","scoring_points":["빠진 요소 하나를 골랐는가","그 요소가 알려 주는 정보를 바르게 썼는가","불편한 까닭을 썼는가"]},"explanation":["요소를 골라요.","하는 일을 떠올려요.","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#1','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',1,'mc','auto','어떤 곳이 다른 곳을 기준으로 어디쯤에 있는지를 나타낸 것을 무엇이라고 하나요?',ARRAY['SO4-1-u1-X22']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C8","difficulty":1,"kind":"mc","stem":"어떤 곳이 다른 곳을 기준으로 어디쯤에 있는지를 나타낸 것을 무엇이라고 하나요?","options":[{"t":"위치","correct":true},{"t":"넓이","mis":"SO4-1-u1-X22"},{"t":"이름","mis":"SO4-1-u1-X22"},{"t":"날씨","mis":"SO4-1-u1-X22"}],"explanation":["어디쯤이에요.","기준이 있어요.","위치예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#2','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',1,'mc','auto','산·강·들·바다처럼 땅이 이루는 여러 가지 생김새를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X23']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C8","difficulty":1,"kind":"mc","stem":"산·강·들·바다처럼 땅이 이루는 여러 가지 생김새를 무엇이라고 하나요?","options":[{"t":"지형","correct":true},{"t":"지도","mis":"SO4-1-u1-X23"},{"t":"기호","mis":"SO4-1-u1-X23"},{"t":"축척","mis":"SO4-1-u1-X23"}],"explanation":["땅의 생김새예요.","지◯이에요.","지형이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#3','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',1,'sa','auto','넓고 평평하게 펼쳐져 농사를 짓기 좋은 땅을 들 또는 ○○이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C8","difficulty":1,"kind":"sa","stem":"넓고 평평하게 펼쳐져 농사를 짓기 좋은 땅을 들 또는 ○○이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["평야"],"explanation":["넓고 평평해요.","평◯예요.","평야예요."],"mis":"SO4-1-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#4','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',1,'ox','auto','우뚝 솟은 높은 땅을 산이라고 해요.',ARRAY['SO4-1-u1-X23']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C8","difficulty":1,"kind":"ox","stem":"우뚝 솟은 높은 땅을 산이라고 해요.","answer":"O","reason_options":[{"t":"산은 주변보다 높이 솟은 땅이기 때문에","correct":true},{"t":"산은 넓고 평평한 땅이기 때문에","mis":"SO4-1-u1-X23"}],"mis":"SO4-1-u1-X23","explanation":["솟아 있어요.","높아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#5','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',2,'mc','auto','해솔군의 위치를 알맞게 나타낸 말은 무엇인가요?',ARRAY['SO4-1-u1-X22']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"mc","stem":"해솔군의 위치를 알맞게 나타낸 말은 무엇인가요?","options":[{"t":"○○도의 남쪽에 있고 북쪽으로 바람시와 맞닿아 있어요","correct":true},{"t":"벼농사를 많이 해요","mis":"SO4-1-u1-X22"},{"t":"사람이 아주 많아요","mis":"SO4-1-u1-X22"},{"t":"날씨가 따뜻해요","mis":"SO4-1-u1-X22"}],"explanation":["방위가 있어요.","이웃 지역이 있어요.","그것이 위치예요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#6','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',2,'mc','auto','해솔군 소개에서 동쪽에 있는 지형은 무엇인가요?',ARRAY['SO4-1-u1-X23']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"mc","stem":"해솔군 소개에서 동쪽에 있는 지형은 무엇인가요?","options":[{"t":"바다","correct":true},{"t":"산","mis":"SO4-1-u1-X23"},{"t":"들","mis":"SO4-1-u1-X23"},{"t":"사막","mis":"SO4-1-u1-X23"}],"explanation":["동쪽을 찾아요.","물이 넓게 있어요.","바다예요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#7','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',2,'ox','auto','해솔군에서 벼농사를 많이 하는 것은 넓고 평평한 들이 있기 때문이에요.',ARRAY['SO4-1-u1-X24']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"ox","stem":"해솔군에서 벼농사를 많이 하는 것은 넓고 평평한 들이 있기 때문이에요.","answer":"O","reason_options":[{"t":"들은 평평해서 농사를 짓기 좋기 때문에","correct":true},{"t":"지형은 사람들이 하는 일과 관계없기 때문에","mis":"SO4-1-u1-X24"}],"mis":"SO4-1-u1-X24","explanation":["들이 있어요.","농사짓기 좋아요.","그래서 O예요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#8','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',2,'blank','auto','지도에서 우리 지역의 위치를 나타낼 때는 (    )과 이웃한 지역을 기준으로 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u1-X22']::text[],false,'{"seq":8,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"blank","stem":"지도에서 우리 지역의 위치를 나타낼 때는 (    )과 이웃한 지역을 기준으로 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"방위","correct":true},{"t":"크기","mis":"SO4-1-u1-X22"},{"t":"날씨","mis":"SO4-1-u1-X22"},{"t":"색깔","mis":"SO4-1-u1-X22"}],"explanation":["동서남북이에요.","방◯예요.","방위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#9','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',2,'match','auto','지형과 그 생김새를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"match","stem":"지형과 그 생김새를 알맞게 이으세요.","pairs":[{"l":"산","r":"우뚝 솟은 높은 땅"},{"l":"들","r":"넓고 평평한 땅"},{"l":"강","r":"물이 흘러가는 길"},{"l":"섬","r":"바다로 둘러싸인 땅"}],"mis":"SO4-1-u1-X23","explanation":["솟았어요.","평평해요.","물로 둘러싸였어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_basic#10','soc',4,1,'u1','L08','g4_1_soc_u1_L08_basic','lesson_basic','SO4-1-u1-C8',3,'mc','auto','지역마다 지형이 다르다는 것을 알면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u1-X24']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C8","difficulty":3,"kind":"mc","stem":"지역마다 지형이 다르다는 것을 알면 좋은 점은 무엇인가요?","options":[{"t":"지역의 특성과 사람들의 생활 모습을 이해할 수 있어요","correct":true},{"t":"모든 지역이 똑같다는 것을 알 수 있어요","mis":"SO4-1-u1-X24"},{"t":"날씨를 바꿀 수 있어요","mis":"SO4-1-u1-X24"},{"t":"지형은 아무 쓸모가 없어요","mis":"SO4-1-u1-X24"}],"explanation":["지형이 달라요.","생활도 달라요.","특성을 이해해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#1','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',2,'ox','auto','「해솔군은 사람이 많고 시장이 커요.」는 해솔군의 위치를 나타낸 말이에요.',ARRAY['SO4-1-u1-X22']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"ox","stem":"「해솔군은 사람이 많고 시장이 커요.」는 해솔군의 위치를 나타낸 말이에요.","answer":"X","reason_options":[{"t":"위치는 방위와 이웃 지역을 기준으로 어디쯤 있는지를 나타내기 때문에","correct":true},{"t":"사람 수와 시장 크기도 위치이기 때문에","mis":"SO4-1-u1-X22"}],"mis":"SO4-1-u1-X22","explanation":["사람 수는 위치가 아니에요.","방위가 없어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#2','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',2,'mc','auto','해솔군 바다에서 볼 수 있는 지형으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X23']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"mc","stem":"해솔군 바다에서 볼 수 있는 지형으로 알맞은 것은 무엇인가요?","options":[{"t":"작은 섬","correct":true},{"t":"높은 산맥","mis":"SO4-1-u1-X23"},{"t":"넓은 사막","mis":"SO4-1-u1-X23"},{"t":"깊은 골짜기","mis":"SO4-1-u1-X23"}],"explanation":["바다를 찾아요.","섬이 여럿 있어요.","작은 섬이에요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#3','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',3,'mc','auto','해솔군에서 강은 어느 쪽으로 흐르나요?',ARRAY['SO4-1-u1-X06','SO4-1-u1-X23']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C8","difficulty":3,"kind":"mc","stem":"해솔군에서 강은 어느 쪽으로 흐르나요?","options":[{"t":"들을 지나 동쪽 바다로","correct":true},{"t":"들을 지나 서쪽 산으로","mis":"SO4-1-u1-X06"},{"t":"바다에서 산으로","mis":"SO4-1-u1-X23"},{"t":"흐르지 않아요","mis":"SO4-1-u1-X23"}],"explanation":["강을 찾아요.","바다로 흘러요.","동쪽 바다예요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#4','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',3,'error','auto','해솔군 소개를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X23','SO4-1-u1-X22']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C8","difficulty":3,"kind":"error","stem":"해솔군 소개를 읽고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「해솔군 서쪽에는 넓고 평평한 들이 있어.」","correct":true,"mis_target":"SO4-1-u1-X23"},{"t":"친구 가 — 「해솔군 동쪽에는 바다가 있어.」","mis":"SO4-1-u1-X23"},{"t":"친구 다 — 「해솔군은 ○○도의 남쪽에 있어.」","mis":"SO4-1-u1-X22"}],"explanation":["서쪽에는 산이 있어요.","들은 가운데예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#5','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',3,'mc','auto','해솔군 바닷가에서 고기잡이를 많이 하는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X24','SO4-1-u1-X23']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C8","difficulty":3,"kind":"mc","stem":"해솔군 바닷가에서 고기잡이를 많이 하는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"바다가 가까운 지형이기 때문이에요","correct":true},{"t":"높은 산이 가까운 지형이기 때문이에요","mis":"SO4-1-u1-X24"},{"t":"지형과 관계없이 우연히 정했기 때문이에요","mis":"SO4-1-u1-X24"},{"t":"강이 없기 때문이에요","mis":"SO4-1-u1-X23"}],"explanation":["바닷가예요.","바다가 있어요.","지형 때문이에요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#6','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',3,'ox','auto','바람시에서 보면 해솔군은 바람시의 남쪽에 있어요.',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C8","difficulty":3,"kind":"ox","stem":"바람시에서 보면 해솔군은 바람시의 남쪽에 있어요.","answer":"O","reason_options":[{"t":"해솔군의 북쪽에 바람시가 맞닿아 있기 때문에","correct":true},{"t":"해솔군이 바람시의 북쪽에 있기 때문에","mis":"SO4-1-u1-X06"}],"mis":"SO4-1-u1-X06","explanation":["해솔군 북쪽에 바람시가 있어요.","거꾸로 보면 남쪽이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#7','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',3,'mc','auto','산이 많은 지역의 사람들이 들이 넓은 지역의 사람들과 다르게 살아갈 수 있는 까닭은 무엇인가요?',ARRAY['SO4-1-u1-X24']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C8","difficulty":3,"kind":"mc","stem":"산이 많은 지역의 사람들이 들이 넓은 지역의 사람들과 다르게 살아갈 수 있는 까닭은 무엇인가요?","options":[{"t":"지형에 따라 할 수 있는 일과 생활 모습이 달라지기 때문이에요","correct":true},{"t":"지형은 생활과 관계없기 때문이에요","mis":"SO4-1-u1-X24"},{"t":"모든 지역의 지형이 같기 때문이에요","mis":"SO4-1-u1-X24"},{"t":"산이 많으면 사람이 살 수 없기 때문이에요","mis":"SO4-1-u1-X24"}],"explanation":["지형이 달라요.","하는 일이 달라요.","생활이 달라져요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#8','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',4,'essay','teacher','해솔군 소개를 보고 해솔군의 위치를 방위와 이웃 지역으로 한 문장으로 쓰고, 지형 두 가지를 골라 그 지형과 이어지는 생활 모습을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C8","difficulty":4,"kind":"essay","stem":"해솔군 소개를 보고 해솔군의 위치를 방위와 이웃 지역으로 한 문장으로 쓰고, 지형 두 가지를 골라 그 지형과 이어지는 생활 모습을 쓰세요.","answer_guide":{"answer":"예: 해솔군은 ○○도의 남쪽에 있고 북쪽으로 바람시와 맞닿아 있어요. 가운데 넓은 들에서는 벼농사를 짓고, 동쪽 바다에서는 고기잡이를 해요.","scoring_points":["방위와 이웃 지역으로 위치를 썼는가","지형 두 가지를 바르게 골랐는가","지형과 생활 모습을 이었는가"]},"explanation":["위치를 써요.","지형을 골라요.","생활과 이어요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#9','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',4,'mc','auto','해솔군에 놀이공원을 새로 짓는다면 지형으로 볼 때 가장 알맞은 곳과 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u1-X23','SO4-1-u1-X24']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C8","difficulty":4,"kind":"mc","stem":"해솔군에 놀이공원을 새로 짓는다면 지형으로 볼 때 가장 알맞은 곳과 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"가운데 들 — 넓고 평평해서 큰 시설을 짓기 좋아요","correct":true},{"t":"서쪽 산 — 높이 솟아 있어서 짓기 쉬워요","mis":"SO4-1-u1-X23"},{"t":"바다 위 — 물 위라서 땅이 넓어요","mis":"SO4-1-u1-X23"},{"t":"어디든 같아요 — 지형은 관계없어요","mis":"SO4-1-u1-X24"}],"explanation":["넓고 평평한 곳이 좋아요.","들이에요.","가운데 들이에요."],"asset":{"type":"passage","lines":["해솔군은 ○○도의 남쪽에 있고, 북쪽으로 바람시와 맞닿아 있다.","해솔군의 동쪽에는 바다가 있고, 서쪽에는 우뚝 솟은 산이 있다.","가운데에는 넓고 평평한 들이 펼쳐져 있다.","강이 들을 지나 동쪽 바다로 흐르고, 바다에는 작은 섬이 여럿 있다.","들에서는 벼농사를, 바닷가에서는 고기잡이를 많이 한다."],"title":"해솔군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L08_challenge#10','soc',4,1,'u1','L08','g4_1_soc_u1_L08_challenge','lesson_challenge','SO4-1-u1-C8',4,'essay','teacher','우리 지역을 처음 보는 친구에게 소개한다면 위치와 지형을 어떻게 설명할지 쓰세요. (지역 이름은 ○○로 써도 돼요)','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C8","difficulty":4,"kind":"essay","stem":"우리 지역을 처음 보는 친구에게 소개한다면 위치와 지형을 어떻게 설명할지 쓰세요. (지역 이름은 ○○로 써도 돼요)","answer_guide":{"answer":"예: 우리 ○○시는 ○○도의 북쪽에 있고 남쪽으로 ○○군과 맞닿아 있어요. 동쪽에는 높은 산이 있고 가운데로 강이 흘러요. 강가에는 넓은 들이 있어 농사를 지어요.","scoring_points":["방위로 위치를 썼는가","이웃 지역을 썼는가","지형을 하나 이상 썼는가"]},"explanation":["위치부터 써요.","이웃 지역을 써요.","지형을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_basic#1','soc',4,1,'u1','L09','g4_1_soc_u1_L09_basic','lesson_basic','SO4-1-u1-C9',1,'mc','auto','어떤 지역의 땅이 차지하는 넓이를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X25','SO4-1-u1-X22']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C9","difficulty":1,"kind":"mc","stem":"어떤 지역의 땅이 차지하는 넓이를 무엇이라고 하나요?","options":[{"t":"면적","correct":true},{"t":"인구","mis":"SO4-1-u1-X25"},{"t":"위치","mis":"SO4-1-u1-X22"},{"t":"방위","mis":"SO4-1-u1-X22"}],"explanation":["넓이예요.","면◯이에요.","면적이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_basic#2','soc',4,1,'u1','L09','g4_1_soc_u1_L09_basic','lesson_basic','SO4-1-u1-C9',1,'mc','auto','어떤 지역에 사는 사람의 수를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X25','SO4-1-u1-X23']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C9","difficulty":1,"kind":"mc","stem":"어떤 지역에 사는 사람의 수를 무엇이라고 하나요?","options":[{"t":"인구","correct":true},{"t":"면적","mis":"SO4-1-u1-X25"},{"t":"지형","mis":"SO4-1-u1-X23"},{"t":"넓이","mis":"SO4-1-u1-X25"}],"explanation":["사람의 수예요.","인◯예요.","인구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_basic#3','soc',4,1,'u1','L09','g4_1_soc_u1_L09_basic','lesson_basic','SO4-1-u1-C9',1,'sa','auto','세 지역의 면적과 인구 표에서 면적이 가장 넓은 지역은 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C9","difficulty":1,"kind":"sa","stem":"세 지역의 면적과 인구 표에서 면적이 가장 넓은 지역은 어디인가요? 세 글자로 쓰세요.","answer":["해솔군"],"explanation":["면적을 견줘요.","600 km² 예요.","해솔군이에요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","해솔군 — 600 km² — 5만 명","바람시 — 150 km² — 40만 명","푸른군 — 300 km² — 8만 명"],"title":"세 지역의 면적과 인구"},"mis":"SO4-1-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_basic#4','soc',4,1,'u1','L09','g4_1_soc_u1_L09_basic','lesson_basic','SO4-1-u1-C9',1,'ox','auto','인구 막대그래프에서 막대가 길수록 인구가 많아요.',ARRAY['SO4-1-u1-X26']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C9","difficulty":1,"kind":"ox","stem":"인구 막대그래프에서 막대가 길수록 인구가 많아요.","answer":"O","reason_options":[{"t":"막대가 길수록 값이 크기 때문에","correct":true},{"t":"막대가 짧을수록 값이 크기 때문에","mis":"SO4-1-u1-X26"}],"mis":"SO4-1-u1-X26","explanation":["막대를 봐요.","길수록 커요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
