INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_basic#10','soc',4,1,'u1','L09','g4_1_soc_u1_L09_basic','lesson_basic','SO4-1-u1-C9',3,'mc','auto','우리 지역의 면적과 인구를 알면 무엇에 도움이 되나요?',ARRAY['SO4-1-u1-X25']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C9","difficulty":3,"kind":"mc","stem":"우리 지역의 면적과 인구를 알면 무엇에 도움이 되나요?","options":[{"t":"지역의 특성을 이해하고 학교·공원 같은 시설을 계획하는 데 도움이 돼요","correct":true},{"t":"날씨를 마음대로 바꿀 수 있어요","mis":"SO4-1-u1-X25"},{"t":"모든 지역이 똑같다는 것을 알 수 있어요","mis":"SO4-1-u1-X25"},{"t":"면적과 인구는 쓸모가 없어요","mis":"SO4-1-u1-X25"}],"explanation":["사람이 얼마나 사나요?","땅이 얼마나 넓나요?","계획에 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_challenge#1','soc',4,1,'u1','L09','g4_1_soc_u1_L09_challenge','lesson_challenge','SO4-1-u1-C9',2,'ox','auto','해솔군은 면적이 가장 넓으니 인구도 가장 많아요.',ARRAY['SO4-1-u1-X25']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C9","difficulty":2,"kind":"ox","stem":"해솔군은 면적이 가장 넓으니 인구도 가장 많아요.","answer":"X","reason_options":[{"t":"해솔군은 면적이 가장 넓지만 인구는 5만 명으로 가장 적기 때문에","correct":true},{"t":"면적이 넓으면 인구도 반드시 많기 때문에","mis":"SO4-1-u1-X25"}],"mis":"SO4-1-u1-X25","explanation":["면적은 가장 넓어요.","인구는 가장 적어요.","그래서 X예요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","해솔군 — 600 km² — 5만 명","바람시 — 150 km² — 40만 명","푸른군 — 300 km² — 8만 명"],"title":"세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
