INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_challenge#4','soc',4,1,'u1','L09','g4_1_soc_u1_L09_challenge','lesson_challenge','SO4-1-u1-C9',3,'error','auto','세 지역의 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X25']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C9","difficulty":3,"kind":"error","stem":"세 지역의 표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「푸른군은 해솔군보다 넓어.」","correct":true,"mis_target":"SO4-1-u1-X25"},{"t":"친구 가 — 「푸른군은 해솔군보다 사람이 많이 살아.」","mis":"SO4-1-u1-X25"},{"t":"친구 나 — 「바람시가 가장 좁아.」","mis":"SO4-1-u1-X25"}],"explanation":["푸른군 300 km² 예요.","해솔군 600 km² 예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","해솔군 — 600 km² — 5만 명","바람시 — 150 km² — 40만 명","푸른군 — 300 km² — 8만 명"],"title":"세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
