INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_challenge#6','soc',4,1,'u1','L09','g4_1_soc_u1_L09_challenge','lesson_challenge','SO4-1-u1-C9',3,'ox','auto','두 지역을 지도로 볼 때 더 넓게 그려진 지역이 면적이 더 넓어요.',ARRAY['SO4-1-u1-X25']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C9","difficulty":3,"kind":"ox","stem":"두 지역을 지도로 볼 때 더 넓게 그려진 지역이 면적이 더 넓어요.","answer":"O","reason_options":[{"t":"같은 축척의 지도에서 넓게 그려질수록 땅이 넓기 때문에","correct":true},{"t":"넓게 그려진 지역은 인구가 반드시 많기 때문에","mis":"SO4-1-u1-X25"}],"mis":"SO4-1-u1-X25","explanation":["넓게 그려졌어요.","땅이 넓어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_challenge#7','soc',4,1,'u1','L09','g4_1_soc_u1_L09_challenge','lesson_challenge','SO4-1-u1-C9',3,'match','auto','낱말과 그 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C9","difficulty":3,"kind":"match","stem":"낱말과 그 뜻을 알맞게 이으세요.","pairs":[{"l":"면적","r":"땅이 차지하는 넓이"},{"l":"인구","r":"지역에 사는 사람의 수"},{"l":"km²","r":"넓이를 나타내는 단위"}],"mis":"SO4-1-u1-X25","explanation":["넓이예요.","사람 수예요.","단위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_challenge#8','soc',4,1,'u1','L09','g4_1_soc_u1_L09_challenge','lesson_challenge','SO4-1-u1-C9',4,'essay','teacher','바람시와 해솔군의 인구 그래프를 견주어 두 지역의 인구가 어떻게 달라지고 있는지 쓰고, 그렇게 판단한 근거를 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C9","difficulty":4,"kind":"essay","stem":"바람시와 해솔군의 인구 그래프를 견주어 두 지역의 인구가 어떻게 달라지고 있는지 쓰고, 그렇게 판단한 근거를 쓰세요.","answer_guide":{"answer":"예: 바람시는 인구가 점점 늘고 있고, 해솔군은 점점 줄고 있어요. 바람시는 30만 명 → 35만 명 → 40만 명으로 많아지고, 해솔군은 9만 명 → 7만 명 → 5만 명으로 적어지기 때문이에요.","scoring_points":["바람시 인구가 는다고 썼는가","해솔군 인구가 준다고 썼는가","해마다의 인구 변화를 근거로 들었는가"]},"explanation":["바람시 막대를 봐요.","해솔군 막대를 봐요.","근거를 써요."],"asset":{"type":"passage","lines":["바람시 — 10년 전 30만 명 · 5년 전 35만 명 · 올해 40만 명","해솔군 — 10년 전 9만 명 · 5년 전 7만 명 · 올해 5만 명"],"title":"두 지역 인구 그래프(표로 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_challenge#9','soc',4,1,'u1','L09','g4_1_soc_u1_L09_challenge','lesson_challenge','SO4-1-u1-C9',4,'mc','auto','인구가 점점 늘고 있는 바람시에 가장 먼저 필요할 것 같은 계획은 무엇인가요?',ARRAY['SO4-1-u1-X26','SO4-1-u1-X25']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C9","difficulty":4,"kind":"mc","stem":"인구가 점점 늘고 있는 바람시에 가장 먼저 필요할 것 같은 계획은 무엇인가요?","options":[{"t":"학교·도로 같은 시설을 늘리는 계획","correct":true},{"t":"사람이 없으니 시설을 줄이는 계획","mis":"SO4-1-u1-X26"},{"t":"땅을 넓히는 계획만 세우기","mis":"SO4-1-u1-X25"},{"t":"아무 계획도 필요 없어요","mis":"SO4-1-u1-X25"}],"explanation":["사람이 늘어요.","시설이 더 필요해요.","늘리는 계획이에요."],"asset":{"type":"lgraph","xs":["10년 전","5년 전","올해"],"series":[{"vals":[30,35,40]}],"step":5,"ymax":45,"mode":"bar","title":"바람시 인구","ylab":"만 명"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L09_challenge#10','soc',4,1,'u1','L09','g4_1_soc_u1_L09_challenge','lesson_challenge','SO4-1-u1-C9',4,'essay','teacher','세 지역의 면적과 인구 표를 보고, 「면적이 넓으면 인구도 많다」는 말이 맞는지 판단하고 근거를 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C9","difficulty":4,"kind":"essay","stem":"세 지역의 면적과 인구 표를 보고, 「면적이 넓으면 인구도 많다」는 말이 맞는지 판단하고 근거를 쓰세요.","answer_guide":{"answer":"예: 맞지 않아요. 해솔군은 면적이 600 km² 로 가장 넓지만 인구는 5만 명으로 가장 적고, 바람시는 면적이 150 km² 로 가장 좁지만 인구는 40만 명으로 가장 많기 때문이에요.","scoring_points":["맞지 않다고 판단했는가","해솔군 또는 바람시의 수를 근거로 들었는가","면적과 인구가 다른 정보라고 이해했는가"]},"explanation":["면적을 견줘요.","인구를 견줘요.","판단해요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","해솔군 — 600 km² — 5만 명","바람시 — 150 km² — 40만 명","푸른군 — 300 km² — 8만 명"],"title":"세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
