INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#3','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',1,'sa','auto','해솔군 기온 그래프에서 기온이 가장 높은 달은 몇 월인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C10","difficulty":1,"kind":"sa","stem":"해솔군 기온 그래프에서 기온이 가장 높은 달은 몇 월인가요? 숫자만 쓰세요.","answer":["7"],"explanation":["꺾은선을 봐요.","가장 높은 점이에요.","7월이에요."],"asset":{"type":"lgraph","xs":["1월","4월","7월","10월"],"series":[{"vals":[2,14,26,16]}],"step":2,"ymax":30,"mode":"line","title":"해솔군 기온","ylab":"°C"},"mis":"SO4-1-u1-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#4','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',1,'ox','auto','우리나라는 여름에 기온이 가장 높아요.',ARRAY['SO4-1-u1-X29']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C10","difficulty":1,"kind":"ox","stem":"우리나라는 여름에 기온이 가장 높아요.","answer":"O","reason_options":[{"t":"여름에 덥고 겨울에 춥기 때문에","correct":true},{"t":"겨울에 기온이 가장 높기 때문에","mis":"SO4-1-u1-X29"}],"mis":"SO4-1-u1-X29","explanation":["계절을 떠올려요.","여름이 더워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#5','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',2,'mc','auto','기온을 나타낼 때 쓰는 단위는 무엇인가요?',ARRAY['SO4-1-u1-X27']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"mc","stem":"기온을 나타낼 때 쓰는 단위는 무엇인가요?","options":[{"t":"도(°C)","correct":true},{"t":"밀리미터(mm)","mis":"SO4-1-u1-X27"},{"t":"제곱킬로미터(km²)","mis":"SO4-1-u1-X27"},{"t":"명","mis":"SO4-1-u1-X27"}],"explanation":["따뜻한 정도예요.","°C 예요.","도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#6','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',2,'mc','auto','해솔군 강수량 그래프에서 비가 가장 많이 내린 달은 몇 월인가요?',ARRAY['SO4-1-u1-X26']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"mc","stem":"해솔군 강수량 그래프에서 비가 가장 많이 내린 달은 몇 월인가요?","options":[{"t":"7월","correct":true},{"t":"1월","mis":"SO4-1-u1-X26"},{"t":"4월","mis":"SO4-1-u1-X26"},{"t":"10월","mis":"SO4-1-u1-X26"}],"explanation":["막대를 봐요.","가장 긴 막대예요.","7월이에요."],"asset":{"type":"lgraph","xs":["1월","4월","7월","10월"],"series":[{"vals":[50,100,300,50]}],"step":50,"ymax":350,"mode":"bar","title":"해솔군 강수량","ylab":"mm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#7','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',2,'ox','auto','기후 그래프에서 기온은 막대로, 강수량은 꺾은선으로 나타내요.',ARRAY['SO4-1-u1-X28']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"ox","stem":"기후 그래프에서 기온은 막대로, 강수량은 꺾은선으로 나타내요.","answer":"X","reason_options":[{"t":"보통 기온은 꺾은선, 강수량은 막대로 나타내기 때문에","correct":true},{"t":"기온은 언제나 막대로 나타내기 때문에","mis":"SO4-1-u1-X28"}],"mis":"SO4-1-u1-X28","explanation":["기온은 꺾은선이에요.","강수량은 막대예요.","그래서 X예요."],"asset":{"type":"passage","lines":["기온 — 빨간 꺾은선, 왼쪽 눈금(°C)","강수량 — 파란 막대, 오른쪽 눈금(mm)","꺾은선은 7월에 가장 높고 1월에 가장 낮다.","막대는 7월에 가장 길고 1월에 가장 짧다."],"title":"해솔군 기후 그래프 읽는 법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#8','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',2,'blank','auto','기온과 강수량을 함께 나타내 그 지역 날씨의 특징을 한눈에 보여 주는 그래프를 (    )라고 해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-1-u1-X27']::text[],false,'{"seq":8,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"blank","stem":"기온과 강수량을 함께 나타내 그 지역 날씨의 특징을 한눈에 보여 주는 그래프를 (    )라고 해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"기후 그래프","correct":true},{"t":"인구 그래프","mis":"SO4-1-u1-X27"},{"t":"사진첩","mis":"SO4-1-u1-X27"},{"t":"범례","mis":"SO4-1-u1-X27"}],"explanation":["기온과 강수량을 함께요.","날씨 특징이에요.","기후 그래프예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#9','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',2,'mc','auto','우리나라에서 강수량이 가장 많은 계절은 언제인가요?',ARRAY['SO4-1-u1-X29']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"mc","stem":"우리나라에서 강수량이 가장 많은 계절은 언제인가요?","options":[{"t":"여름","correct":true},{"t":"겨울","mis":"SO4-1-u1-X29"},{"t":"봄","mis":"SO4-1-u1-X29"},{"t":"가을","mis":"SO4-1-u1-X29"}],"explanation":["장마가 있어요.","소나기도 와요.","여름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_basic#10','soc',4,1,'u1','L10','g4_1_soc_u1_L10_basic','lesson_basic','SO4-1-u1-C10',3,'mc','auto','우리 지역의 기온과 강수량을 알면 무엇에 도움이 되나요?',ARRAY['SO4-1-u1-X27','SO4-1-u1-X29']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"mc","stem":"우리 지역의 기온과 강수량을 알면 무엇에 도움이 되나요?","options":[{"t":"계절에 맞는 옷차림·농사·생활을 미리 준비할 수 있어요","correct":true},{"t":"날씨를 마음대로 바꿀 수 있어요","mis":"SO4-1-u1-X27"},{"t":"모든 지역의 날씨가 같아져요","mis":"SO4-1-u1-X29"},{"t":"기온과 강수량은 쓸모가 없어요","mis":"SO4-1-u1-X27"}],"explanation":["날씨를 알아요.","미리 준비해요.","생활에 도움이 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#1','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',2,'ox','auto','해솔군은 1월에 기온이 가장 낮고 비도 가장 적게 내려요.',ARRAY['SO4-1-u1-X29']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"ox","stem":"해솔군은 1월에 기온이 가장 낮고 비도 가장 적게 내려요.","answer":"O","reason_options":[{"t":"1월의 꺾은선이 가장 낮고 1월의 막대가 가장 짧기 때문에","correct":true},{"t":"1월에 비가 가장 많이 내리기 때문에","mis":"SO4-1-u1-X29"}],"mis":"SO4-1-u1-X29","explanation":["1월 꺾은선을 봐요.","1월 막대도 봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["기온 — 빨간 꺾은선, 왼쪽 눈금(°C)","강수량 — 파란 막대, 오른쪽 눈금(mm)","꺾은선은 7월에 가장 높고 1월에 가장 낮다.","막대는 7월에 가장 길고 1월에 가장 짧다."],"title":"해솔군 기후 그래프 읽는 법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#2','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',2,'mc','auto','해솔군 기온 그래프에서 7월 기온은 1월보다 몇 °C 더 높나요?',ARRAY['SO4-1-u1-X26']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"mc","stem":"해솔군 기온 그래프에서 7월 기온은 1월보다 몇 °C 더 높나요?","options":[{"t":"24 °C","correct":true},{"t":"26 °C","mis":"SO4-1-u1-X26"},{"t":"2 °C","mis":"SO4-1-u1-X26"},{"t":"28 °C","mis":"SO4-1-u1-X26"}],"explanation":["7월 26 °C 예요.","1월 2 °C 예요.","24 °C 더 높아요."],"asset":{"type":"lgraph","xs":["1월","4월","7월","10월"],"series":[{"vals":[2,14,26,16]}],"step":2,"ymax":30,"mode":"line","title":"해솔군 기온","ylab":"°C"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#3','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',3,'mc','auto','해솔군 강수량 그래프에서 7월 강수량은 4월의 몇 배인가요?',ARRAY['SO4-1-u1-X26']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"mc","stem":"해솔군 강수량 그래프에서 7월 강수량은 4월의 몇 배인가요?","options":[{"t":"3배","correct":true},{"t":"2배","mis":"SO4-1-u1-X26"},{"t":"4배","mis":"SO4-1-u1-X26"},{"t":"6배","mis":"SO4-1-u1-X26"}],"explanation":["7월 300 mm 예요.","4월 100 mm 예요.","3배예요."],"asset":{"type":"lgraph","xs":["1월","4월","7월","10월"],"series":[{"vals":[50,100,300,50]}],"step":50,"ymax":350,"mode":"bar","title":"해솔군 강수량","ylab":"mm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#4','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',3,'error','auto','해솔군 기후 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X28','SO4-1-u1-X27']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"error","stem":"해솔군 기후 그래프를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「빨간 꺾은선이 길수록 비가 많이 왔어.」","correct":true,"mis_target":"SO4-1-u1-X28"},{"t":"친구 나 — 「파란 막대가 길수록 비가 많이 왔어.」","mis":"SO4-1-u1-X28"},{"t":"친구 다 — 「빨간 꺾은선이 높을수록 따뜻해.」","mis":"SO4-1-u1-X27"}],"explanation":["꺾은선은 기온이에요.","비는 막대예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["기온 — 빨간 꺾은선, 왼쪽 눈금(°C)","강수량 — 파란 막대, 오른쪽 눈금(mm)","꺾은선은 7월에 가장 높고 1월에 가장 낮다.","막대는 7월에 가장 길고 1월에 가장 짧다."],"title":"해솔군 기후 그래프 읽는 법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#5','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',3,'mc','auto','해솔군에서 우산과 장화를 가장 많이 챙겨야 할 달은 언제인가요?',ARRAY['SO4-1-u1-X29','SO4-1-u1-X26']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"mc","stem":"해솔군에서 우산과 장화를 가장 많이 챙겨야 할 달은 언제인가요?","options":[{"t":"7월","correct":true},{"t":"1월","mis":"SO4-1-u1-X29"},{"t":"10월","mis":"SO4-1-u1-X26"},{"t":"4월","mis":"SO4-1-u1-X26"}],"explanation":["비가 많은 달이에요.","막대가 가장 길어요.","7월이에요."],"asset":{"type":"lgraph","xs":["1월","4월","7월","10월"],"series":[{"vals":[50,100,300,50]}],"step":50,"ymax":350,"mode":"bar","title":"해솔군 강수량","ylab":"mm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#6','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',3,'ox','auto','우리나라는 겨울에 춥고 비나 눈이 적게 내려 건조해요.',ARRAY['SO4-1-u1-X29']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"ox","stem":"우리나라는 겨울에 춥고 비나 눈이 적게 내려 건조해요.","answer":"O","reason_options":[{"t":"겨울에는 기온이 낮고 강수량이 적기 때문에","correct":true},{"t":"겨울에 강수량이 가장 많기 때문에","mis":"SO4-1-u1-X29"}],"mis":"SO4-1-u1-X29","explanation":["겨울을 떠올려요.","춥고 건조해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#7','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',3,'match','auto','낱말과 그 단위를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"match","stem":"낱말과 그 단위를 알맞게 이으세요.","pairs":[{"l":"기온","r":"°C"},{"l":"강수량","r":"mm"},{"l":"면적","r":"km²"}],"mis":"SO4-1-u1-X27","explanation":["따뜻한 정도예요.","내린 양이에요.","넓이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#8','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',4,'essay','teacher','해솔군 기온과 강수량 그래프를 보고 해솔군 여름과 겨울의 날씨 특징을 한 가지씩 쓰고, 그에 맞는 생활 준비를 하나 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C10","difficulty":4,"kind":"essay","stem":"해솔군 기온과 강수량 그래프를 보고 해솔군 여름과 겨울의 날씨 특징을 한 가지씩 쓰고, 그에 맞는 생활 준비를 하나 쓰세요.","answer_guide":{"answer":"예: 여름(7월)은 기온이 26 °C 로 덥고 비가 300 mm 로 가장 많이 와요. 겨울(1월)은 기온이 2 °C 로 춥고 비가 적어요. 여름에는 비에 대비해 우산과 배수로를 미리 살펴요.","scoring_points":["여름 특징을 그래프로 썼는가","겨울 특징을 그래프로 썼는가","알맞은 생활 준비를 썼는가"]},"explanation":["7월을 봐요.","1월을 봐요.","준비를 써요."],"asset":{"type":"passage","lines":["1월 — 기온 2 °C · 강수량 50 mm","4월 — 기온 14 °C · 강수량 100 mm","7월 — 기온 26 °C · 강수량 300 mm","10월 — 기온 16 °C · 강수량 50 mm"],"title":"해솔군 기온과 강수량(그래프를 표로 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#9','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',4,'mc','auto','해솔군 농부가 들에 물을 가장 많이 대 주어야 할 것 같은 달은 언제인가요?',ARRAY['SO4-1-u1-X29','SO4-1-u1-X26','SO4-1-u1-X27']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C10","difficulty":4,"kind":"mc","stem":"해솔군 농부가 들에 물을 가장 많이 대 주어야 할 것 같은 달은 언제인가요?","options":[{"t":"1월","correct":true},{"t":"7월","mis":"SO4-1-u1-X29"},{"t":"4월","mis":"SO4-1-u1-X26"},{"t":"물은 필요 없어요","mis":"SO4-1-u1-X27"}],"explanation":["비가 적은 달이에요.","막대가 가장 짧아요.","1월이에요."],"asset":{"type":"lgraph","xs":["1월","4월","7월","10월"],"series":[{"vals":[50,100,300,50]}],"step":50,"ymax":350,"mode":"bar","title":"해솔군 강수량","ylab":"mm"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L10_challenge#10','soc',4,1,'u1','L10','g4_1_soc_u1_L10_challenge','lesson_challenge','SO4-1-u1-C10',4,'essay','teacher','기후 그래프 하나에 기온과 강수량을 함께 나타내면 좋은 점을 쓰고, 두 가지를 어떻게 구별해 읽는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C10","difficulty":4,"kind":"essay","stem":"기후 그래프 하나에 기온과 강수량을 함께 나타내면 좋은 점을 쓰고, 두 가지를 어떻게 구별해 읽는지 쓰세요.","answer_guide":{"answer":"예: 한 그래프에서 달마다 기온과 강수량을 함께 견줄 수 있어 그 지역 날씨의 특징을 한눈에 알 수 있어요. 기온은 꺾은선, 강수량은 막대로 나타내서 선의 높이로 기온을, 막대의 길이로 비의 양을 읽어요.","scoring_points":["한눈에 함께 견줄 수 있다고 썼는가","기온은 꺾은선이라고 썼는가","강수량은 막대라고 썼는가"]},"explanation":["좋은 점을 써요.","꺾은선이에요.","막대예요."],"asset":{"type":"passage","lines":["기온 — 빨간 꺾은선, 왼쪽 눈금(°C)","강수량 — 파란 막대, 오른쪽 눈금(mm)","꺾은선은 7월에 가장 높고 1월에 가장 낮다.","막대는 7월에 가장 길고 1월에 가장 짧다."],"title":"해솔군 기후 그래프 읽는 법"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#1','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',1,'mc','auto','위치·지형·면적·인구·기후처럼 어떤 지역에 관한 여러 정보를 무엇이라고 하나요?',ARRAY['SO4-1-u1-X30']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C11","difficulty":1,"kind":"mc","stem":"위치·지형·면적·인구·기후처럼 어떤 지역에 관한 여러 정보를 무엇이라고 하나요?","options":[{"t":"지리 정보","correct":true},{"t":"날씨 정보","mis":"SO4-1-u1-X30"},{"t":"교통 정보","mis":"SO4-1-u1-X30"},{"t":"가격 정보","mis":"SO4-1-u1-X30"}],"explanation":["지역에 관한 정보예요.","다섯 가지가 있어요.","지리 정보예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#2','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',1,'ox','auto','두 지역을 비교할 때는 같은 항목끼리 견주어야 해요.',ARRAY['SO4-1-u1-X31']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C11","difficulty":1,"kind":"ox","stem":"두 지역을 비교할 때는 같은 항목끼리 견주어야 해요.","answer":"O","reason_options":[{"t":"위치는 위치끼리, 인구는 인구끼리 견주어야 바르게 비교되기 때문에","correct":true},{"t":"서로 다른 항목을 섞어 견주어도 되기 때문에","mis":"SO4-1-u1-X31"}],"mis":"SO4-1-u1-X31","explanation":["항목을 맞춰요.","같은 것끼리예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#3','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',1,'sa','auto','비교표에서 바람시의 인구는 몇 만 명인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C11","difficulty":1,"kind":"sa","stem":"비교표에서 바람시의 인구는 몇 만 명인가요? 숫자만 쓰세요.","answer":["40"],"explanation":["인구 줄을 봐요.","바람시 칸이에요.","40만 명이에요."],"asset":{"type":"passage","lines":["항목 — 해솔군 — 바람시","위치 — ○○도의 남쪽 — ○○도의 북쪽","지형 — 바다·들·섬 — 높은 산·좁은 골짜기","면적 — 600 km² — 150 km²","인구 — 5만 명 — 40만 명","기후 — 겨울에 덜 추움 — 겨울에 더 추움"],"title":"두 지역 지리 정보 비교표"},"mis":"SO4-1-u1-X31"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#4','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',1,'mc','auto','비교표에서 해솔군의 지형은 무엇인가요?',ARRAY['SO4-1-u1-X23','SO4-1-u1-X31']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C11","difficulty":1,"kind":"mc","stem":"비교표에서 해솔군의 지형은 무엇인가요?","options":[{"t":"바다·들·섬","correct":true},{"t":"높은 산·좁은 골짜기","mis":"SO4-1-u1-X23"},{"t":"600 km²","mis":"SO4-1-u1-X31"},{"t":"겨울에 덜 추움","mis":"SO4-1-u1-X31"}],"explanation":["지형 줄을 봐요.","해솔군 칸이에요.","바다·들·섬이에요."],"asset":{"type":"passage","lines":["항목 — 해솔군 — 바람시","위치 — ○○도의 남쪽 — ○○도의 북쪽","지형 — 바다·들·섬 — 높은 산·좁은 골짜기","면적 — 600 km² — 150 km²","인구 — 5만 명 — 40만 명","기후 — 겨울에 덜 추움 — 겨울에 더 추움"],"title":"두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#5','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',2,'mc','auto','지리 정보를 조사하는 방법으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-1-u1-X30']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C11","difficulty":2,"kind":"mc","stem":"지리 정보를 조사하는 방법으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"친구 얼굴을 살펴보기","correct":true},{"t":"디지털 영상 지도로 위치·지형 살펴보기","mis":"SO4-1-u1-X30"},{"t":"통계 자료로 인구·면적 찾기","mis":"SO4-1-u1-X30"},{"t":"기상 자료로 기온·강수량 찾기","mis":"SO4-1-u1-X30"}],"explanation":["지리 정보를 조사해요.","친구 얼굴은 아니에요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#6','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',2,'mc','auto','조사 계획의 ㉯로 알 수 있는 지리 정보는 무엇인가요?',ARRAY['SO4-1-u1-X30']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C11","difficulty":2,"kind":"mc","stem":"조사 계획의 ㉯로 알 수 있는 지리 정보는 무엇인가요?","options":[{"t":"인구","correct":true},{"t":"지형","mis":"SO4-1-u1-X30"},{"t":"기온","mis":"SO4-1-u1-X30"},{"t":"위치","mis":"SO4-1-u1-X30"}],"explanation":["통계 자료예요.","사람의 수예요.","인구예요."],"asset":{"type":"passage","lines":["㉮ 디지털 영상 지도로 산·강·바다를 살펴본다.","㉯ 통계 자료에서 사는 사람의 수를 찾는다.","㉰ 기상 자료에서 달마다의 기온과 비의 양을 찾는다."],"title":"지리 정보 조사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#7','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',2,'ox','auto','지리 정보는 한번 정해지면 시간이 지나도 절대 바뀌지 않아요.',ARRAY['SO4-1-u1-X31']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C11","difficulty":2,"kind":"ox","stem":"지리 정보는 한번 정해지면 시간이 지나도 절대 바뀌지 않아요.","answer":"X","reason_options":[{"t":"다리가 놓이거나 이름이 바뀌면 지리 정보도 변할 수 있기 때문에","correct":true},{"t":"지리 정보는 언제나 그대로이기 때문에","mis":"SO4-1-u1-X31"}],"mis":"SO4-1-u1-X31","explanation":["안내판이 바뀌었어요.","정보가 변했어요.","그래서 X예요."],"asset":{"type":"passage","lines":["섬마을의 다리가 새로 놓이고 동네 이름이 바뀌었다.","그래서 마을 안내판의 주소와 길 안내가 새로 고쳐졌다."],"title":"바뀐 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
