INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#9','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',2,'mc','auto','영상 지도·통계·기상 자료를 모아 지리 정보를 조사하고 지도·자료로 만드는 사람은 누구인가요?',ARRAY['SO4-1-u1-X30']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C11","difficulty":2,"kind":"mc","stem":"영상 지도·통계·기상 자료를 모아 지리 정보를 조사하고 지도·자료로 만드는 사람은 누구인가요?","options":[{"t":"지리 정보 전문가","correct":true},{"t":"요리사","mis":"SO4-1-u1-X30"},{"t":"운동선수","mis":"SO4-1-u1-X30"},{"t":"성악가","mis":"SO4-1-u1-X30"}],"explanation":["지리 정보를 모아요.","자료로 만들어요.","지리 정보 전문가예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_basic#10','soc',4,1,'u1','L11','g4_1_soc_u1_L11_basic','lesson_basic','SO4-1-u1-C11',3,'mc','auto','우리 지역과 다른 지역의 지리 정보를 비교하면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u1-X31']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"mc","stem":"우리 지역과 다른 지역의 지리 정보를 비교하면 좋은 점은 무엇인가요?","options":[{"t":"각 지역의 특징과 다른 점을 잘 알 수 있어요","correct":true},{"t":"모든 지역이 같아져요","mis":"SO4-1-u1-X31"},{"t":"한 지역만 좋아져요","mis":"SO4-1-u1-X31"},{"t":"비교는 아무 도움이 안 돼요","mis":"SO4-1-u1-X31"}],"explanation":["견주어 봐요.","다른 점이 보여요.","특징을 알아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#1','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',2,'ox','auto','「해솔군의 면적은 바람시의 인구보다 커요.」는 바른 비교예요.',ARRAY['SO4-1-u1-X31']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C11","difficulty":2,"kind":"ox","stem":"「해솔군의 면적은 바람시의 인구보다 커요.」는 바른 비교예요.","answer":"X","reason_options":[{"t":"면적과 인구는 서로 다른 항목이라 견줄 수 없기 때문에","correct":true},{"t":"수가 있으면 어떤 항목끼리든 견줄 수 있기 때문에","mis":"SO4-1-u1-X31"}],"mis":"SO4-1-u1-X31","explanation":["면적과 인구예요.","다른 항목이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["항목 — 해솔군 — 바람시","위치 — ○○도의 남쪽 — ○○도의 북쪽","지형 — 바다·들·섬 — 높은 산·좁은 골짜기","면적 — 600 km² — 150 km²","인구 — 5만 명 — 40만 명","기후 — 겨울에 덜 추움 — 겨울에 더 추움"],"title":"두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#2','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',2,'mc','auto','조사 계획 ㉮·㉯·㉰로 알 수 있는 지리 정보를 차례대로 바르게 쓴 것은 무엇인가요?',ARRAY['SO4-1-u1-X30']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C11","difficulty":2,"kind":"mc","stem":"조사 계획 ㉮·㉯·㉰로 알 수 있는 지리 정보를 차례대로 바르게 쓴 것은 무엇인가요?","options":[{"t":"지형 — 인구 — 기후","correct":true},{"t":"인구 — 지형 — 기후","mis":"SO4-1-u1-X30"},{"t":"기후 — 인구 — 지형","mis":"SO4-1-u1-X30"},{"t":"지형 — 기후 — 인구","mis":"SO4-1-u1-X30"}],"explanation":["영상 지도는 지형이에요.","통계는 인구예요.","기상 자료는 기후예요."],"asset":{"type":"passage","lines":["㉮ 디지털 영상 지도로 산·강·바다를 살펴본다.","㉯ 통계 자료에서 사는 사람의 수를 찾는다.","㉰ 기상 자료에서 달마다의 기온과 비의 양을 찾는다."],"title":"지리 정보 조사 계획"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#3','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',3,'mc','auto','비교표를 보고 두 지역의 특징을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u1-X25','SO4-1-u1-X31']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"mc","stem":"비교표를 보고 두 지역의 특징을 바르게 말한 것은 무엇인가요?","options":[{"t":"해솔군은 넓고 사람이 적고, 바람시는 좁고 사람이 많아요","correct":true},{"t":"해솔군은 좁고 사람이 많아요","mis":"SO4-1-u1-X25"},{"t":"두 지역의 면적과 인구가 같아요","mis":"SO4-1-u1-X31"},{"t":"바람시는 넓고 사람이 적어요","mis":"SO4-1-u1-X25"}],"explanation":["면적을 견줘요.","인구를 견줘요.","함께 말해요."],"asset":{"type":"passage","lines":["항목 — 해솔군 — 바람시","위치 — ○○도의 남쪽 — ○○도의 북쪽","지형 — 바다·들·섬 — 높은 산·좁은 골짜기","면적 — 600 km² — 150 km²","인구 — 5만 명 — 40만 명","기후 — 겨울에 덜 추움 — 겨울에 더 추움"],"title":"두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#4','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',3,'error','auto','비교표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X23','SO4-1-u1-X22','SO4-1-u1-X31']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"error","stem":"비교표를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「바람시는 바다와 들이 있는 지역이야.」","correct":true,"mis_target":"SO4-1-u1-X23"},{"t":"친구 가 — 「해솔군은 ○○도의 남쪽에 있어.」","mis":"SO4-1-u1-X22"},{"t":"친구 다 — 「바람시는 겨울에 더 추워.」","mis":"SO4-1-u1-X31"}],"explanation":["바람시 지형을 봐요.","높은 산과 골짜기예요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["항목 — 해솔군 — 바람시","위치 — ○○도의 남쪽 — ○○도의 북쪽","지형 — 바다·들·섬 — 높은 산·좁은 골짜기","면적 — 600 km² — 150 km²","인구 — 5만 명 — 40만 명","기후 — 겨울에 덜 추움 — 겨울에 더 추움"],"title":"두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#5','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',3,'mc','auto','바뀐 안내판 이야기로 알 수 있는 것은 무엇인가요?',ARRAY['SO4-1-u1-X31','SO4-1-u1-X30']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"mc","stem":"바뀐 안내판 이야기로 알 수 있는 것은 무엇인가요?","options":[{"t":"지리 정보는 시간이 지나며 변할 수 있어요","correct":true},{"t":"지리 정보는 절대 변하지 않아요","mis":"SO4-1-u1-X31"},{"t":"안내판은 아무 때나 바꿔요","mis":"SO4-1-u1-X31"},{"t":"섬마을에는 지리 정보가 없어요","mis":"SO4-1-u1-X30"}],"explanation":["다리가 놓였어요.","이름이 바뀌었어요.","정보가 변했어요."],"asset":{"type":"passage","lines":["섬마을의 다리가 새로 놓이고 동네 이름이 바뀌었다.","그래서 마을 안내판의 주소와 길 안내가 새로 고쳐졌다."],"title":"바뀐 안내판"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#6','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',3,'ox','auto','해솔군과 바람시의 기후를 견주려면 두 지역의 기온과 강수량 자료를 함께 살펴야 해요.',ARRAY['SO4-1-u1-X31']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"ox","stem":"해솔군과 바람시의 기후를 견주려면 두 지역의 기온과 강수량 자료를 함께 살펴야 해요.","answer":"O","reason_options":[{"t":"기후는 기온과 강수량으로 알 수 있고 같은 항목끼리 견주어야 하기 때문에","correct":true},{"t":"기후는 인구 자료만 보면 알 수 있기 때문에","mis":"SO4-1-u1-X31"}],"mis":"SO4-1-u1-X31","explanation":["기후예요.","기온과 강수량이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#7','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',3,'match','auto','조사할 지리 정보와 알맞은 조사 방법을 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"match","stem":"조사할 지리 정보와 알맞은 조사 방법을 이으세요.","pairs":[{"l":"위치·지형","r":"디지털 영상 지도"},{"l":"인구·면적","r":"통계 자료"},{"l":"기온·강수량","r":"기상 자료"}],"mis":"SO4-1-u1-X30","explanation":["지형은 지도예요.","인구는 통계예요.","날씨는 기상 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#8','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',4,'essay','teacher','비교표에서 두 항목을 골라 해솔군과 바람시를 견주고, 비교로 알게 된 각 지역의 특징을 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C11","difficulty":4,"kind":"essay","stem":"비교표에서 두 항목을 골라 해솔군과 바람시를 견주고, 비교로 알게 된 각 지역의 특징을 쓰세요.","answer_guide":{"answer":"예: 지형을 견주면 해솔군은 바다·들·섬이 있고 바람시는 높은 산과 좁은 골짜기가 있어요. 인구를 견주면 해솔군은 5만 명, 바람시는 40만 명이에요. 해솔군은 바다와 들이 넓은 한적한 지역이고, 바람시는 좁은 땅에 사람이 많이 사는 지역이에요.","scoring_points":["같은 항목끼리 두 가지를 견주었는가","표의 내용을 바르게 썼는가","각 지역의 특징을 정리했는가"]},"explanation":["항목을 골라요.","같은 것끼리 견줘요.","특징을 써요."],"asset":{"type":"passage","lines":["항목 — 해솔군 — 바람시","위치 — ○○도의 남쪽 — ○○도의 북쪽","지형 — 바다·들·섬 — 높은 산·좁은 골짜기","면적 — 600 km² — 150 km²","인구 — 5만 명 — 40만 명","기후 — 겨울에 덜 추움 — 겨울에 더 추움"],"title":"두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#9','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',4,'mc','auto','바람시에 사는 친구가 해솔군으로 이사 가요. 비교표를 보고 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X23','SO4-1-u1-X25','SO4-1-u1-X31']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C11","difficulty":4,"kind":"mc","stem":"바람시에 사는 친구가 해솔군으로 이사 가요. 비교표를 보고 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"해솔군은 바다와 들이 있고 겨울이 바람시보다 덜 추울 거야","correct":true},{"t":"해솔군도 높은 산과 좁은 골짜기뿐이야","mis":"SO4-1-u1-X23"},{"t":"해솔군은 사람이 바람시보다 훨씬 많아","mis":"SO4-1-u1-X25"},{"t":"해솔군과 바람시는 모든 것이 같아","mis":"SO4-1-u1-X31"}],"explanation":["지형을 봐요.","기후를 봐요.","알맞은 말을 골라요."],"asset":{"type":"passage","lines":["항목 — 해솔군 — 바람시","위치 — ○○도의 남쪽 — ○○도의 북쪽","지형 — 바다·들·섬 — 높은 산·좁은 골짜기","면적 — 600 km² — 150 km²","인구 — 5만 명 — 40만 명","기후 — 겨울에 덜 추움 — 겨울에 더 추움"],"title":"두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L11_challenge#10','soc',4,1,'u1','L11','g4_1_soc_u1_L11_challenge','lesson_challenge','SO4-1-u1-C11',4,'essay','teacher','우리 지역의 지리 정보 다섯 가지를 조사하려고 해요. 각 정보를 어떤 방법으로 조사할지 계획을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C11","difficulty":4,"kind":"essay","stem":"우리 지역의 지리 정보 다섯 가지를 조사하려고 해요. 각 정보를 어떤 방법으로 조사할지 계획을 쓰세요.","answer_guide":{"answer":"예: 위치와 지형은 디지털 영상 지도로 살펴볼 거예요. 면적과 인구는 통계 자료에서 찾고, 기후는 기상 자료에서 달마다의 기온과 강수량을 찾을 거예요.","scoring_points":["다섯 가지 지리 정보를 썼는가","위치·지형 조사 방법을 썼는가","면적·인구·기후 조사 방법을 썼는가"]},"explanation":["다섯 가지예요.","방법을 짝지어요.","계획을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_basic#1','soc',4,1,'u1','L12','g4_1_soc_u1_L12_basic','lesson_basic','SO4-1-u1-C12',1,'mc','auto','작은 사각형(픽셀)을 여러 개 모아 그림이나 지도를 나타내는 것을 무엇이라고 하나요?',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C12","difficulty":1,"kind":"mc","stem":"작은 사각형(픽셀)을 여러 개 모아 그림이나 지도를 나타내는 것을 무엇이라고 하나요?","options":[{"t":"픽셀 아트","correct":true},{"t":"범례","mis":"SO4-1-u1-X32"},{"t":"등고선","mis":"SO4-1-u1-X32"},{"t":"약도","mis":"SO4-1-u1-X32"}],"explanation":["작은 사각형이에요.","모아서 그려요.","픽셀 아트예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_basic#2','soc',4,1,'u1','L12','g4_1_soc_u1_L12_basic','lesson_basic','SO4-1-u1-C12',1,'ox','auto','픽셀 지도에서 칸을 색칠할 때는 범례에 맞추어 색을 정해요.',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C12","difficulty":1,"kind":"ox","stem":"픽셀 지도에서 칸을 색칠할 때는 범례에 맞추어 색을 정해요.","answer":"O","reason_options":[{"t":"범례에서 지역마다 정한 색으로 칠해야 누구나 읽을 수 있기 때문에","correct":true},{"t":"내 마음대로 색을 골라 칠하기 때문에","mis":"SO4-1-u1-X32"}],"mis":"SO4-1-u1-X32","explanation":["범례가 있어요.","정한 색이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_basic#3','soc',4,1,'u1','L12','g4_1_soc_u1_L12_basic','lesson_basic','SO4-1-u1-C12',1,'sa','auto','픽셀 지도에서 숫자 2로 칠한 지역은 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C12","difficulty":1,"kind":"sa","stem":"픽셀 지도에서 숫자 2로 칠한 지역은 어디인가요? 세 글자로 쓰세요.","answer":["바람시"],"explanation":["범례를 봐요.","2는 노랑이에요.","바람시예요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"},"mis":"SO4-1-u1-X32"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
