INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_basic#9','soc',4,1,'u1','L12','g4_1_soc_u1_L12_basic','lesson_basic','SO4-1-u1-C12',2,'mc','auto','픽셀 지도에서 면적이 가장 좁은 지역은 어디인가요?',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C12","difficulty":2,"kind":"mc","stem":"픽셀 지도에서 면적이 가장 좁은 지역은 어디인가요?","options":[{"t":"별빛군(5)","correct":true},{"t":"달빛군(4)","mis":"SO4-1-u1-X32"},{"t":"푸른군(3)","mis":"SO4-1-u1-X32"},{"t":"해솔군(1)","mis":"SO4-1-u1-X32"}],"explanation":["칸을 세어요.","5는 한 칸이에요.","별빛군이에요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
