INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#3','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',3,'mc','auto','픽셀 지도에서 푸른군(3)과 달빛군(4)을 견주면 어떠한가요?',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"mc","stem":"픽셀 지도에서 푸른군(3)과 달빛군(4)을 견주면 어떠한가요?","options":[{"t":"푸른군이 달빛군보다 2칸 더 넓어요","correct":true},{"t":"달빛군이 푸른군보다 2칸 더 넓어요","mis":"SO4-1-u1-X32"},{"t":"두 지역의 면적이 같아요","mis":"SO4-1-u1-X32"},{"t":"면적은 알 수 없어요","mis":"SO4-1-u1-X32"}],"explanation":["3은 4칸이에요.","4는 2칸이에요.","푸른군이 2칸 넓어요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#4','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',3,'error','auto','픽셀 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"error","stem":"픽셀 지도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「보라색이 예뻐서 별빛군을 다 보라로 칠하면 돼.」","correct":true,"mis_target":"SO4-1-u1-X32"},{"t":"친구 가 — 「별빛군은 범례대로 보라로 칠해.」","mis":"SO4-1-u1-X32"},{"t":"친구 나 — 「바람시는 동쪽에 길게 있어.」","mis":"SO4-1-u1-X32"}],"explanation":["색은 범례로 정해요.","예뻐서가 아니에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#5','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',3,'mc','auto','픽셀 지도에서 바람시(2)는 몇 칸이고, 지도의 어느 쪽에 길게 있나요?',ARRAY['SO4-1-u1-X32','SO4-1-u1-X06']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"mc","stem":"픽셀 지도에서 바람시(2)는 몇 칸이고, 지도의 어느 쪽에 길게 있나요?","options":[{"t":"7칸 — 동쪽","correct":true},{"t":"6칸 — 동쪽","mis":"SO4-1-u1-X32"},{"t":"7칸 — 서쪽","mis":"SO4-1-u1-X06"},{"t":"4칸 — 남쪽","mis":"SO4-1-u1-X32"}],"explanation":["2를 세어요.","오른쪽 두 줄이에요.","7칸, 동쪽이에요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#6','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',3,'ox','auto','완성한 픽셀 지도를 친구들과 함께 보며 지역을 비교하면 서로 이야기하고 협력하는 힘을 기를 수 있어요.',ARRAY['SO4-1-u1-X30']::text[],false,'{"seq":6,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"ox","stem":"완성한 픽셀 지도를 친구들과 함께 보며 지역을 비교하면 서로 이야기하고 협력하는 힘을 기를 수 있어요.","answer":"O","reason_options":[{"t":"지역의 위치와 면적을 함께 견주며 생각을 나누기 때문에","correct":true},{"t":"픽셀 아트는 혼자서만 하는 활동이기 때문에","mis":"SO4-1-u1-X30"}],"mis":"SO4-1-u1-X30","explanation":["함께 봐요.","이야기를 나눠요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#7','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',3,'match','auto','픽셀 지도에서 보는 것과 알 수 있는 정보를 알맞게 이으세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"match","stem":"픽셀 지도에서 보는 것과 알 수 있는 정보를 알맞게 이으세요.","pairs":[{"l":"칸 수","r":"면적"},{"l":"색칠된 자리","r":"위치"},{"l":"범례의 숫자와 색","r":"어느 지역인지"}],"mis":"SO4-1-u1-X32","explanation":["칸을 세면 면적이에요.","자리는 위치예요.","범례는 지역이에요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#8','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',4,'essay','teacher','픽셀 지도에서 두 지역을 골라 위치와 면적을 견주어 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C12","difficulty":4,"kind":"essay","stem":"픽셀 지도에서 두 지역을 골라 위치와 면적을 견주어 쓰세요.","answer_guide":{"answer":"예: 해솔군(1)은 북서쪽에 있고 6칸이에요. 별빛군(5)은 남동쪽에 있고 1칸이에요. 해솔군이 별빛군보다 5칸 많아서 면적이 더 넓어요.","scoring_points":["두 지역의 위치를 방위로 썼는가","두 지역의 칸 수를 바르게 셌는가","칸 수로 면적을 견주었는가"]},"explanation":["위치를 봐요.","칸을 세어요.","견주어 써요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#9','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',4,'mc','auto','픽셀 지도의 지역을 넓은 차례대로 바르게 늘어놓은 것은 무엇인가요?',ARRAY['SO4-1-u1-X32','SO4-1-u1-X26']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C12","difficulty":4,"kind":"mc","stem":"픽셀 지도의 지역을 넓은 차례대로 바르게 늘어놓은 것은 무엇인가요?","options":[{"t":"바람시 — 해솔군 — 푸른군 — 달빛군 — 별빛군","correct":true},{"t":"해솔군 — 바람시 — 푸른군 — 달빛군 — 별빛군","mis":"SO4-1-u1-X32"},{"t":"바람시 — 해솔군 — 달빛군 — 푸른군 — 별빛군","mis":"SO4-1-u1-X32"},{"t":"별빛군 — 달빛군 — 푸른군 — 해솔군 — 바람시","mis":"SO4-1-u1-X26"}],"explanation":["7·6·4·2·1칸이에요.","많은 칸부터예요.","넓은 차례예요."],"asset":{"type":"passage","lines":["1 1 1 2 2","1 1 1 2 2","3 3 4 2 2","3 3 4 2 5","범례 — 1 해솔군 초록 · 2 바람시 노랑 · 3 푸른군 파랑","범례 — 4 달빛군 분홍 · 5 별빛군 보라","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"픽셀 지도(예시 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_L12_challenge#10','soc',4,1,'u1','L12','g4_1_soc_u1_L12_challenge','lesson_challenge','SO4-1-u1-C12',4,'essay','teacher','우리 반이 우리 고장 픽셀 지도를 만든다면 어떤 차례로 만들지 쓰고, 완성한 지도로 무엇을 비교할 수 있는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C12","difficulty":4,"kind":"essay","stem":"우리 반이 우리 고장 픽셀 지도를 만든다면 어떤 차례로 만들지 쓰고, 완성한 지도로 무엇을 비교할 수 있는지 쓰세요.","answer_guide":{"answer":"예: 먼저 범례에서 지역마다 숫자와 색을 정해요. 다음에 범례에 맞추어 칸을 색칠해 지도를 완성해요. 완성한 지도에서 색칠한 자리로 지역의 위치를, 칸 수로 면적을 비교할 수 있어요.","scoring_points":["범례를 먼저 정한다고 썼는가","범례에 맞추어 색칠한다고 썼는가","위치와 면적을 비교한다고 썼는가"]},"explanation":["범례가 먼저예요.","색칠해요.","비교해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#1','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C1',1,'mc','auto','땅의 모습을 일정하게 줄여 약속에 따라 나타낸 그림은 무엇인가요?',ARRAY['SO4-1-u1-X01']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C1","difficulty":1,"kind":"mc","stem":"땅의 모습을 일정하게 줄여 약속에 따라 나타낸 그림은 무엇인가요?","options":[{"t":"지도","correct":true},{"t":"사진","mis":"SO4-1-u1-X01"},{"t":"일기","mis":"SO4-1-u1-X01"},{"t":"동화책","mis":"SO4-1-u1-X01"}],"explanation":["줄여요.","약속대로예요.","지도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
