INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#9','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C2',2,'mc','auto','일지 ①에서 우체국은 학교의 어느 쪽에 있나요?',ARRAY['SO4-1-u1-X06','SO4-1-u1-X08']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C2","difficulty":2,"kind":"mc","stem":"일지 ①에서 우체국은 학교의 어느 쪽에 있나요?","options":[{"t":"남서쪽","correct":true},{"t":"북동쪽","mis":"SO4-1-u1-X06"},{"t":"남동쪽","mis":"SO4-1-u1-X08"},{"t":"북서쪽","mis":"SO4-1-u1-X08"}],"explanation":["왼쪽 아래예요.","남쪽과 서쪽 사이예요.","남서쪽이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#10','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C3',2,'ox','auto','기호와 범례를 쓰면 복잡한 땅의 모습을 간단하게 나타낼 수 있어요.',ARRAY['SO4-1-u1-X03']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"ox","stem":"기호와 범례를 쓰면 복잡한 땅의 모습을 간단하게 나타낼 수 있어요.","answer":"O","reason_options":[{"t":"약속된 기호로 장소를 줄여 나타내기 때문에","correct":true},{"t":"기호를 쓰면 지도가 더 복잡해지기 때문에","mis":"SO4-1-u1-X03"}],"mis":"SO4-1-u1-X03","explanation":["기호는 약속이에요.","간단해져요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#11','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C4',2,'mc','auto','일지 ②에서 더 높은 산과 그 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u1-X13','SO4-1-u1-X12']::text[],false,'{"seq":11,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"mc","stem":"일지 ②에서 더 높은 산과 그 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"산 ㉯ — 숫자가 더 크고 등고선이 더 여러 겹이라서","correct":true},{"t":"산 ㉮ — 등고선이 더 적어서","mis":"SO4-1-u1-X13"},{"t":"산 ㉮ — 이름이 앞이라서","mis":"SO4-1-u1-X12"},{"t":"알 수 없어요 — 사진이 없어서","mis":"SO4-1-u1-X12"}],"explanation":["숫자를 견줘요.","겹 수도 견줘요.","산 ㉯예요."],"asset":{"type":"passage","lines":["산 ㉮ — 등고선 4겹, 가장 안쪽 원에 쓰인 숫자 400","산 ㉯ — 등고선 6겹, 가장 안쪽 원에 쓰인 숫자 600","산 ㉯ 북쪽 비탈 — 등고선 간격이 넓다","산 ㉯ 남쪽 비탈 — 등고선 간격이 좁다"],"title":"일지 ② — 두 산의 등고선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#12','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C5',2,'mc','auto','일지 ③에서 학교부터 기차역까지의 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16','SO4-1-u1-X18']::text[],false,'{"seq":12,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"mc","stem":"일지 ③에서 학교부터 기차역까지의 실제 거리는 얼마인가요?","options":[{"t":"10 km","correct":true},{"t":"5 km","mis":"SO4-1-u1-X16"},{"t":"7 km","mis":"SO4-1-u1-X16"},{"t":"10 cm","mis":"SO4-1-u1-X18"}],"explanation":["1 cm 가 2 km 예요.","5 cm 예요.","10 km 예요."],"asset":{"type":"passage","lines":["축척 막대 — 1 cm = 2 km","학교 ~ 도서관: 지도에서 2 cm","학교 ~ 기차역: 지도에서 5 cm"],"title":"일지 ③ — 은빛마을 거리 재기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#13','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C6',2,'mc','auto','일지 ④의 ㉠처럼 할머니 댁에 처음 자동차로 갈 때 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X19']::text[],false,'{"seq":13,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"mc","stem":"일지 ④의 ㉠처럼 할머니 댁에 처음 자동차로 갈 때 알맞은 것은 무엇인가요?","options":[{"t":"길 도우미(내비게이션)","correct":true},{"t":"관광 안내도","mis":"SO4-1-u1-X19"},{"t":"버스 노선도","mis":"SO4-1-u1-X19"},{"t":"세계지도","mis":"SO4-1-u1-X19"}],"explanation":["처음 가요.","자동차예요.","길 도우미예요."],"asset":{"type":"passage","lines":["㉠ 할머니 댁에 처음 자동차로 간다.","㉡ 다른 고장의 볼거리를 찾는다.","㉢ 버스를 갈아타고 체육관에 간다.","㉣ 친구에게 우리 집 가는 길을 간단히 알려 준다."],"title":"일지 ④ — 지도가 필요한 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#14','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C8',2,'mc','auto','일지 ⑤에서 노을군의 위치를 알맞게 나타낸 말은 무엇인가요?',ARRAY['SO4-1-u1-X22']::text[],false,'{"seq":14,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"mc","stem":"일지 ⑤에서 노을군의 위치를 알맞게 나타낸 말은 무엇인가요?","options":[{"t":"○○도의 서쪽에 있고 동쪽으로 햇살시와 맞닿아 있어요","correct":true},{"t":"버섯을 기르고 벼농사를 지어요","mis":"SO4-1-u1-X22"},{"t":"높은 산과 넓은 들이 있어요","mis":"SO4-1-u1-X22"},{"t":"사람이 6만 명 살아요","mis":"SO4-1-u1-X22"}],"explanation":["방위가 있어요.","이웃 지역이 있어요.","그것이 위치예요."],"asset":{"type":"passage","lines":["노을군은 ○○도의 서쪽에 있고, 동쪽으로 햇살시와 맞닿아 있다.","노을군의 북쪽에는 높은 산이 있고, 남쪽에는 넓은 들이 있다.","강이 산에서 들을 지나 서쪽 바다로 흐른다.","산골 마을에서는 버섯을 기르고, 들에서는 벼농사를 짓는다."],"title":"일지 ⑤ — 노을군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#15','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C9',2,'mc','auto','일지 ⑥에서 면적은 가장 좁지만 인구는 가장 많은 지역은 어디인가요?',ARRAY['SO4-1-u1-X25']::text[],false,'{"seq":15,"concept":"SO4-1-u1-C9","difficulty":2,"kind":"mc","stem":"일지 ⑥에서 면적은 가장 좁지만 인구는 가장 많은 지역은 어디인가요?","options":[{"t":"햇살시","correct":true},{"t":"노을군","mis":"SO4-1-u1-X25"},{"t":"초록군","mis":"SO4-1-u1-X25"},{"t":"그런 곳은 없어요","mis":"SO4-1-u1-X25"}],"explanation":["면적은 햇살시가 좁아요.","인구는 햇살시가 많아요.","햇살시예요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","노을군 — 450 km² — 6만 명","햇살시 — 120 km² — 30만 명","초록군 — 250 km² — 9만 명"],"title":"일지 ⑥ — 세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#16','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C10',2,'mc','auto','일지 ⑦에서 7월 기온은 1월보다 몇 °C 높나요?',ARRAY['SO4-1-u1-X26','SO4-1-u1-X27']::text[],false,'{"seq":16,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"mc","stem":"일지 ⑦에서 7월 기온은 1월보다 몇 °C 높나요?","options":[{"t":"25 °C","correct":true},{"t":"0 °C","mis":"SO4-1-u1-X26"},{"t":"12 °C","mis":"SO4-1-u1-X26"},{"t":"280 °C","mis":"SO4-1-u1-X27"}],"explanation":["7월 25 °C 예요.","1월 0 °C 예요.","25 °C 높아요."],"asset":{"type":"passage","lines":["1월 — 기온 0 °C · 강수량 30 mm","4월 — 기온 12 °C · 강수량 90 mm","7월 — 기온 25 °C · 강수량 280 mm","10월 — 기온 15 °C · 강수량 50 mm"],"title":"일지 ⑦ — 노을군 기온과 강수량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#17','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C7',3,'mc','auto','일지 ①에서 학교 북쪽 산에 대해 알 수 있는 것을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u1-X06','SO4-1-u1-X13','SO4-1-u1-X11']::text[],false,'{"seq":17,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"mc","stem":"일지 ①에서 학교 북쪽 산에 대해 알 수 있는 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"학교의 북쪽에 있고 가장 높은 곳이 300이에요","correct":true},{"t":"학교의 남쪽에 있고 가장 높은 곳이 300이에요","mis":"SO4-1-u1-X06"},{"t":"학교의 북쪽에 있고 가장 낮은 곳이 300이에요","mis":"SO4-1-u1-X13"},{"t":"학교의 북쪽에 있고 실제로 300 km 떨어져 있어요","mis":"SO4-1-u1-X11"}],"explanation":["위쪽은 북쪽이에요.","안쪽 원이 가장 높아요.","두 가지를 함께 봐요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#18','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C4',3,'mc','auto','일지 ②에서 산 ㉯의 등고선 6겹 가운데 가장 바깥쪽 원은 어떤 곳인가요?',ARRAY['SO4-1-u1-X13','SO4-1-u1-X14','SO4-1-u1-X12']::text[],false,'{"seq":18,"concept":"SO4-1-u1-C4","difficulty":3,"kind":"mc","stem":"일지 ②에서 산 ㉯의 등고선 6겹 가운데 가장 바깥쪽 원은 어떤 곳인가요?","options":[{"t":"산 ㉯에서 가장 낮은 곳","correct":true},{"t":"산 ㉯에서 가장 높은 곳","mis":"SO4-1-u1-X13"},{"t":"경사가 가장 급한 곳","mis":"SO4-1-u1-X14"},{"t":"강이 흐르는 곳","mis":"SO4-1-u1-X12"}],"explanation":["바깥쪽이에요.","안쪽으로 갈수록 높아요.","가장 낮은 곳이에요."],"asset":{"type":"passage","lines":["산 ㉮ — 등고선 4겹, 가장 안쪽 원에 쓰인 숫자 400","산 ㉯ — 등고선 6겹, 가장 안쪽 원에 쓰인 숫자 600","산 ㉯ 북쪽 비탈 — 등고선 간격이 넓다","산 ㉯ 남쪽 비탈 — 등고선 간격이 좁다"],"title":"일지 ② — 두 산의 등고선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#19','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C6',3,'error','auto','일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X19','SO4-1-u1-X20']::text[],false,'{"seq":19,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"error","stem":"일지 ④를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「㉣에는 관광 안내도를 건네주면 돼.」","correct":true,"mis_target":"SO4-1-u1-X19"},{"t":"친구 가 — 「㉠에는 길 도우미가 좋아.」","mis":"SO4-1-u1-X19"},{"t":"친구 나 — 「㉡에는 관광 안내도가 좋아.」","mis":"SO4-1-u1-X20"}],"explanation":["㉣은 우리 집 가는 길이에요.","약도가 알맞아요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 할머니 댁에 처음 자동차로 간다.","㉡ 다른 고장의 볼거리를 찾는다.","㉢ 버스를 갈아타고 체육관에 간다.","㉣ 친구에게 우리 집 가는 길을 간단히 알려 준다."],"title":"일지 ④ — 지도가 필요한 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#20','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C11',3,'mc','auto','일지 ⑧에서 두 지역을 같은 항목끼리 바르게 견준 것은 무엇인가요?',ARRAY['SO4-1-u1-X31']::text[],false,'{"seq":20,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"mc","stem":"일지 ⑧에서 두 지역을 같은 항목끼리 바르게 견준 것은 무엇인가요?","options":[{"t":"인구는 햇살시가 노을군보다 많아요","correct":true},{"t":"노을군의 면적은 햇살시의 인구보다 커요","mis":"SO4-1-u1-X31"},{"t":"노을군의 지형은 햇살시의 기후보다 좋아요","mis":"SO4-1-u1-X31"},{"t":"햇살시의 위치는 노을군의 면적보다 넓어요","mis":"SO4-1-u1-X31"}],"explanation":["같은 항목끼리예요.","인구는 인구끼리예요.","바른 비교예요."],"asset":{"type":"passage","lines":["항목 — 노을군 — 햇살시","위치 — ○○도의 서쪽 — ○○도의 동쪽","지형 — 산·들·강 — 바다·섬","면적 — 450 km² — 120 km²","인구 — 6만 명 — 30만 명","기후 — 여름에 비가 많음 — 겨울에 덜 추움"],"title":"일지 ⑧ — 두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#21','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C9',3,'mc','auto','일지 ⑥에서 초록군은 노을군보다 인구가 얼마나 더 많나요?',ARRAY['SO4-1-u1-X26','SO4-1-u1-X25']::text[],false,'{"seq":21,"concept":"SO4-1-u1-C9","difficulty":3,"kind":"mc","stem":"일지 ⑥에서 초록군은 노을군보다 인구가 얼마나 더 많나요?","options":[{"t":"3만 명","correct":true},{"t":"15만 명","mis":"SO4-1-u1-X26"},{"t":"9만 명","mis":"SO4-1-u1-X26"},{"t":"200 km²","mis":"SO4-1-u1-X25"}],"explanation":["초록군 9만 명이에요.","노을군 6만 명이에요.","3만 명 많아요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","노을군 — 450 km² — 6만 명","햇살시 — 120 km² — 30만 명","초록군 — 250 km² — 9만 명"],"title":"일지 ⑥ — 세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#22','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C12',3,'mc','auto','일지 ⑨에서 가장 넓은 지역은 어디이고 몇 칸인가요?',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":22,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"mc","stem":"일지 ⑨에서 가장 넓은 지역은 어디이고 몇 칸인가요?","options":[{"t":"햇살시 — 6칸","correct":true},{"t":"노을군 — 6칸","mis":"SO4-1-u1-X32"},{"t":"햇살시 — 5칸","mis":"SO4-1-u1-X32"},{"t":"초록군 — 6칸","mis":"SO4-1-u1-X32"}],"explanation":["칸을 세어요.","2가 6칸이에요.","햇살시예요."],"asset":{"type":"passage","lines":["1 1 2 2","1 1 2 2","1 3 3 2","4 3 3 2","범례 — 1 노을군 · 2 햇살시 · 3 초록군 · 4 달빛군","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"일지 ⑨ — 픽셀 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#23','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C7',4,'essay','teacher','일지 ①의 지도로 학교에서 우체국을 찾아가는 방법을 방위·기호와 범례·축척을 써서 설명하세요. (지도상 거리는 2 cm 예요)','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u1-C7","difficulty":4,"kind":"essay","stem":"일지 ①의 지도로 학교에서 우체국을 찾아가는 방법을 방위·기호와 범례·축척을 써서 설명하세요. (지도상 거리는 2 cm 예요)","answer_guide":{"answer":"예: 범례에서 제비 모양이 우체국이라는 것을 찾아요. 방위표를 보면 우체국은 학교의 왼쪽 아래, 곧 남서쪽에 있어요. 축척 막대가 1 cm = 2 km 이고 지도상 거리가 2 cm 이므로 남서쪽으로 4 km 가면 우체국이에요.","scoring_points":["범례로 우체국 기호를 찾았는가","방위로 남서쪽이라고 썼는가","축척으로 4 km 를 구했는가"]},"explanation":["기호를 찾아요.","방향을 봐요.","거리를 구해요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#24','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C11',4,'essay','teacher','일지 ⑧을 보고 노을군과 햇살시를 두 항목에서 견주고, 두 지역의 특징을 한 문장씩 정리하세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u1-C11","difficulty":4,"kind":"essay","stem":"일지 ⑧을 보고 노을군과 햇살시를 두 항목에서 견주고, 두 지역의 특징을 한 문장씩 정리하세요.","answer_guide":{"answer":"예: 면적은 노을군이 450 km² 로 햇살시 120 km² 보다 넓고, 인구는 햇살시가 30만 명으로 노을군 6만 명보다 많아요. 노을군은 산과 들이 넓은 곳에 사람이 적게 사는 지역이고, 햇살시는 바닷가의 좁은 땅에 사람이 많이 사는 지역이에요.","scoring_points":["같은 항목끼리 두 가지를 견주었는가","표의 수를 바르게 썼는가","두 지역의 특징을 정리했는가"]},"explanation":["항목을 골라요.","같은 것끼리 견줘요.","특징을 써요."],"asset":{"type":"passage","lines":["항목 — 노을군 — 햇살시","위치 — ○○도의 서쪽 — ○○도의 동쪽","지형 — 산·들·강 — 바다·섬","면적 — 450 km² — 120 km²","인구 — 6만 명 — 30만 명","기후 — 여름에 비가 많음 — 겨울에 덜 추움"],"title":"일지 ⑧ — 두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_a#25','soc',4,1,'u1','','g4_1_soc_u1_review_a','unit_review','SO4-1-u1-C12',4,'essay','teacher','일지 ⑨의 픽셀 지도에서 두 지역을 골라 위치와 면적을 견주어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u1-C12","difficulty":4,"kind":"essay","stem":"일지 ⑨의 픽셀 지도에서 두 지역을 골라 위치와 면적을 견주어 쓰세요.","answer_guide":{"answer":"예: 햇살시(2)는 동쪽에 있고 6칸이에요. 달빛군(4)은 남서쪽 끝에 있고 1칸이에요. 햇살시가 달빛군보다 5칸 많아서 면적이 더 넓어요.","scoring_points":["두 지역의 위치를 방위로 썼는가","칸 수를 바르게 셌는가","칸 수로 면적을 견주었는가"]},"explanation":["위치를 봐요.","칸을 세어요.","견주어 써요."],"asset":{"type":"passage","lines":["1 1 2 2","1 1 2 2","1 3 3 2","4 3 3 2","범례 — 1 노을군 · 2 햇살시 · 3 초록군 · 4 달빛군","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"일지 ⑨ — 픽셀 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#1','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C2',1,'sa','auto','일지 ①에서 병원은 학교의 어느 쪽에 있나요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":1,"concept":"SO4-1-u1-C2","difficulty":1,"kind":"sa","stem":"일지 ①에서 병원은 학교의 어느 쪽에 있나요? 두 글자로 쓰세요.","answer":["동쪽"],"explanation":["병원은 오른쪽이에요.","오른쪽은 동쪽이에요.","동쪽이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"},"mis":"SO4-1-u1-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#2','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C3',1,'sa','auto','일지 ①에서 깃발 기호로 나타낸 곳은 어디인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-1-u1-C3","difficulty":1,"kind":"sa","stem":"일지 ①에서 깃발 기호로 나타낸 곳은 어디인가요? 두 글자로 쓰세요.","answer":["학교"],"explanation":["가운데를 봐요.","깃발이에요.","학교예요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"},"mis":"SO4-1-u1-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#3','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C4',1,'sa','auto','일지 ②에서 산 ㉯의 가장 높은 곳에 쓰인 숫자는 무엇인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-1-u1-C4","difficulty":1,"kind":"sa","stem":"일지 ②에서 산 ㉯의 가장 높은 곳에 쓰인 숫자는 무엇인가요? 숫자만 쓰세요.","answer":["600"],"explanation":["가장 안쪽 원이에요.","산 ㉯예요.","600이에요."],"asset":{"type":"passage","lines":["산 ㉮ — 등고선 4겹, 가장 안쪽 원에 쓰인 숫자 400","산 ㉯ — 등고선 6겹, 가장 안쪽 원에 쓰인 숫자 600","산 ㉯ 북쪽 비탈 — 등고선 간격이 넓다","산 ㉯ 남쪽 비탈 — 등고선 간격이 좁다"],"title":"일지 ② — 두 산의 등고선"},"mis":"SO4-1-u1-X13"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#4','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C5',1,'sa','auto','일지 ③에서 학교부터 도서관까지의 실제 거리는 몇 km 인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO4-1-u1-C5","difficulty":1,"kind":"sa","stem":"일지 ③에서 학교부터 도서관까지의 실제 거리는 몇 km 인가요? 숫자만 쓰세요.","answer":["4"],"explanation":["1 cm 가 2 km 예요.","2 cm 예요.","4 km 예요."],"asset":{"type":"passage","lines":["축척 막대 — 1 cm = 2 km","학교 ~ 도서관: 지도에서 2 cm","학교 ~ 기차역: 지도에서 5 cm"],"title":"일지 ③ — 은빛마을 거리 재기"},"mis":"SO4-1-u1-X16"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#5','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C6',1,'sa','auto','목적지까지 가는 길을 간단히 그린 지도는 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-1-u1-C6","difficulty":1,"kind":"sa","stem":"목적지까지 가는 길을 간단히 그린 지도는 무엇인가요? 두 글자로 쓰세요.","answer":["약도"],"explanation":["길을 간단히 그려요.","약◯예요.","약도예요."],"mis":"SO4-1-u1-X20"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#6','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C8',1,'sa','auto','일지 ⑤에서 노을군의 북쪽에 있는 지형은 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-1-u1-C8","difficulty":1,"kind":"sa","stem":"일지 ⑤에서 노을군의 북쪽에 있는 지형은 무엇인가요? 한 글자로 쓰세요.","answer":["산"],"explanation":["북쪽을 찾아요.","높은 땅이에요.","산이에요."],"asset":{"type":"passage","lines":["노을군은 ○○도의 서쪽에 있고, 동쪽으로 햇살시와 맞닿아 있다.","노을군의 북쪽에는 높은 산이 있고, 남쪽에는 넓은 들이 있다.","강이 산에서 들을 지나 서쪽 바다로 흐른다.","산골 마을에서는 버섯을 기르고, 들에서는 벼농사를 짓는다."],"title":"일지 ⑤ — 노을군 소개"},"mis":"SO4-1-u1-X23"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#7','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C9',1,'sa','auto','일지 ⑥에서 인구가 가장 많은 지역은 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-1-u1-C9","difficulty":1,"kind":"sa","stem":"일지 ⑥에서 인구가 가장 많은 지역은 어디인가요? 세 글자로 쓰세요.","answer":["햇살시"],"explanation":["인구를 견줘요.","30만 명이에요.","햇살시예요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","노을군 — 450 km² — 6만 명","햇살시 — 120 km² — 30만 명","초록군 — 250 km² — 9만 명"],"title":"일지 ⑥ — 세 지역의 면적과 인구"},"mis":"SO4-1-u1-X25"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#8','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C10',1,'sa','auto','일지 ⑦에서 기온이 가장 낮은 달은 몇 월인가요? 숫자만 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-1-u1-C10","difficulty":1,"kind":"sa","stem":"일지 ⑦에서 기온이 가장 낮은 달은 몇 월인가요? 숫자만 쓰세요.","answer":["1"],"explanation":["기온을 견줘요.","0 °C 예요.","1월이에요."],"asset":{"type":"passage","lines":["1월 — 기온 0 °C · 강수량 30 mm","4월 — 기온 12 °C · 강수량 90 mm","7월 — 기온 25 °C · 강수량 280 mm","10월 — 기온 15 °C · 강수량 50 mm"],"title":"일지 ⑦ — 노을군 기온과 강수량"},"mis":"SO4-1-u1-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#9','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C2',2,'ox','auto','앞·뒤·오른쪽·왼쪽으로 위치를 말해도 누구에게나 똑같이 전해져요.',ARRAY['SO4-1-u1-X05']::text[],false,'{"seq":9,"concept":"SO4-1-u1-C2","difficulty":2,"kind":"ox","stem":"앞·뒤·오른쪽·왼쪽으로 위치를 말해도 누구에게나 똑같이 전해져요.","answer":"X","reason_options":[{"t":"보는 방향에 따라 오른쪽·왼쪽이 달라지기 때문에","correct":true},{"t":"오른쪽은 누구에게나 같은 쪽이기 때문에","mis":"SO4-1-u1-X05"}],"mis":"SO4-1-u1-X05","explanation":["보는 방향이 달라요.","오른쪽이 바뀌어요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#10','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C3',2,'mc','auto','그림 문자인 픽토그램을 쓰면 좋은 점은 무엇인가요?',ARRAY['SO4-1-u1-X03','SO4-1-u1-X04']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"mc","stem":"그림 문자인 픽토그램을 쓰면 좋은 점은 무엇인가요?","options":[{"t":"글자를 몰라도 누구나 쉽게 알아봐요","correct":true},{"t":"한 사람만 알아봐요","mis":"SO4-1-u1-X03"},{"t":"글자를 많이 써야 해요","mis":"SO4-1-u1-X04"},{"t":"색만 화려해져요","mis":"SO4-1-u1-X03"}],"explanation":["그림 문자예요.","글자가 없어도 돼요.","누구나 알아봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#11','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C4',2,'ox','auto','일지 ②에서 산 ㉯의 남쪽 비탈은 북쪽 비탈보다 경사가 완만해요.',ARRAY['SO4-1-u1-X14']::text[],false,'{"seq":11,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"ox","stem":"일지 ②에서 산 ㉯의 남쪽 비탈은 북쪽 비탈보다 경사가 완만해요.","answer":"X","reason_options":[{"t":"남쪽 비탈은 등고선 간격이 좁아 경사가 더 급하기 때문에","correct":true},{"t":"간격이 좁을수록 완만하기 때문에","mis":"SO4-1-u1-X14"}],"mis":"SO4-1-u1-X14","explanation":["남쪽은 좁아요.","좁으면 급해요.","그래서 X예요."],"asset":{"type":"passage","lines":["산 ㉮ — 등고선 4겹, 가장 안쪽 원에 쓰인 숫자 400","산 ㉯ — 등고선 6겹, 가장 안쪽 원에 쓰인 숫자 600","산 ㉯ 북쪽 비탈 — 등고선 간격이 넓다","산 ㉯ 남쪽 비탈 — 등고선 간격이 좁다"],"title":"일지 ② — 두 산의 등고선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#12','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C5',2,'ox','auto','실제 거리를 구할 때는 축척을 확인하지 않고 지도상 거리만 재면 돼요.',ARRAY['SO4-1-u1-X18']::text[],false,'{"seq":12,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"ox","stem":"실제 거리를 구할 때는 축척을 확인하지 않고 지도상 거리만 재면 돼요.","answer":"X","reason_options":[{"t":"축척을 먼저 확인해야 지도상 거리를 실제 거리로 바꿀 수 있기 때문에","correct":true},{"t":"지도상 거리가 곧 실제 거리이기 때문에","mis":"SO4-1-u1-X18"}],"mis":"SO4-1-u1-X18","explanation":["축척이 먼저예요.","그다음 재요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#13','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C6',2,'ox','auto','일지 ④의 ㉢처럼 버스를 갈아탈 때는 버스 노선도를 보면 좋아요.',ARRAY['SO4-1-u1-X20']::text[],false,'{"seq":13,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"ox","stem":"일지 ④의 ㉢처럼 버스를 갈아탈 때는 버스 노선도를 보면 좋아요.","answer":"O","reason_options":[{"t":"노선도로 어디에서 갈아타는지 알 수 있기 때문에","correct":true},{"t":"노선도는 관광지만 알려 주기 때문에","mis":"SO4-1-u1-X20"}],"mis":"SO4-1-u1-X20","explanation":["갈아타요.","노선도예요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 할머니 댁에 처음 자동차로 간다.","㉡ 다른 고장의 볼거리를 찾는다.","㉢ 버스를 갈아타고 체육관에 간다.","㉣ 친구에게 우리 집 가는 길을 간단히 알려 준다."],"title":"일지 ④ — 지도가 필요한 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#14','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C8',2,'ox','auto','일지 ⑤에서 노을군 강은 동쪽 바다로 흘러요.',ARRAY['SO4-1-u1-X23']::text[],false,'{"seq":14,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"ox","stem":"일지 ⑤에서 노을군 강은 동쪽 바다로 흘러요.","answer":"X","reason_options":[{"t":"강은 산에서 들을 지나 서쪽 바다로 흐르기 때문에","correct":true},{"t":"강은 언제나 동쪽으로만 흐르기 때문에","mis":"SO4-1-u1-X23"}],"mis":"SO4-1-u1-X23","explanation":["강을 찾아요.","서쪽 바다예요.","그래서 X예요."],"asset":{"type":"passage","lines":["노을군은 ○○도의 서쪽에 있고, 동쪽으로 햇살시와 맞닿아 있다.","노을군의 북쪽에는 높은 산이 있고, 남쪽에는 넓은 들이 있다.","강이 산에서 들을 지나 서쪽 바다로 흐른다.","산골 마을에서는 버섯을 기르고, 들에서는 벼농사를 짓는다."],"title":"일지 ⑤ — 노을군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#15','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C9',2,'ox','auto','일지 ⑥을 보면 면적이 넓을수록 인구도 반드시 많아요.',ARRAY['SO4-1-u1-X25']::text[],false,'{"seq":15,"concept":"SO4-1-u1-C9","difficulty":2,"kind":"ox","stem":"일지 ⑥을 보면 면적이 넓을수록 인구도 반드시 많아요.","answer":"X","reason_options":[{"t":"노을군은 가장 넓지만 인구는 가장 적기 때문에","correct":true},{"t":"면적과 인구는 언제나 함께 늘기 때문에","mis":"SO4-1-u1-X25"}],"mis":"SO4-1-u1-X25","explanation":["노을군은 넓어요.","인구는 적어요.","그래서 X예요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","노을군 — 450 km² — 6만 명","햇살시 — 120 km² — 30만 명","초록군 — 250 km² — 9만 명"],"title":"일지 ⑥ — 세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#16','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C10',2,'ox','auto','기후 그래프에서 강수량은 막대로 나타내요.',ARRAY['SO4-1-u1-X28']::text[],false,'{"seq":16,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"ox","stem":"기후 그래프에서 강수량은 막대로 나타내요.","answer":"O","reason_options":[{"t":"보통 기온은 꺾은선, 강수량은 막대로 함께 나타내기 때문에","correct":true},{"t":"강수량은 꺾은선으로만 나타내기 때문에","mis":"SO4-1-u1-X28"}],"mis":"SO4-1-u1-X28","explanation":["강수량이에요.","막대예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#17','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C7',3,'error','auto','일지 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X11','SO4-1-u1-X09']::text[],false,'{"seq":17,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"error","stem":"일지 ①을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「등고선을 보면 병원까지 거리를 알 수 있어.」","correct":true,"mis_target":"SO4-1-u1-X11"},{"t":"친구 가 — 「축척 막대로 실제 거리를 구해.」","mis":"SO4-1-u1-X11"},{"t":"친구 다 — 「범례로 병원 기호를 찾아.」","mis":"SO4-1-u1-X09"}],"explanation":["등고선은 높낮이예요.","거리는 축척이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#18','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C5',3,'ox','auto','「1 cm = 2 km」 지도와 「1 cm = 1 km」 지도에 같은 길을 그리면 「1 cm = 2 km」 지도에서 더 짧게 그려져요.',ARRAY['SO4-1-u1-X17']::text[],false,'{"seq":18,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"ox","stem":"「1 cm = 2 km」 지도와 「1 cm = 1 km」 지도에 같은 길을 그리면 「1 cm = 2 km」 지도에서 더 짧게 그려져요.","answer":"O","reason_options":[{"t":"실제 거리를 더 많이 줄인 지도이기 때문에","correct":true},{"t":"줄인 정도와 관계없이 길이가 같기 때문에","mis":"SO4-1-u1-X17"}],"mis":"SO4-1-u1-X17","explanation":["2 km 를 1 cm 에 담아요.","더 많이 줄였어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#19','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C6',3,'ox','auto','일지 ④의 네 상황에는 모두 같은 지도 한 장만 쓰는 것이 가장 편리해요.',ARRAY['SO4-1-u1-X19']::text[],false,'{"seq":19,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"ox","stem":"일지 ④의 네 상황에는 모두 같은 지도 한 장만 쓰는 것이 가장 편리해요.","answer":"X","reason_options":[{"t":"상황마다 필요한 정보가 달라 알맞은 지도가 다르기 때문에","correct":true},{"t":"지도는 모두 같은 정보를 담고 있기 때문에","mis":"SO4-1-u1-X19"}],"mis":"SO4-1-u1-X19","explanation":["상황이 달라요.","필요한 정보도 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 할머니 댁에 처음 자동차로 간다.","㉡ 다른 고장의 볼거리를 찾는다.","㉢ 버스를 갈아타고 체육관에 간다.","㉣ 친구에게 우리 집 가는 길을 간단히 알려 준다."],"title":"일지 ④ — 지도가 필요한 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#20','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C11',3,'ox','auto','일지 ⑧에서 노을군과 햇살시는 지형이 서로 달라요.',ARRAY['SO4-1-u1-X23']::text[],false,'{"seq":20,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"ox","stem":"일지 ⑧에서 노을군과 햇살시는 지형이 서로 달라요.","answer":"O","reason_options":[{"t":"노을군은 산·들·강, 햇살시는 바다·섬이 있기 때문에","correct":true},{"t":"두 지역의 지형이 같기 때문에","mis":"SO4-1-u1-X23"}],"mis":"SO4-1-u1-X23","explanation":["지형 줄을 봐요.","서로 달라요.","그래서 O예요."],"asset":{"type":"passage","lines":["항목 — 노을군 — 햇살시","위치 — ○○도의 서쪽 — ○○도의 동쪽","지형 — 산·들·강 — 바다·섬","면적 — 450 km² — 120 km²","인구 — 6만 명 — 30만 명","기후 — 여름에 비가 많음 — 겨울에 덜 추움"],"title":"일지 ⑧ — 두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#21','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C10',3,'ox','auto','일지 ⑦을 보면 노을군은 기온이 높은 달에 비도 가장 많이 와요.',ARRAY['SO4-1-u1-X29']::text[],false,'{"seq":21,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"ox","stem":"일지 ⑦을 보면 노을군은 기온이 높은 달에 비도 가장 많이 와요.","answer":"O","reason_options":[{"t":"7월에 기온이 가장 높고 강수량도 가장 많기 때문에","correct":true},{"t":"기온이 높은 달에는 비가 오지 않기 때문에","mis":"SO4-1-u1-X29"}],"mis":"SO4-1-u1-X29","explanation":["7월을 봐요.","둘 다 가장 커요.","그래서 O예요."],"asset":{"type":"passage","lines":["1월 — 기온 0 °C · 강수량 30 mm","4월 — 기온 12 °C · 강수량 90 mm","7월 — 기온 25 °C · 강수량 280 mm","10월 — 기온 15 °C · 강수량 50 mm"],"title":"일지 ⑦ — 노을군 기온과 강수량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#22','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C12',3,'ox','auto','일지 ⑨에서 달빛군은 지도의 남서쪽 끝에 있어요.',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":22,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"ox","stem":"일지 ⑨에서 달빛군은 지도의 남서쪽 끝에 있어요.","answer":"O","reason_options":[{"t":"숫자 4가 맨 아래 줄 왼쪽 끝에 있기 때문에","correct":true},{"t":"숫자 4가 맨 위 줄 오른쪽에 있기 때문에","mis":"SO4-1-u1-X06"}],"mis":"SO4-1-u1-X06","explanation":["4를 찾아요.","아래 왼쪽이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["1 1 2 2","1 1 2 2","1 3 3 2","4 3 3 2","범례 — 1 노을군 · 2 햇살시 · 3 초록군 · 4 달빛군","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"일지 ⑨ — 픽셀 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#23','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C4',4,'essay','teacher','일지 ②의 두 산 가운데 하나를 골라 그 산의 높이와 경사를 등고선을 근거로 설명하세요.','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u1-C4","difficulty":4,"kind":"essay","stem":"일지 ②의 두 산 가운데 하나를 골라 그 산의 높이와 경사를 등고선을 근거로 설명하세요.","answer_guide":{"answer":"예: 산 ㉯는 가장 안쪽 원에 600이 쓰여 있어 600 높이까지 올라가요. 북쪽 비탈은 등고선 간격이 넓어 완만하고, 남쪽 비탈은 간격이 좁아 경사가 급해요.","scoring_points":["산 하나를 골랐는가","숫자로 높이를 썼는가","간격으로 경사를 바르게 설명했는가"]},"explanation":["숫자를 봐요.","간격을 봐요.","근거를 써요."],"asset":{"type":"passage","lines":["산 ㉮ — 등고선 4겹, 가장 안쪽 원에 쓰인 숫자 400","산 ㉯ — 등고선 6겹, 가장 안쪽 원에 쓰인 숫자 600","산 ㉯ 북쪽 비탈 — 등고선 간격이 넓다","산 ㉯ 남쪽 비탈 — 등고선 간격이 좁다"],"title":"일지 ② — 두 산의 등고선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#24','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C9',4,'essay','teacher','일지 ⑥을 보고 인구가 가장 많은 햇살시에 필요한 계획 하나를 쓰고, 면적과 인구를 근거로 까닭을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u1-C9","difficulty":4,"kind":"essay","stem":"일지 ⑥을 보고 인구가 가장 많은 햇살시에 필요한 계획 하나를 쓰고, 면적과 인구를 근거로 까닭을 쓰세요.","answer_guide":{"answer":"예: 햇살시에는 공원을 더 만들어야 해요. 햇살시는 면적이 120 km² 로 가장 좁은데 인구는 30만 명으로 가장 많아서, 좁은 땅에 많은 사람이 살아 쉴 곳이 부족할 수 있기 때문이에요.","scoring_points":["계획을 하나 썼는가","면적과 인구를 근거로 들었는가","계획과 근거가 이어지는가"]},"explanation":["면적을 봐요.","인구를 봐요.","계획을 써요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","노을군 — 450 km² — 6만 명","햇살시 — 120 km² — 30만 명","초록군 — 250 km² — 9만 명"],"title":"일지 ⑥ — 세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_b#25','soc',4,1,'u1','','g4_1_soc_u1_review_b','unit_review','SO4-1-u1-C8',4,'essay','teacher','일지 ⑤를 보고 노을군의 위치를 한 문장으로 쓰고, 지형과 생활 모습을 이어 노을군을 소개하세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u1-C8","difficulty":4,"kind":"essay","stem":"일지 ⑤를 보고 노을군의 위치를 한 문장으로 쓰고, 지형과 생활 모습을 이어 노을군을 소개하세요.","answer_guide":{"answer":"예: 노을군은 ○○도의 서쪽에 있고 동쪽으로 햇살시와 맞닿아 있어요. 북쪽의 높은 산골 마을에서는 버섯을 기르고, 남쪽의 넓은 들에서는 벼농사를 지어요.","scoring_points":["방위와 이웃 지역으로 위치를 썼는가","지형을 바르게 썼는가","지형과 생활 모습을 이었는가"]},"explanation":["위치를 써요.","지형을 써요.","생활과 이어요."],"asset":{"type":"passage","lines":["노을군은 ○○도의 서쪽에 있고, 동쪽으로 햇살시와 맞닿아 있다.","노을군의 북쪽에는 높은 산이 있고, 남쪽에는 넓은 들이 있다.","강이 산에서 들을 지나 서쪽 바다로 흐른다.","산골 마을에서는 버섯을 기르고, 들에서는 벼농사를 짓는다."],"title":"일지 ⑤ — 노을군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#1','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C2',1,'ox','auto','방위표에서 위쪽은 북쪽이에요.',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C2","difficulty":1,"kind":"ox","stem":"방위표에서 위쪽은 북쪽이에요.","answer":"O","reason_options":[{"t":"방위표의 화살표가 북쪽을 가리키기 때문에","correct":true},{"t":"위쪽은 언제나 남쪽이기 때문에","mis":"SO4-1-u1-X06"}],"mis":"SO4-1-u1-X06","explanation":["화살표를 봐요.","위쪽이 북쪽이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#2','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C3',1,'ox','auto','기호는 장소의 생김새나 특징을 본떠 만들어요.',ARRAY['SO4-1-u1-X10']::text[],false,'{"seq":2,"concept":"SO4-1-u1-C3","difficulty":1,"kind":"ox","stem":"기호는 장소의 생김새나 특징을 본떠 만들어요.","answer":"O","reason_options":[{"t":"그래서 누구나 뜻을 짐작하기 쉽기 때문에","correct":true},{"t":"기호는 아무렇게나 정하기 때문에","mis":"SO4-1-u1-X10"}],"mis":"SO4-1-u1-X10","explanation":["본떠 만들어요.","짐작하기 쉬워요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#3','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C4',1,'ox','auto','등고선 지도에서 높은 곳은 고동색으로 나타내요.',ARRAY['SO4-1-u1-X15']::text[],false,'{"seq":3,"concept":"SO4-1-u1-C4","difficulty":1,"kind":"ox","stem":"등고선 지도에서 높은 곳은 고동색으로 나타내요.","answer":"O","reason_options":[{"t":"낮은 곳은 초록색, 높은 곳은 고동색이기 때문에","correct":true},{"t":"높은 곳은 초록색이기 때문에","mis":"SO4-1-u1-X15"}],"mis":"SO4-1-u1-X15","explanation":["높은 곳이에요.","고동색이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#4','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C5',1,'ox','auto','실제 거리를 덜 줄인 지도는 좁은 지역을 자세하게 보여 줘요.',ARRAY['SO4-1-u1-X17']::text[],false,'{"seq":4,"concept":"SO4-1-u1-C5","difficulty":1,"kind":"ox","stem":"실제 거리를 덜 줄인 지도는 좁은 지역을 자세하게 보여 줘요.","answer":"O","reason_options":[{"t":"덜 줄일수록 좁은 곳이 크게 나오기 때문에","correct":true},{"t":"덜 줄인 지도일수록 넓은 지역이 담기기 때문에","mis":"SO4-1-u1-X17"}],"mis":"SO4-1-u1-X17","explanation":["덜 줄였어요.","자세해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#5','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C6',1,'ox','auto','지도는 상황과 목적에 맞게 골라 써야 편리해요.',ARRAY['SO4-1-u1-X19']::text[],false,'{"seq":5,"concept":"SO4-1-u1-C6","difficulty":1,"kind":"ox","stem":"지도는 상황과 목적에 맞게 골라 써야 편리해요.","answer":"O","reason_options":[{"t":"지도마다 담긴 정보가 다르기 때문에","correct":true},{"t":"어떤 지도든 담긴 정보가 같기 때문에","mis":"SO4-1-u1-X19"}],"mis":"SO4-1-u1-X19","explanation":["정보가 달라요.","골라 써요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
