INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#7','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C9',1,'ox','auto','땅이 차지하는 넓이를 면적이라고 해요.',ARRAY['SO4-1-u1-X25']::text[],false,'{"seq":7,"concept":"SO4-1-u1-C9","difficulty":1,"kind":"ox","stem":"땅이 차지하는 넓이를 면적이라고 해요.","answer":"O","reason_options":[{"t":"면적은 땅의 넓이를 뜻하기 때문에","correct":true},{"t":"면적은 사람의 수를 뜻하기 때문에","mis":"SO4-1-u1-X25"}],"mis":"SO4-1-u1-X25","explanation":["넓이예요.","면적이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#8','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C10',1,'ox','auto','기온은 도(°C)로 나타내요.',ARRAY['SO4-1-u1-X27']::text[],false,'{"seq":8,"concept":"SO4-1-u1-C10","difficulty":1,"kind":"ox","stem":"기온은 도(°C)로 나타내요.","answer":"O","reason_options":[{"t":"공기가 따뜻하고 차가운 정도를 °C 로 나타내기 때문에","correct":true},{"t":"기온은 mm 로 나타내기 때문에","mis":"SO4-1-u1-X27"}],"mis":"SO4-1-u1-X27","explanation":["기온의 단위예요.","°C 예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#9','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C2',2,'match','auto','일지 ①의 장소와 학교에서 본 방위를 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-1-u1-C2","difficulty":2,"kind":"match","stem":"일지 ①의 장소와 학교에서 본 방위를 알맞게 이으세요.","pairs":[{"l":"산","r":"북쪽"},{"l":"병원","r":"동쪽"},{"l":"강","r":"남쪽"},{"l":"우체국","r":"남서쪽"}],"mis":"SO4-1-u1-X06","explanation":["위쪽은 북쪽이에요.","오른쪽은 동쪽이에요.","왼쪽 아래는 남서쪽이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#10','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C3',2,'match','auto','일지 ①의 기호와 뜻을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"match","stem":"일지 ①의 기호와 뜻을 알맞게 이으세요.","pairs":[{"l":"깃발","r":"학교"},{"l":"＋","r":"병원"},{"l":"파란 선","r":"강"},{"l":"제비 모양","r":"우체국"}],"mis":"SO4-1-u1-X09","explanation":["범례를 떠올려요.","하나씩 이어요.","약속이에요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#11','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C4',2,'mc','auto','등고선과 함께 쓰여 있는 숫자는 무엇을 알려 주나요?',ARRAY['SO4-1-u1-X12']::text[],false,'{"seq":11,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"mc","stem":"등고선과 함께 쓰여 있는 숫자는 무엇을 알려 주나요?","options":[{"t":"땅의 높이","correct":true},{"t":"사람 수","mis":"SO4-1-u1-X12"},{"t":"집 개수","mis":"SO4-1-u1-X12"},{"t":"산의 나이","mis":"SO4-1-u1-X12"}],"explanation":["등고선 옆이에요.","높이예요.","땅의 높이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#12','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C5',2,'mc','auto','같은 크기의 종이에 그린 두 지도 가운데 더 넓은 지역이 담긴 지도는 어느 것인가요?',ARRAY['SO4-1-u1-X17','SO4-1-u1-X18']::text[],false,'{"seq":12,"concept":"SO4-1-u1-C5","difficulty":2,"kind":"mc","stem":"같은 크기의 종이에 그린 두 지도 가운데 더 넓은 지역이 담긴 지도는 어느 것인가요?","options":[{"t":"실제 거리를 더 많이 줄인 지도","correct":true},{"t":"실제 거리를 덜 줄인 지도","mis":"SO4-1-u1-X17"},{"t":"글자가 큰 지도","mis":"SO4-1-u1-X17"},{"t":"축척 막대가 없는 지도","mis":"SO4-1-u1-X18"}],"explanation":["같은 종이예요.","많이 줄이면 넓게 담겨요.","많이 줄인 지도예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#13','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C6',2,'match','auto','일지 ④의 상황과 알맞은 지도를 이으세요.','{}'::text[],false,'{"seq":13,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"match","stem":"일지 ④의 상황과 알맞은 지도를 이으세요.","pairs":[{"l":"㉡ 볼거리 찾기","r":"관광 안내도"},{"l":"㉢ 버스 갈아타기","r":"버스 노선도"},{"l":"㉣ 우리 집 가는 길 알려 주기","r":"약도"}],"mis":"SO4-1-u1-X19","explanation":["상황을 읽어요.","목적을 떠올려요.","지도를 이어요."],"asset":{"type":"passage","lines":["㉠ 할머니 댁에 처음 자동차로 간다.","㉡ 다른 고장의 볼거리를 찾는다.","㉢ 버스를 갈아타고 체육관에 간다.","㉣ 친구에게 우리 집 가는 길을 간단히 알려 준다."],"title":"일지 ④ — 지도가 필요한 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#14','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C8',2,'match','auto','일지 ⑤의 지형과 그곳의 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"match","stem":"일지 ⑤의 지형과 그곳의 생활 모습을 알맞게 이으세요.","pairs":[{"l":"북쪽 산골","r":"버섯 기르기"},{"l":"남쪽 들","r":"벼농사 짓기"}],"mis":"SO4-1-u1-X24","explanation":["산골이에요.","들이에요.","지형에 따라 달라요."],"asset":{"type":"passage","lines":["노을군은 ○○도의 서쪽에 있고, 동쪽으로 햇살시와 맞닿아 있다.","노을군의 북쪽에는 높은 산이 있고, 남쪽에는 넓은 들이 있다.","강이 산에서 들을 지나 서쪽 바다로 흐른다.","산골 마을에서는 버섯을 기르고, 들에서는 벼농사를 짓는다."],"title":"일지 ⑤ — 노을군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#15','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C9',2,'mc','auto','면적의 단위로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X27','SO4-1-u1-X25']::text[],false,'{"seq":15,"concept":"SO4-1-u1-C9","difficulty":2,"kind":"mc","stem":"면적의 단위로 알맞은 것은 무엇인가요?","options":[{"t":"제곱킬로미터(km²)","correct":true},{"t":"밀리미터(mm)","mis":"SO4-1-u1-X27"},{"t":"도(°C)","mis":"SO4-1-u1-X27"},{"t":"명","mis":"SO4-1-u1-X25"}],"explanation":["넓이의 단위예요.","km² 예요.","제곱킬로미터예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#16','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C10',2,'mc','auto','우리나라 겨울 날씨의 특징으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X29']::text[],false,'{"seq":16,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"mc","stem":"우리나라 겨울 날씨의 특징으로 알맞은 것은 무엇인가요?","options":[{"t":"춥고 비나 눈이 적어 건조해요","correct":true},{"t":"덥고 비가 가장 많아요","mis":"SO4-1-u1-X29"},{"t":"따뜻하고 장마가 있어요","mis":"SO4-1-u1-X29"},{"t":"일 년 내내 같은 날씨예요","mis":"SO4-1-u1-X29"}],"explanation":["겨울이에요.","추워요.","건조해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#17','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C7',3,'ox','auto','일지 ①에서 학교부터 병원까지 지도상 거리가 3 cm 라면 실제 거리는 6 km 예요.',ARRAY['SO4-1-u1-X16']::text[],false,'{"seq":17,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"ox","stem":"일지 ①에서 학교부터 병원까지 지도상 거리가 3 cm 라면 실제 거리는 6 km 예요.","answer":"O","reason_options":[{"t":"축척 막대가 1 cm = 2 km 이므로 3 cm 는 6 km 이기 때문에","correct":true},{"t":"지도상 거리 3 cm 가 곧 실제 거리이기 때문에","mis":"SO4-1-u1-X16"}],"mis":"SO4-1-u1-X16","explanation":["1 cm 가 2 km 예요.","3 cm 예요.","그래서 O예요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#18','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C5',3,'mc','auto','「1 cm = 3 km」 지도에서 지도상 거리가 4 cm 인 두 곳의 실제 거리는 얼마인가요?',ARRAY['SO4-1-u1-X16','SO4-1-u1-X18']::text[],false,'{"seq":18,"concept":"SO4-1-u1-C5","difficulty":3,"kind":"mc","stem":"「1 cm = 3 km」 지도에서 지도상 거리가 4 cm 인 두 곳의 실제 거리는 얼마인가요?","options":[{"t":"12 km","correct":true},{"t":"7 km","mis":"SO4-1-u1-X16"},{"t":"4 km","mis":"SO4-1-u1-X18"},{"t":"34 km","mis":"SO4-1-u1-X16"}],"explanation":["1 cm 가 3 km 예요.","4 cm 는 4배예요.","12 km 예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#19','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C6',3,'mc','auto','상황에 맞는 지도를 골라 쓰면 가장 좋은 점은 무엇인가요?',ARRAY['SO4-1-u1-X19']::text[],false,'{"seq":19,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"mc","stem":"상황에 맞는 지도를 골라 쓰면 가장 좋은 점은 무엇인가요?","options":[{"t":"이동을 미리 계획할 수 있어요","correct":true},{"t":"지도를 볼 필요가 없어요","mis":"SO4-1-u1-X19"},{"t":"모든 지도가 같아져요","mis":"SO4-1-u1-X19"},{"t":"길을 잃어도 괜찮아요","mis":"SO4-1-u1-X19"}],"explanation":["알맞은 지도예요.","미리 알아요.","계획해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#20','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C11',3,'error','auto','일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X25','SO4-1-u1-X23','SO4-1-u1-X22']::text[],false,'{"seq":20,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"error","stem":"일지 ⑧을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「햇살시는 노을군보다 넓어.」","correct":true,"mis_target":"SO4-1-u1-X25"},{"t":"친구 나 — 「햇살시는 바다와 섬이 있어.」","mis":"SO4-1-u1-X23"},{"t":"친구 다 — 「노을군은 ○○도의 서쪽에 있어.」","mis":"SO4-1-u1-X22"}],"explanation":["면적 줄을 봐요.","노을군이 더 넓어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["항목 — 노을군 — 햇살시","위치 — ○○도의 서쪽 — ○○도의 동쪽","지형 — 산·들·강 — 바다·섬","면적 — 450 km² — 120 km²","인구 — 6만 명 — 30만 명","기후 — 여름에 비가 많음 — 겨울에 덜 추움"],"title":"일지 ⑧ — 두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#21','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C10',3,'mc','auto','일지 ⑦을 기후 그래프로 그리면 7월의 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X26','SO4-1-u1-X28']::text[],false,'{"seq":21,"concept":"SO4-1-u1-C10","difficulty":3,"kind":"mc","stem":"일지 ⑦을 기후 그래프로 그리면 7월의 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"꺾은선이 가장 높고 막대가 가장 길어요","correct":true},{"t":"꺾은선이 가장 낮고 막대가 가장 짧아요","mis":"SO4-1-u1-X26"},{"t":"막대가 가장 높고 꺾은선이 가장 길어요","mis":"SO4-1-u1-X28"},{"t":"꺾은선과 막대가 모두 없어요","mis":"SO4-1-u1-X28"}],"explanation":["기온은 꺾은선이에요.","강수량은 막대예요.","7월은 둘 다 커요."],"asset":{"type":"passage","lines":["1월 — 기온 0 °C · 강수량 30 mm","4월 — 기온 12 °C · 강수량 90 mm","7월 — 기온 25 °C · 강수량 280 mm","10월 — 기온 15 °C · 강수량 50 mm"],"title":"일지 ⑦ — 노을군 기온과 강수량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#22','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C12',3,'error','auto','일지 ⑨를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":22,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"error","stem":"일지 ⑨를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「노을군은 칸이 많으니 사람이 가장 많이 살아.」","correct":true,"mis_target":"SO4-1-u1-X32"},{"t":"친구 가 — 「초록군은 4칸이야.」","mis":"SO4-1-u1-X32"},{"t":"친구 다 — 「햇살시는 동쪽에 있어.」","mis":"SO4-1-u1-X32"}],"explanation":["칸 수는 면적이에요.","인구가 아니에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["1 1 2 2","1 1 2 2","1 3 3 2","4 3 3 2","범례 — 1 노을군 · 2 햇살시 · 3 초록군 · 4 달빛군","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"일지 ⑨ — 픽셀 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#23','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C7',4,'mc','auto','어떤 지도에 방위표·범례·등고선은 있는데 축척 막대가 없어요. 이 지도로 알기 어려운 것은 무엇인가요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":23,"concept":"SO4-1-u1-C7","difficulty":4,"kind":"mc","stem":"어떤 지도에 방위표·범례·등고선은 있는데 축척 막대가 없어요. 이 지도로 알기 어려운 것은 무엇인가요?","options":[{"t":"두 장소 사이의 실제 거리","correct":true},{"t":"장소가 있는 방향","mis":"SO4-1-u1-X11"},{"t":"땅의 높낮이","mis":"SO4-1-u1-X11"},{"t":"기호가 뜻하는 장소","mis":"SO4-1-u1-X11"}],"explanation":["빠진 요소를 찾아요.","축척이 없어요.","실제 거리를 몰라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#24','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C11',4,'mc','auto','노을군 친구가 햇살시로 이사 가요. 일지 ⑧을 보고 해 줄 말로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-1-u1-X23','SO4-1-u1-X25','SO4-1-u1-X31']::text[],false,'{"seq":24,"concept":"SO4-1-u1-C11","difficulty":4,"kind":"mc","stem":"노을군 친구가 햇살시로 이사 가요. 일지 ⑧을 보고 해 줄 말로 가장 알맞은 것은 무엇인가요?","options":[{"t":"햇살시는 바다와 섬이 있고 사람이 훨씬 많아","correct":true},{"t":"햇살시도 산과 들뿐이야","mis":"SO4-1-u1-X23"},{"t":"햇살시는 노을군보다 땅이 넓어","mis":"SO4-1-u1-X25"},{"t":"햇살시와 노을군은 모든 것이 같아","mis":"SO4-1-u1-X31"}],"explanation":["지형을 봐요.","인구를 봐요.","알맞은 말을 골라요."],"asset":{"type":"passage","lines":["항목 — 노을군 — 햇살시","위치 — ○○도의 서쪽 — ○○도의 동쪽","지형 — 산·들·강 — 바다·섬","면적 — 450 km² — 120 km²","인구 — 6만 명 — 30만 명","기후 — 여름에 비가 많음 — 겨울에 덜 추움"],"title":"일지 ⑧ — 두 지역 지리 정보 비교표"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_c#25','soc',4,1,'u1','','g4_1_soc_u1_review_c','unit_review','SO4-1-u1-C8',4,'mc','auto','노을군에 큰 공원을 만든다면 지형으로 볼 때 가장 알맞은 곳과 까닭을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-1-u1-X23','SO4-1-u1-X24']::text[],false,'{"seq":25,"concept":"SO4-1-u1-C8","difficulty":4,"kind":"mc","stem":"노을군에 큰 공원을 만든다면 지형으로 볼 때 가장 알맞은 곳과 까닭을 바르게 말한 것은 무엇인가요?","options":[{"t":"남쪽 들 — 넓고 평평해서","correct":true},{"t":"북쪽 산 — 높이 솟아 있어서","mis":"SO4-1-u1-X23"},{"t":"서쪽 바다 위 — 물이 많아서","mis":"SO4-1-u1-X23"},{"t":"어디든 같아요 — 지형은 관계없어서","mis":"SO4-1-u1-X24"}],"explanation":["넓고 평평한 곳이에요.","들이에요.","남쪽 들이에요."],"asset":{"type":"passage","lines":["노을군은 ○○도의 서쪽에 있고, 동쪽으로 햇살시와 맞닿아 있다.","노을군의 북쪽에는 높은 산이 있고, 남쪽에는 넓은 들이 있다.","강이 산에서 들을 지나 서쪽 바다로 흐른다.","산골 마을에서는 버섯을 기르고, 들에서는 벼농사를 짓는다."],"title":"일지 ⑤ — 노을군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#1','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C2',1,'mc','auto','지도에서 동서남북의 방향으로 나타낸 위치는 무엇인가요?',ARRAY['SO4-1-u1-X11']::text[],false,'{"seq":1,"concept":"SO4-1-u1-C2","difficulty":1,"kind":"mc","stem":"지도에서 동서남북의 방향으로 나타낸 위치는 무엇인가요?","options":[{"t":"방위","correct":true},{"t":"범례","mis":"SO4-1-u1-X11"},{"t":"축척","mis":"SO4-1-u1-X11"},{"t":"기호","mis":"SO4-1-u1-X11"}],"explanation":["동서남북이에요.","방향이에요.","방위예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
