INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#10','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C3',2,'mc','auto','사진보다 기호지도에서 장소를 빨리 찾을 수 있는 까닭은 무엇인가요?',ARRAY['SO4-1-u1-X04','SO4-1-u1-X03']::text[],false,'{"seq":10,"concept":"SO4-1-u1-C3","difficulty":2,"kind":"mc","stem":"사진보다 기호지도에서 장소를 빨리 찾을 수 있는 까닭은 무엇인가요?","options":[{"t":"약속된 기호로 장소를 간단히 나타냈기 때문이에요","correct":true},{"t":"사진이 더 단순하기 때문이에요","mis":"SO4-1-u1-X04"},{"t":"기호지도가 더 크기 때문이에요","mis":"SO4-1-u1-X03"},{"t":"사진에는 색이 없기 때문이에요","mis":"SO4-1-u1-X04"}],"explanation":["사진은 복잡해요.","기호는 간단해요.","빨리 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#11','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C4',2,'mc','auto','일지 ②에서 산 ㉯를 천천히 덜 힘들게 오르려면 어느 쪽 비탈로 가면 좋을까요?',ARRAY['SO4-1-u1-X14','SO4-1-u1-X13']::text[],false,'{"seq":11,"concept":"SO4-1-u1-C4","difficulty":2,"kind":"mc","stem":"일지 ②에서 산 ㉯를 천천히 덜 힘들게 오르려면 어느 쪽 비탈로 가면 좋을까요?","options":[{"t":"북쪽 비탈","correct":true},{"t":"남쪽 비탈","mis":"SO4-1-u1-X14"},{"t":"어느 쪽이나 같아요","mis":"SO4-1-u1-X14"},{"t":"산꼭대기부터","mis":"SO4-1-u1-X13"}],"explanation":["간격이 넓은 쪽이에요.","완만해요.","북쪽이에요."],"asset":{"type":"passage","lines":["산 ㉮ — 등고선 4겹, 가장 안쪽 원에 쓰인 숫자 400","산 ㉯ — 등고선 6겹, 가장 안쪽 원에 쓰인 숫자 600","산 ㉯ 북쪽 비탈 — 등고선 간격이 넓다","산 ㉯ 남쪽 비탈 — 등고선 간격이 좁다"],"title":"일지 ② — 두 산의 등고선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
