INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#13','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C6',2,'mc','auto','대동여지도가 오늘날 지도와 비슷한 점은 무엇인가요?',ARRAY['SO4-1-u1-X21']::text[],false,'{"seq":13,"concept":"SO4-1-u1-C6","difficulty":2,"kind":"mc","stem":"대동여지도가 오늘날 지도와 비슷한 점은 무엇인가요?","options":[{"t":"기호와 범례를 썼어요","correct":true},{"t":"인터넷으로 검색해요","mis":"SO4-1-u1-X21"},{"t":"길을 소리로 안내해요","mis":"SO4-1-u1-X21"},{"t":"사진으로 만들었어요","mis":"SO4-1-u1-X21"}],"explanation":["옛 지도예요.","기호가 있어요.","범례도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#14','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C8',2,'mc','auto','햇살시에서 보면 노을군은 햇살시의 어느 쪽에 있나요?',ARRAY['SO4-1-u1-X06']::text[],false,'{"seq":14,"concept":"SO4-1-u1-C8","difficulty":2,"kind":"mc","stem":"햇살시에서 보면 노을군은 햇살시의 어느 쪽에 있나요?","options":[{"t":"서쪽","correct":true},{"t":"동쪽","mis":"SO4-1-u1-X06"},{"t":"남쪽","mis":"SO4-1-u1-X06"},{"t":"북쪽","mis":"SO4-1-u1-X06"}],"explanation":["노을군 동쪽에 햇살시가 있어요.","거꾸로 봐요.","서쪽이에요."],"asset":{"type":"passage","lines":["노을군은 ○○도의 서쪽에 있고, 동쪽으로 햇살시와 맞닿아 있다.","노을군의 북쪽에는 높은 산이 있고, 남쪽에는 넓은 들이 있다.","강이 산에서 들을 지나 서쪽 바다로 흐른다.","산골 마을에서는 버섯을 기르고, 들에서는 벼농사를 짓는다."],"title":"일지 ⑤ — 노을군 소개"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#15','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C9',2,'mc','auto','인구 막대그래프의 막대가 해마다 짧아지면 무엇을 뜻하나요?',ARRAY['SO4-1-u1-X26','SO4-1-u1-X25']::text[],false,'{"seq":15,"concept":"SO4-1-u1-C9","difficulty":2,"kind":"mc","stem":"인구 막대그래프의 막대가 해마다 짧아지면 무엇을 뜻하나요?","options":[{"t":"인구가 줄고 있어요","correct":true},{"t":"인구가 늘고 있어요","mis":"SO4-1-u1-X26"},{"t":"인구가 그대로예요","mis":"SO4-1-u1-X26"},{"t":"면적이 넓어져요","mis":"SO4-1-u1-X25"}],"explanation":["막대가 짧아져요.","값이 작아져요.","줄고 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#16','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C10',2,'mc','auto','일지 ⑦에서 7월 강수량은 10월보다 얼마나 많나요?',ARRAY['SO4-1-u1-X26','SO4-1-u1-X27']::text[],false,'{"seq":16,"concept":"SO4-1-u1-C10","difficulty":2,"kind":"mc","stem":"일지 ⑦에서 7월 강수량은 10월보다 얼마나 많나요?","options":[{"t":"230 mm","correct":true},{"t":"280 mm","mis":"SO4-1-u1-X26"},{"t":"50 mm","mis":"SO4-1-u1-X26"},{"t":"230 °C","mis":"SO4-1-u1-X27"}],"explanation":["7월 280 mm 예요.","10월 50 mm 예요.","230 mm 많아요."],"asset":{"type":"passage","lines":["1월 — 기온 0 °C · 강수량 30 mm","4월 — 기온 12 °C · 강수량 90 mm","7월 — 기온 25 °C · 강수량 280 mm","10월 — 기온 15 °C · 강수량 50 mm"],"title":"일지 ⑦ — 노을군 기온과 강수량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#17','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C7',3,'mc','auto','일지 ①의 지도에서 강의 위치와 강을 나타낸 기호를 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-1-u1-X06','SO4-1-u1-X09','SO4-1-u1-X11']::text[],false,'{"seq":17,"concept":"SO4-1-u1-C7","difficulty":3,"kind":"mc","stem":"일지 ①의 지도에서 강의 위치와 강을 나타낸 기호를 바르게 짝지은 것은 무엇인가요?","options":[{"t":"학교의 남쪽 — 파란 선","correct":true},{"t":"학교의 북쪽 — 파란 선","mis":"SO4-1-u1-X06"},{"t":"학교의 남쪽 — 초록 세모","mis":"SO4-1-u1-X09"},{"t":"학교의 동쪽 — 제비 모양","mis":"SO4-1-u1-X11"}],"explanation":["아래쪽이에요.","파란 선이에요.","함께 골라요."],"asset":{"type":"passage","lines":["방위표 — 화살표가 지도의 위쪽을 가리킨다.","가운데 — 은빛 초등학교(깃발)","학교의 위쪽 — 산(초록 세모, 등고선 가장 안쪽에 300)","학교의 오른쪽 — 병원(＋)","학교의 아래쪽 — 강(파란 선)","학교의 왼쪽 아래 — 우체국(제비 모양)","축척 막대 — 1 cm = 2 km"],"title":"일지 ① — 은빛마을 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#18','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C4',3,'mc','auto','산 ㉮와 산 ㉯를 위에서 내려다본 등고선 모형을 옆에서 보면 무엇을 알 수 있나요?',ARRAY['SO4-1-u1-X12','SO4-1-u1-X11']::text[],false,'{"seq":18,"concept":"SO4-1-u1-C4","difficulty":3,"kind":"mc","stem":"산 ㉮와 산 ㉯를 위에서 내려다본 등고선 모형을 옆에서 보면 무엇을 알 수 있나요?","options":[{"t":"두 산의 높낮이","correct":true},{"t":"두 산의 이름","mis":"SO4-1-u1-X12"},{"t":"두 산 사이의 실제 거리","mis":"SO4-1-u1-X11"},{"t":"두 산에 사는 사람 수","mis":"SO4-1-u1-X12"}],"explanation":["옆에서 봐요.","높이가 보여요.","높낮이예요."],"asset":{"type":"passage","lines":["산 ㉮ — 등고선 4겹, 가장 안쪽 원에 쓰인 숫자 400","산 ㉯ — 등고선 6겹, 가장 안쪽 원에 쓰인 숫자 600","산 ㉯ 북쪽 비탈 — 등고선 간격이 넓다","산 ㉯ 남쪽 비탈 — 등고선 간격이 좁다"],"title":"일지 ② — 두 산의 등고선"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#19','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C6',3,'mc','auto','대동여지도에서 산의 크기와 높이를 짐작하게 한 방법과 오늘날 등고선 지도의 방법을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-1-u1-X21','SO4-1-u1-X11']::text[],false,'{"seq":19,"concept":"SO4-1-u1-C6","difficulty":3,"kind":"mc","stem":"대동여지도에서 산의 크기와 높이를 짐작하게 한 방법과 오늘날 등고선 지도의 방법을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"선의 굵기 — 높이가 같은 곳을 이은 선","correct":true},{"t":"글자 크기 — 높이가 같은 곳을 이은 선","mis":"SO4-1-u1-X21"},{"t":"선의 굵기 — 실제 거리를 줄인 막대","mis":"SO4-1-u1-X11"},{"t":"사진 — 범례","mis":"SO4-1-u1-X21"}],"explanation":["대동여지도는 선의 굵기예요.","등고선은 같은 높이를 이어요.","짝을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#20','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C11',3,'mc','auto','지리 정보를 조사할 때 인구와 면적을 찾기에 알맞은 자료는 무엇인가요?',ARRAY['SO4-1-u1-X30']::text[],false,'{"seq":20,"concept":"SO4-1-u1-C11","difficulty":3,"kind":"mc","stem":"지리 정보를 조사할 때 인구와 면적을 찾기에 알맞은 자료는 무엇인가요?","options":[{"t":"통계 자료","correct":true},{"t":"기상 자료","mis":"SO4-1-u1-X30"},{"t":"관광 엽서","mis":"SO4-1-u1-X30"},{"t":"친구의 일기","mis":"SO4-1-u1-X30"}],"explanation":["사람 수와 넓이예요.","수를 모은 자료예요.","통계 자료예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#21','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C9',3,'mc','auto','일지 ⑥에서 노을군의 면적은 햇살시의 몇 배쯤인가요?',ARRAY['SO4-1-u1-X26','SO4-1-u1-X25']::text[],false,'{"seq":21,"concept":"SO4-1-u1-C9","difficulty":3,"kind":"mc","stem":"일지 ⑥에서 노을군의 면적은 햇살시의 몇 배쯤인가요?","options":[{"t":"4배쯤","correct":true},{"t":"2배쯤","mis":"SO4-1-u1-X26"},{"t":"같아요","mis":"SO4-1-u1-X25"},{"t":"5분의 1쯤","mis":"SO4-1-u1-X26"}],"explanation":["노을군 450 km² 예요.","햇살시 120 km² 예요.","4배쯤이에요."],"asset":{"type":"passage","lines":["지역 — 면적 — 인구","노을군 — 450 km² — 6만 명","햇살시 — 120 km² — 30만 명","초록군 — 250 km² — 9만 명"],"title":"일지 ⑥ — 세 지역의 면적과 인구"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#22','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C12',3,'mc','auto','일지 ⑨에서 노을군과 초록군의 칸 수 차이는 얼마인가요?',ARRAY['SO4-1-u1-X32']::text[],false,'{"seq":22,"concept":"SO4-1-u1-C12","difficulty":3,"kind":"mc","stem":"일지 ⑨에서 노을군과 초록군의 칸 수 차이는 얼마인가요?","options":[{"t":"1칸","correct":true},{"t":"2칸","mis":"SO4-1-u1-X32"},{"t":"같아요","mis":"SO4-1-u1-X32"},{"t":"5칸","mis":"SO4-1-u1-X32"}],"explanation":["노을군 5칸이에요.","초록군 4칸이에요.","1칸 차이예요."],"asset":{"type":"passage","lines":["1 1 2 2","1 1 2 2","1 3 3 2","4 3 3 2","범례 — 1 노을군 · 2 햇살시 · 3 초록군 · 4 달빛군","(지도 위쪽이 북쪽 · 칸 하나의 넓이는 모두 같다)"],"title":"일지 ⑨ — 픽셀 지도"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#23','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C6',4,'essay','teacher','일지 ④의 상황 가운데 두 가지를 골라 어떤 지도를 쓸지 쓰고, 그 지도가 그 상황에 알맞은 까닭을 쓰세요.','{}'::text[],false,'{"seq":23,"concept":"SO4-1-u1-C6","difficulty":4,"kind":"essay","stem":"일지 ④의 상황 가운데 두 가지를 골라 어떤 지도를 쓸지 쓰고, 그 지도가 그 상황에 알맞은 까닭을 쓰세요.","answer_guide":{"answer":"예: ㉡ 다른 고장의 볼거리를 찾을 때는 관광 안내도를 써요. 관광지가 어디에 있는지 알려 주기 때문이에요. ㉣ 친구에게 우리 집 가는 길을 알려 줄 때는 약도를 그려 줘요. 목적지까지 가는 길을 간단히 보여 주기 때문이에요.","scoring_points":["상황 두 가지를 골랐는가","알맞은 지도를 골랐는가","지도가 알려 주는 정보로 까닭을 썼는가"]},"explanation":["상황을 골라요.","지도를 골라요.","까닭을 써요."],"asset":{"type":"passage","lines":["㉠ 할머니 댁에 처음 자동차로 간다.","㉡ 다른 고장의 볼거리를 찾는다.","㉢ 버스를 갈아타고 체육관에 간다.","㉣ 친구에게 우리 집 가는 길을 간단히 알려 준다."],"title":"일지 ④ — 지도가 필요한 상황"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#24','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C10',4,'essay','teacher','일지 ⑦을 보고 노을군에서 7월과 1월에 각각 준비하면 좋을 일을 기온과 강수량을 근거로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-1-u1-C10","difficulty":4,"kind":"essay","stem":"일지 ⑦을 보고 노을군에서 7월과 1월에 각각 준비하면 좋을 일을 기온과 강수량을 근거로 쓰세요.","answer_guide":{"answer":"예: 7월은 기온이 25 °C 로 덥고 비가 280 mm 로 가장 많이 와서 우산을 챙기고 물이 잘 빠지는지 살펴요. 1월은 기온이 0 °C 로 춥고 비가 30 mm 로 적어서 두꺼운 옷을 입고 메마른 날씨에 불조심을 해요.","scoring_points":["7월 준비를 썼는가","1월 준비를 썼는가","기온과 강수량을 근거로 들었는가"]},"explanation":["7월을 봐요.","1월을 봐요.","근거를 써요."],"asset":{"type":"passage","lines":["1월 — 기온 0 °C · 강수량 30 mm","4월 — 기온 12 °C · 강수량 90 mm","7월 — 기온 25 °C · 강수량 280 mm","10월 — 기온 15 °C · 강수량 50 mm"],"title":"일지 ⑦ — 노을군 기온과 강수량"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_soc_u1_review_d#25','soc',4,1,'u1','','g4_1_soc_u1_review_d','unit_review','SO4-1-u1-C11',4,'essay','teacher','1단원에서 배운 지도 요소와 지리 정보를 써서, 우리 지역을 처음 온 사람에게 소개하는 안내문을 세 문장으로 쓰세요. (지역 이름은 ○○로 써도 돼요)','{}'::text[],false,'{"seq":25,"concept":"SO4-1-u1-C11","difficulty":4,"kind":"essay","stem":"1단원에서 배운 지도 요소와 지리 정보를 써서, 우리 지역을 처음 온 사람에게 소개하는 안내문을 세 문장으로 쓰세요. (지역 이름은 ○○로 써도 돼요)","answer_guide":{"answer":"예: ○○시는 ○○도의 북쪽에 있고, 지도의 방위표로 보면 동쪽에 높은 산이 있어요. 등고선을 보면 동쪽 산은 경사가 급하니 서쪽 길로 오르세요. 인구가 많아 공원과 도서관이 곳곳에 있고, 여름에는 비가 많이 오니 우산을 챙기세요.","scoring_points":["지도 요소를 하나 이상 썼는가","지리 정보를 두 가지 이상 썼는가","처음 온 사람에게 도움이 되게 썼는가"]},"explanation":["지도 요소를 써요.","지리 정보를 써요.","안내문으로 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
